class CoarseGridAxisItem(pg.AxisItem):
    def tickSpacing(self, minVal, maxVal, size):
        tick_levels = super().tickSpacing(minVal, maxVal, size)
        return [(spacing * GRID_SPACING_FACTOR, offset) for spacing, offset in tick_levels]


class WorkspaceTabBar(QTabBar):
    """Tab bar that places a "+" button immediately after the last tab,
    sliding rightward as new tabs are added (browser-style)."""
    addClicked = Signal()

    # Minimum width a single tab can shrink to under crowding (2026-05-15).
    # Picked so "Tab18"-style short labels remain readable while leaving room
    # for the close (✕) button. Must align with CSS `min-width` for the same
    # selector (see change_theme()).
    _MIN_TAB_WIDTH_PX = 36
    # Horizontal margin we reserve to the right of the last tab so the [+]
    # add-button never gets visually overlapped by tab geometry.
    _ADD_BUTTON_RESERVE_PX = 12

    def __init__(self, parent=None):
        # 분석창 탭바 초기화. QPushButton("+") 의 글자를 바꾸면 추가 버튼 라벨이,
        # setFixedSize(30, 25) 의 픽셀 값을 키우면 + 버튼이 커집니다.
        # setFont 의 14 를 키우면 + 글자가 굵고 크게 그려지고, setToolTip 문구를
        # 바꾸면 마우스 호버 시 뜨는 안내가 바뀝니다.
        super().__init__(parent)
        button_parent = parent if isinstance(parent, QWidget) else self
        self._add_button = QPushButton("+", button_parent)
        self._add_button.setObjectName("newTabButton")
        self._add_button.setFixedSize(30, 25)
        self._add_button.setFlat(True)
        self._add_button.setFont(QFont("", 14, QFont.Bold))
        self._add_button.setCursor(Qt.PointingHandCursor)
        self._add_button.setToolTip("분석창 추가")
        self._add_button.clicked.connect(self.addClicked)
        self.setExpanding(False)
        self.setUsesScrollButtons(True)
        self.setDrawBase(False)
        self.setElideMode(Qt.ElideRight)

    def tabSizeHint(self, index):
        # Browser-style auto-shrink (2026-05-15): when natural tab widths
        # would overflow into the [+] button area, redistribute the
        # available width equally with `_MIN_TAB_WIDTH_PX` as the floor.
        # When there is plenty of space, fall back to the base hint so
        # long-label tabs like "분석:foo.ulg | Com Link" can stay wide.
        #
        # NOTE: we must size against the PARENT QTabWidget's width, not
        # self.width(). With setExpanding(False) the QTabBar's own width is
        # the sum of its tabSizeHints — so using self.width() creates a
        # feedback loop where the first shrunk hint keeps the bar narrow
        # forever (it never expands back even when there's plenty of room).
        base = super().tabSizeHint(index)
        n = self.count()
        if n <= 0:
            return base
        button = getattr(self, "_add_button", None)
        reserved = (int(button.width()) + self._ADD_BUTTON_RESERVE_PX) if button is not None else 0
        parent = self.parentWidget()
        parent_w = int(parent.width()) if parent is not None else 0
        bar_w = int(self.width())
        # Use the larger of the two so the bar can recover after a shrink.
        available = max(0, max(parent_w, bar_w) - reserved)
        if available <= 0:
            return base
        total_natural = 0
        for i in range(n):
            total_natural += super().tabSizeHint(i).width()
        if total_natural <= available:
            return base
        even_w = max(self._MIN_TAB_WIDTH_PX, available // n)
        return QSize(min(base.width(), even_w), base.height())

    def add_button(self):
        # 외부에서 + 버튼 객체를 가져갈 때 씀 보통 수정할 필요 없음.
        return self._add_button

    def _layout_add_button(self):
        # + 버튼을 마지막 탭 바로 오른쪽에 배치. last_rect.right() + 2 의 2 를
        # 키우면 마지막 탭과 + 버튼 사이 간격이 벌어짐
        # 직접 수정할 필요는 없음.
        button = getattr(self, "_add_button", None)
        if button is None:
            return
        host = button.parentWidget() if button.parentWidget() is not None else self
        tab_bar_geom = self.geometry()
        # Align bottom-edge of the button with bottom-edge of the tab so the
        # "+" sits on the same baseline as Tab1/Tab2 (browser-style).
        y = tab_bar_geom.y() + max(0, self.height() - button.height())
        if self.count() > 0:
            last_rect = self.tabRect(self.count() - 1)
            x = tab_bar_geom.x() + last_rect.right() + 2
        else:
            x = tab_bar_geom.x() + 4
        max_x = max(0, host.width() - button.width() - 4)
        button.move(min(x, max_x), y)
        button.raise_()

    def _extra_button_width(self):
        # 탭바 sizeHint 가 + 버튼 영역까지 확보하도록 너비를 더해주는 헬퍼.
        # 끝의 + 8 을 키우면 + 버튼 좌우 여유 공간이 늘어납니다.
        button = getattr(self, "_add_button", None)
        if button is None:
            return 0
        return int(button.width()) + 8

    def sizeHint(self):
        hint = super().sizeHint()
        hint.setWidth(hint.width() + self._extra_button_width())
        return hint

    def minimumSizeHint(self):
        hint = super().minimumSizeHint()
        hint.setWidth(hint.width() + self._extra_button_width())
        return hint

    def resizeEvent(self, event):
        # 창 크기가 바뀔 때마다 + 버튼 위치를 다시 계산. 자동 호출되니
        # 보통 수정할 필요 없음.
        super().resizeEvent(event)
        self._layout_add_button()

    def tabLayoutChange(self):
        # 탭이 추가/삭제/순서 변경될 때 + 버튼을 다시 자리잡게 함. 자동
        # 호출되니 보통 수정할 필요 없음.
        super().tabLayoutChange()
        self._layout_add_button()

    # Right-edge gap for the close button: wraps a custom close QPushButton in a
    # QWidget container with right-side contents margin. PySide6's default
    # QTabBar::close-button ignores CSS margin/padding for positioning, so this
    # is the only reliable way to push the X icon away from the tab's right edge.
    _CLOSE_BUTTON_RIGHT_GAP_PX = 6

    def tabInserted(self, index):
        # 탭이 새로 추가될 때 호출. QPushButton("✕") 의 글자를 바꾸면 닫기
        # 버튼 모양이, setFixedSize(16, 16) 의 픽셀 값을 키우면 닫기 버튼이
        # 커집니다. _CLOSE_BUTTON_RIGHT_GAP_PX 를 늘리면 ✕ 가 탭 오른쪽
        # 끝에서 더 안쪽으로 들어옵니다.
        super().tabInserted(index)
        wrapper = QWidget(self)
        wrapper.setAttribute(Qt.WA_TransparentForMouseEvents, False)
        layout = QHBoxLayout(wrapper)
        layout.setContentsMargins(0, 0, self._CLOSE_BUTTON_RIGHT_GAP_PX, 0)
        layout.setSpacing(0)
        btn = QPushButton("✕", wrapper)
        btn.setObjectName("tabCloseButton")
        btn.setFixedSize(12, 12)
        btn.setFlat(True)
        btn.setCursor(Qt.PointingHandCursor)
        btn.clicked.connect(lambda _checked=False, b=btn: self._emit_close_for_button(b))
        layout.addWidget(btn)
        self.setTabButton(index, QTabBar.RightSide, wrapper)
        self._layout_add_button()

    def _emit_close_for_button(self, button):
        # 사용자가 ✕ 닫기 버튼을 눌렀을 때 해당 탭 인덱스를 찾아 닫기
        # 시그널을 발생시킵니다. 내부 라우팅이므로 보통 수정할 필요 없음.
        for i in range(self.count()):
            wrapper = self.tabButton(i, QTabBar.RightSide)
            if wrapper is None:
                continue
            for child in wrapper.findChildren(QPushButton):
                if child is button:
                    self.tabCloseRequested.emit(i)
                    return

    def tabRemoved(self, index):
        # 탭이 닫힐 때 + 버튼 위치 재정렬. 자동 호출되니 보통 수정 X.
        super().tabRemoved(index)
        self._layout_add_button()

    # 로그별 코너 마커 (2026-05-21). 좌상단 7×7 색띠로 어느 로그를 분석
    # 중인지 한눈에 식별. 표준 QStyle 페인트 순서를 분해해서
    # background → marker → text 로 그리므로 텍스트가 항상 마커 위에
    # 그려져 가려질 가능성 없음.
    LOG_MARKER_SIZE = 7
    LOG_MARKER_INSET_X = 3
    LOG_MARKER_INSET_Y = 2

    def paintEvent(self, event):
        # 탭 좌상단에 작은 색상 마커(어느 로그인지 식별) 를 그리는 커스텀
        # 페인트. LOG_MARKER_SIZE / INSET_X / INSET_Y 상수를 키우면 마커가
        # 더 크게/안쪽으로 들어와 그려집니다. 호출은 자동 — 함수 본문은
        # 보통 수정 X.
        main_window = self.window()
        get_color_text = getattr(main_window, "_log_tab_color_for_text", None)
        get_color_ws = getattr(main_window, "_log_tab_color_for_workspace", None)
        if not callable(get_color_text) and not callable(get_color_ws):
            super().paintEvent(event)
            return
        # The tab bar's parent IS the QTabWidget — use it to resolve the
        # workspace widget mounted at each tab index.
        tab_widget = self.parent()
        try:
            painter = QStylePainter(self)
            try:
                for i in range(self.count()):
                    opt = QStyleOptionTab()
                    self.initStyleOption(opt, i)
                    color = None
                    # 1) Try tab-text path (Analysis / Auto Panels case).
                    if callable(get_color_text):
                        c = get_color_text(self.tabText(i))
                        if isinstance(c, QColor) and c.isValid():
                            color = c
                    # 2) Fallback: inspect the workspace's plotted signals
                    #    so drag-and-drop tabs (still named "Tab1") still
                    #    get marked by whichever log they actually show.
                    #    (2026-05-21)
                    if color is None and callable(get_color_ws) and tab_widget is not None:
                        try:
                            workspace_widget = tab_widget.widget(i)
                        except Exception:
                            workspace_widget = None
                        if workspace_widget is not None:
                            c = get_color_ws(workspace_widget)
                            if isinstance(c, QColor) and c.isValid():
                                color = c
                    if color is None:
                        painter.drawControl(QStyle.CE_TabBarTab, opt)
                        continue
                    # Split paint so the marker sits BETWEEN background and
                    # text. Text drawn last → never gets covered by marker
                    # even when a long title reaches into the corner.
                    painter.drawControl(QStyle.CE_TabBarTabShape, opt)
                    rect = opt.rect
                    marker = QRect(
                        rect.left() + self.LOG_MARKER_INSET_X,
                        rect.top() + self.LOG_MARKER_INSET_Y,
                        self.LOG_MARKER_SIZE,
                        self.LOG_MARKER_SIZE,
                    )
                    painter.fillRect(marker, color)
                    painter.drawControl(QStyle.CE_TabBarTabLabel, opt)
            finally:
                painter.end()
        except Exception:
            # Fail-safe: if anything in custom paint blows up, fall back
            # to Qt default so the tabs never end up unreadable.
            super().paintEvent(event)

    def showEvent(self, event):
        # 탭바가 처음 화면에 표시될 때 + 버튼 위치 초기 배치. 자동 호출.
        super().showEvent(event)
        self._layout_add_button()


class _PaintSplitAccumulator:
    # Instrumentation-3: per-paintEvent internal split. When active, wrapped
    # pg item paint methods feed durations into this accumulator so a single
    # paintEvent's total duration can be broken into curve / axis / overlay /
    # scene-other components. Reset/stop is driven by _TimedPlotWidget.
    __slots__ = ("active", "curve_ms", "axis_ms", "overlay_ms",
                 "curve_count", "axis_count", "overlay_count")

    def __init__(self):
        self.active = False
        self.curve_ms = 0.0
        self.axis_ms = 0.0
        self.overlay_ms = 0.0
        self.curve_count = 0
        self.axis_count = 0
        self.overlay_count = 0

    def reset(self):
        self.active = True
        self.curve_ms = 0.0
        self.axis_ms = 0.0
        self.overlay_ms = 0.0
        self.curve_count = 0
        self.axis_count = 0
        self.overlay_count = 0

    def stop(self):
        self.active = False

    def snapshot(self):
        return (self.curve_ms, self.axis_ms, self.overlay_ms,
                self.curve_count, self.axis_count, self.overlay_count)


_PAINT_SPLIT_ACC = _PaintSplitAccumulator()


def _install_paint_split_hooks():
    # Wrap pyqtgraph item paint methods so that, while the accumulator is
    # active, each call's wall-clock duration is bucketed by item type. When
    # inactive the wrapper is a single branch + call (fast path). PERF_DEBUG-
    # gated, idempotent, and fully exception-safe. Zero functional change.
    if not PERF_DEBUG_ENABLED:
        return
    if getattr(_install_paint_split_hooks, "_installed", False):
        return
    _install_paint_split_hooks._installed = True

    def _wrap(cls, bucket):
        try:
            orig = getattr(cls, "paint", None)
            if orig is None or getattr(orig, "_perf_split_wrapped", False):
                return

            def wrapped(self, *args, **kwargs):
                if not _PAINT_SPLIT_ACC.active:
                    return orig(self, *args, **kwargs)
                t0 = time.perf_counter()
                try:
                    return orig(self, *args, **kwargs)
                finally:
                    try:
                        dur = (time.perf_counter() - t0) * 1000.0
                        if bucket == "curve":
                            _PAINT_SPLIT_ACC.curve_ms += dur
                            _PAINT_SPLIT_ACC.curve_count += 1
                        elif bucket == "axis":
                            _PAINT_SPLIT_ACC.axis_ms += dur
                            _PAINT_SPLIT_ACC.axis_count += 1
                        else:
                            _PAINT_SPLIT_ACC.overlay_ms += dur
                            _PAINT_SPLIT_ACC.overlay_count += 1
                    except Exception:
                        pass

            wrapped._perf_split_wrapped = True
            cls.paint = wrapped
        except Exception:
            pass

    for cls_attr, bucket in (
        ("PlotCurveItem", "curve"),
        ("AxisItem", "axis"),
        ("InfiniteLine", "overlay"),
        ("ScatterPlotItem", "overlay"),
    ):
        try:
            cls = getattr(pg, cls_attr, None)
            if cls is not None:
                _wrap(cls, bucket)
        except Exception:
            pass


class _TimedPlotWidget(pg.PlotWidget):
    # Diagnostic subclass: when ``_paint_recorder`` is attached, forwards
    # paintEvent start time + duration to the recorder. No behavioural
    # change whatsoever; recorder defaults to None (fast pass-through).
    _OPENGL_LOGGED = False

    def __init__(self, *args, **kwargs):
        # 그래프 위젯 + 페인트 시간 측정 훅 초기화. 평소엔 추가 기능 없이
        # 일반 pg.PlotWidget 처럼 동작 — PERF_DEBUG_ENABLED 가 켜져 있을
        # 때만 paint 분해 통계를 수집합니다. 보통 직접 수정 X.
        super().__init__(*args, **kwargs)
        self._paint_recorder = None
        if PERF_DEBUG_ENABLED:
            try:
                _install_paint_split_hooks()
            except Exception:
                pass
        if PERF_DEBUG_ENABLED and not _TimedPlotWidget._OPENGL_LOGGED:
            _TimedPlotWidget._OPENGL_LOGGED = True
            try:
                vp = self.viewport()
                vp_type = type(vp).__name__
                vp_module = type(vp).__module__
                _perf_debug_print(
                    f"opengl_check viewport_type={vp_module}.{vp_type} useOpenGL={pg.getConfigOption('useOpenGL')}"
                )
            except Exception:
                pass

    def paintEvent(self, ev):
        # 그래프 한 프레임 그리기. 그림 자체는 부모(pg.PlotWidget) 가 그리고
        # 본 함수는 시간 측정만 추가. 보통 수정 X.
        recorder = self._paint_recorder
        if recorder is None:
            return super().paintEvent(ev)
        started = time.perf_counter()
        split_active = False
        if PERF_DEBUG_ENABLED:
            try:
                _PAINT_SPLIT_ACC.reset()
                split_active = True
            except Exception:
                split_active = False
        try:
            super().paintEvent(ev)
        finally:
            try:
                duration_ms = (time.perf_counter() - started) * 1000.0
                split = None
                if split_active:
                    try:
                        split = _PAINT_SPLIT_ACC.snapshot()
                    except Exception:
                        split = None
                    finally:
                        try:
                            _PAINT_SPLIT_ACC.stop()
                        except Exception:
                            pass
                try:
                    recorder(started, duration_ms, split)
                except TypeError:
                    recorder(started, duration_ms)
            except Exception:
                pass


def _create_coarse_grid_plot_widget(*args, **kwargs):
    # 그리드(격자) 간격을 굵게 한 커스텀 축 가진 그래프 위젯 생성 헬퍼.
    # CoarseGridAxisItem 클래스의 tickSpacing/setTickFont 등을 바꾸면 모든
    # 그래프의 X/Y 축 눈금 모양이 바뀝니다.
    axis_items = kwargs.pop("axisItems", None)
    if axis_items is None:
        axis_items = {
            "bottom": CoarseGridAxisItem("bottom"),
            "left": CoarseGridAxisItem("left"),
        }
    return _TimedPlotWidget(*args, axisItems=axis_items, **kwargs)


def _xrange_debug_print(message):
    if XRANGE_DEBUG_ENABLED:
        print(f"[XRANGE_DEBUG] {message}")


_PERF_DEBUG_LOG_DIR = os.path.abspath(
    os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "runtime", "logs")
)
_PERF_DEBUG_LOG_FILE = None
_PERF_DEBUG_LOG_HANDLE = None
_PERF_DEBUG_LOG_FAILED = False


def _perf_debug_log_handle():
    # (2026-10-03) Lazy-open an append-mode log file under runtime/logs/.
    # One file per process: perf_<YYYYMMDD_HHMMSS>_pid<pid>.log.
    # Fully guarded so a file-system failure cannot affect runtime behaviour.
    global _PERF_DEBUG_LOG_FILE, _PERF_DEBUG_LOG_HANDLE, _PERF_DEBUG_LOG_FAILED
    if not PERF_DEBUG_ENABLED or _PERF_DEBUG_LOG_FAILED:
        return None
    if _PERF_DEBUG_LOG_HANDLE is not None:
        return _PERF_DEBUG_LOG_HANDLE
    try:
        os.makedirs(_PERF_DEBUG_LOG_DIR, exist_ok=True)
        if _PERF_DEBUG_LOG_FILE is None:
            stamp = time.strftime("%Y%m%d_%H%M%S")
            _PERF_DEBUG_LOG_FILE = os.path.join(
                _PERF_DEBUG_LOG_DIR, f"perf_{stamp}_pid{os.getpid()}.log"
            )
        _PERF_DEBUG_LOG_HANDLE = open(_PERF_DEBUG_LOG_FILE, "a", encoding="utf-8", buffering=1)
        header = (
            f"# session_started={time.strftime('%Y-%m-%dT%H:%M:%S')} "
            f"pid={os.getpid()} perf_debug=1\n"
        )
        _PERF_DEBUG_LOG_HANDLE.write(header)
        _PERF_DEBUG_LOG_HANDLE.flush()
        try:
            print(f"[PERF_DEBUG] log_file={_PERF_DEBUG_LOG_FILE}")
        except Exception:
            pass
    except Exception:
        _PERF_DEBUG_LOG_FAILED = True
        _PERF_DEBUG_LOG_HANDLE = None
    return _PERF_DEBUG_LOG_HANDLE


def _perf_debug_print(message):
    if not PERF_DEBUG_ENABLED:
        return
    line = f"[PERF_DEBUG] {message}"
    try:
        print(line)
    except Exception:
        pass
    handle = _perf_debug_log_handle()
    if handle is not None:
        try:
            handle.write(line + "\n")
        except Exception:
            pass


def _perf_debug_block(title, rows):
    if not PERF_DEBUG_ENABLED:
        return
    _perf_debug_print(f"{title}:")
    for label, value in rows:
        _perf_debug_print(f"  - {label}: {value}")


def _perf_debug_top_entries(entries, limit=3):
    if not entries:
        return "-"

    ranked = sorted(entries, key=lambda item: float(item.get("total_ms", 0.0)), reverse=True)[:limit]
    formatted = []
    for item in ranked:
        label = str(item.get("label", "-")).strip() or "-"
        try:
            total_ms = float(item.get("total_ms", 0.0))
        except Exception:
            total_ms = 0.0
        flags = []
        if "ok" in item:
            flags.append("ok" if item.get("ok") else "fail")
        if item.get("is_fft"):
            flags.append("fft")
        suffix = f" ({', '.join(flags)})" if flags else ""
        detail_parts = []
        for key, short_label in (
            ("curve_create_ms", "curve"),
            ("legend_ms", "legend"),
            ("post_ui_ms", "post"),
        ):
            if key not in item:
                continue
            try:
                detail_value = float(item.get(key, 0.0))
            except Exception:
                detail_value = 0.0
            detail_parts.append(f"{short_label}={detail_value:.3f}ms")
        detail_suffix = f" [{', '.join(detail_parts)}]" if detail_parts else ""
        formatted.append(f"{label}={total_ms:.3f}ms{suffix}{detail_suffix}")
    return "; ".join(formatted) if formatted else "-"

