class FileDropWidget(QLabel):
    filesDropped = Signal(list) 

    def __init__(self):
        # 파일 드롭 위젯 초기화. apply_theme() 의 색·테두리를 그대로 입혀
        # 화면에 표시합니다.
        super().__init__()
        self._supported_format_summary = supported_source_summary()
        # 파일을 올리기 전 평소 보이는 안내 문구. 따옴표 안 텍스트를 바꾸면
        # 화면 안내 문구가 바뀝니다.
        self.setText(self.idle_text())
        self.setAlignment(Qt.AlignCenter)
        self.setAcceptDrops(True)
        self.apply_theme()

    def idle_text(self, heading="Log Data Upload"):
        return f"{heading}\n({self._supported_format_summary})"

    def apply_theme(self):
        # 드롭 영역 색·테두리·둥근 모서리 정의. background-color 를 바꾸면
        # 평소 배경색이, :hover 블록의 색을 바꾸면 마우스 올렸을 때 색이
        # 바뀝니다. border-radius 픽셀을 키우면 모서리가 더 둥글어집니다.
        self.setStyleSheet("""
            QLabel { background-color: #f0f0f0; color: #555555; border: 1px dashed #cccccc; border-radius: 5px; padding: 8px; font-weight: bold; }
            QLabel:hover { background-color: #e0e0e0; border-color: #1A2D57; color: black; }
        """)

    def dragEnterEvent(self, event):
        # 드래그된 파일이 위젯 영역 안으로 들어왔을 때 호출.
        event.setDropAction(Qt.CopyAction)
        event.accept()
        # 파일을 끌고 있을 때 위젯에 표시되는 임시 문구. 따옴표 안을 바꾸면
        # 드래그 중 안내가 바뀝니다.
        self.setText(" Drop supported log files here ")

    def dragMoveEvent(self, event):
        # 드래그된 파일이 위젯 위에서 움직일 때마다 호출. 보통 수정 X.
        event.setDropAction(Qt.CopyAction)
        event.accept()

    def dropEvent(self, event):
        # (2026-10-03) reader registry가 지원하는 파일과 ROS2 bag 폴더만 전달합니다.
        valid_files = self._extract_log_sources(event.mimeData())
        # 파일을 놓은 직후 다시 보이는 기본 문구. 따옴표 안을 바꾸면 드롭
        # 완료 후 안내가 바뀝니다.
        self.setText(self.idle_text("Drop log files here"))
        if valid_files:
            event.setDropAction(Qt.CopyAction)
            event.accept()
            self.filesDropped.emit(valid_files)
        else:
            event.ignore()
            self.setText("Unsupported log format.\nPlease try again.")
            try:
                mime_data = event.mimeData()
                formats = ", ".join(mime_data.formats()) if mime_data else ""
                sample_text = (mime_data.text() or "").strip()[:160] if mime_data else ""
                if PERF_DEBUG_ENABLED:
                    print(f"[DND][FileDropWidget] no supported log extracted | formats=[{formats}] | text='{sample_text}'")
            except Exception:
                pass

    def mousePressEvent(self, event):
        # 파일 선택 창 필터는 reader registry에서 생성해 새 포맷 추가 시 함께 확장됩니다.
        file_paths, _ = QFileDialog.getOpenFileNames(
            self,
            "로그 파일 선택",
            "",
            log_file_dialog_filter(),
        )
        if file_paths:
            supported_paths = [path for path in file_paths if is_supported_log_source(path)]
            if supported_paths:
                self.filesDropped.emit(supported_paths)
            else:
                self.setText("Unsupported log format.\nPlease try again.")

    @staticmethod
    def _extract_log_sources(mime_data):
        if not mime_data:
            return []

        candidates = []

        if mime_data.hasUrls():
            for url in mime_data.urls():
                local_path = url.toLocalFile()
                if not local_path:
                    raw_url = (url.toString(QUrl.FullyDecoded) or "").strip()
                    if raw_url.lower().startswith("file://"):
                        local_path = QUrl(raw_url).toLocalFile()
                    elif raw_url:
                        local_path = raw_url
                if local_path:
                    candidates.append(local_path)

        if mime_data.hasText():
            for raw_line in (mime_data.text() or "").splitlines():
                line = raw_line.strip().strip('"').strip("'")
                if not line:
                    continue
                if line.lower().startswith("file://"):
                    as_local = QUrl(line).toLocalFile()
                    if as_local:
                        line = as_local
                candidates.append(line)

        # Windows Explorer fallback: parse native filename MIME payload.
        for fmt in mime_data.formats():
            if "FileNameW" not in fmt and "FileName" not in fmt:
                continue
            raw = bytes(mime_data.data(fmt))
            if not raw:
                continue
            decoded = ""
            try:
                decoded = raw.decode("utf-16le", errors="ignore")
            except Exception:
                try:
                    decoded = raw.decode("utf-8", errors="ignore")
                except Exception:
                    decoded = ""
            if not decoded:
                continue
            for piece in re.split(r"\x00+", decoded):
                p = piece.strip().strip('"').strip("'")
                if not p:
                    continue
                if p.lower().startswith("file://"):
                    as_local = QUrl(p).toLocalFile()
                    if as_local:
                        p = as_local
                candidates.append(p)

        valid_files = []
        for path in candidates:
            norm_path = os.path.normpath(path.strip())
            # Some drag sources provide '/C:/path/file.ext' form on Windows.
            if re.match(r"^/[A-Za-z]:[\\/]", norm_path):
                norm_path = norm_path[1:]
            if is_supported_log_source(norm_path):
                valid_files.append(norm_path)

        # Keep order while removing duplicates.
        return list(dict.fromkeys(valid_files))

    # 기존 내부 호출과 저장된 Qt signal 연결을 깨지 않기 위한 호환 별칭.
    _extract_ulg_files = _extract_log_sources

    @staticmethod
    def _has_file_like_payload(mime_data):
        if not mime_data:
            return False
        if mime_data.hasUrls():
            return True
        if any(("FileNameW" in fmt or "FileName" in fmt) for fmt in mime_data.formats()):
            return True
        if FileDropWidget._extract_log_sources(mime_data):
            return True
        if mime_data.hasText():
            sample = (mime_data.text() or "").lower()
            if any(suffix in sample for suffix in supported_source_extensions()) and (
                "file://" in sample or "\\" in sample or "/" in sample
            ):
                return True
        return False


def _metadata_value_to_text(value):
    if value is None:
        return ""
    if isinstance(value, bytes):
        for enc in ("utf-8", "latin-1"):
            try:
                return value.decode(enc, errors="replace")
            except Exception:
                continue
        return repr(value)
    try:
        return str(value)
    except Exception:
        return repr(value)


def _format_aircraft_type(airframe_raw):
    mapping = {
        "VTOL": "VTOL",
        "FIXED_WING": "Fixed-Wing",
        "MULTICOPTER": "Multicopter",
    }
    return mapping.get(airframe_raw, "Unknown")


def _detect_aircraft_type_for_dataset(dataset):
    if FlightTypeDetector is None:
        return "Unknown"
    try:
        detector = FlightTypeDetector(dataset)
        return _format_aircraft_type(detector.detect())
    except Exception as e:
        print(f"[GUI] 기체 타입 분석 실패: {e}")
        return "Unknown"


def _preprocess_loaded_dataset(dataset):
    flight_start_time = None
    for t_name in ["vehicle_attitude_0", "sensor_combined_0", "vehicle_local_position_0"]:
        if t_name in dataset.topics:
            t_col = dataset.topics[t_name].dataframe.get_column("timestamp_sec").drop_nulls()
            t_col = t_col.filter(t_col > 0.1)
            if len(t_col) > 0:
                flight_start_time = t_col.min()
                break

    if flight_start_time is not None:
        for topic in dataset.topics.values():
            if "timestamp_sec" in topic.dataframe.columns:
                df = topic.dataframe.with_columns(
                    (pl.col("timestamp_sec") - flight_start_time).alias("timestamp_sec")
                )
                topic.dataframe = df.filter(pl.col("timestamp_sec") >= -30.0)

    from engines.math_engine import MathEngine
    MathEngine.preprocess_dataset(dataset)
    # (2026-10-03) 필터/파생 컬럼 처리 뒤 DataFrame과 Signal 인덱스를 다시
    # 맞춰 분석 엔진이 오래된 Series 또는 None 신호를 읽지 않게 합니다.
    for topic in dataset.topics.values():
        if hasattr(topic, "refresh_signals"):
            topic.refresh_signals()


def _extract_log_metadata_for_dataset(file_path, dataset=None, aircraft_type="Unknown"):
    # PX4's evaluator and pyulog metadata parser must never be applied to a
    # foreign log merely because it happens to expose similarly named topics.
    # The normal LogLoadWorker already routes non-PX4 LoadResult objects to
    # ``_metadata_from_load_result``; this guard also protects fallback/direct
    # callers (including plugins) that only have a LogDataset.
    source_format = str(getattr(dataset, "source_format", "") or "")
    if dataset is not None and source_format != "px4_ulog":
        format_label = _SOURCE_FORMAT_LABELS.get(source_format, source_format or "Unknown")
        dataset_metadata = dict(getattr(dataset, "metadata", {}) or {})
        return {
            "overview": {
                "Source Format": format_label,
                "Topics": len(getattr(dataset, "topics", {}) or {}),
            },
            "firmware": {
                "Log Format": format_label,
                "Source": str(getattr(dataset, "source_path", "") or file_path or ""),
            },
            "parameters": dict(dataset_metadata.get("parameters", {}) or {}),
            "messages": [],
            "warnings": [],
            "evaluation": {
                "overall_score": None,
                "overall_status": "unavailable",
                "overall_status_label": "형식별 분석 미지원",
                "items": [],
                "top_issues": [],
            },
        }
    result = {
        "overview": {},  # (2026-05-28) 비교 다이얼로그 첫 탭에 표시될 비행 요약.
        "firmware": {},
        "parameters": {},
        "messages": [],
        "evaluation": {},
    }
    parameters = {}
    ulog = None  # overview 빌더에서 재사용하기 위해 try 밖으로 노출.
    try:
        from pyulog import ULog
        ulog = ULog(file_path)

        info = getattr(ulog, "msg_info_dict", {}) or {}
        info_multi = getattr(ulog, "msg_info_multiple_dict", {}) or {}
        firmware = {}
        for k, v in info.items():
            k_txt = _metadata_value_to_text(k)
            firmware[k_txt] = _metadata_value_to_text(v)
        for k, v in info_multi.items():
            k_txt = _metadata_value_to_text(k)
            if isinstance(v, (list, tuple)):
                firmware[k_txt] = " | ".join(_metadata_value_to_text(x) for x in v[:8])
            else:
                firmware[k_txt] = _metadata_value_to_text(v)

        params = getattr(ulog, "initial_parameters", {}) or {}
        parameters = {_metadata_value_to_text(k): _metadata_value_to_text(v) for k, v in params.items()}

        # In-flight parameter changes (2026-05-20). pyulog exposes these as a
        # list of (timestamp_us, name, value) tuples — captured whenever a
        # PARAM_SET / parameter_update happens after the log starts. They
        # are NOT included in initial_parameters, so without surfacing
        # them here the metadata-compare dialog only shows the values at
        # arming time and misses in-flight tuning changes.
        # (2026-05-28) 같은 시간축 정책 — Param Changes timestamp 도 start 기준 초 단위 ("12.345s") 로.
        _start_ts_us_pc = 0
        try:
            _start_ts_us_pc = int(getattr(ulog, "start_timestamp", 0) or 0)
        except (TypeError, ValueError):
            _start_ts_us_pc = 0
        raw_changes = getattr(ulog, "changed_parameters", None) or []
        parameter_changes = []
        changed_param_names = set()
        for entry in raw_changes:
            try:
                if isinstance(entry, (tuple, list)) and len(entry) >= 3:
                    ts_raw, name_raw, value_raw = entry[0], entry[1], entry[2]
                else:
                    continue
                ts_text = ""
                if ts_raw is not None:
                    try:
                        ts_us = int(ts_raw)
                        if _start_ts_us_pc > 0:
                            ts_text = f"{(ts_us - _start_ts_us_pc) / 1e6:.3f}s"
                        else:
                            ts_text = f"{ts_us / 1e6:.3f}s"
                    except (TypeError, ValueError):
                        ts_text = _metadata_value_to_text(ts_raw)
                name_text = _metadata_value_to_text(name_raw)
                val_text = _metadata_value_to_text(value_raw)
                if not name_text:
                    continue
                parameter_changes.append({
                    "timestamp": ts_text,
                    "name": name_text,
                    "value": val_text,
                })
                changed_param_names.add(name_text)
            except Exception:
                continue

        # (2026-05-28) Message timestamp 를 ULog start_timestamp 기준 초 단위로 변환 — 그래프의
        # timestamp_sec 와 같은 시간축. "12.345s" 형식으로 표시. start_timestamp 없으면 raw µs 그대로.
        start_ts_us = 0
        try:
            start_ts_us = int(getattr(ulog, "start_timestamp", 0) or 0)
        except (TypeError, ValueError):
            start_ts_us = 0
        raw_messages = getattr(ulog, "logged_messages", None) or []
        messages = []
        for msg in raw_messages:
            raw_ts = getattr(msg, "timestamp", None)
            ts = ""
            if raw_ts is not None:
                try:
                    ts_us = int(raw_ts)
                    if start_ts_us > 0:
                        ts = f"{(ts_us - start_ts_us) / 1e6:.3f}s"
                    else:
                        ts = f"{ts_us / 1e6:.3f}s"
                except (TypeError, ValueError):
                    ts = _metadata_value_to_text(raw_ts)
            level = _metadata_value_to_text(getattr(msg, "log_level", getattr(msg, "level", "")))
            text = _metadata_value_to_text(getattr(msg, "message", getattr(msg, "msg", "")))
            if not text:
                text = _metadata_value_to_text(msg)
            messages.append({"timestamp": ts, "level": level, "text": text})

        result["firmware"] = firmware
        result["parameters"] = parameters
        result["parameter_changes"] = parameter_changes
        result["changed_param_names"] = sorted(changed_param_names)
        result["messages"] = messages
    except Exception as e:
        result["firmware"] = {"parse_error": _metadata_value_to_text(e)}
        result["parameters"] = {}
        result["messages"] = []
    try:
        if AutoEvaluationEngine is not None and dataset is not None:
            evaluator = AutoEvaluationEngine()
            result["evaluation"] = evaluator.evaluate(
                dataset,
                file_name=os.path.basename(file_path),
                aircraft_type=aircraft_type,
                parameters=parameters,
                firmware=result.get("firmware", {}) or {},
                messages=result.get("messages", []) or [],
            )
    except Exception as eval_err:
        result["evaluation"] = {
            "overall_score": None,
            "overall_status": "unavailable",
            "overall_status_label": "정보부족",
            "items": [],
            "top_issues": [f"Evaluation error: {_metadata_value_to_text(eval_err)}"],
        }
    # (2026-05-28) Overview 탭: firmware/parameters 메타와 dataset 토픽을 합쳐
    # 비행 요약(거리/속도/고도/tilt 등) 한 화면 dict 를 구성.
    try:
        from engines.overview_metrics import build_overview
        result["overview"] = build_overview(
            ulog,
            dataset,
            result.get("firmware", {}) or {},
            parameters,
        )
    except Exception as overview_err:
        result["overview"] = {"parse_error": _metadata_value_to_text(overview_err)}
    return result


_SOURCE_FORMAT_LABELS = {
    "px4_ulog": "PX4",
    "ros1_bag": "ROS 1",
    "ros2_bag": "ROS 2",
    "ardupilot_dataflash": "ArduPilot",
    "mavlink_tlog": "MAVLink",
    "tabular": "Tabular",
}


def _canonical_source_identity(source_path):
    """Return a stable, case-normalized identity for a local log source.

    UI labels intentionally remain basename-oriented, but duplicate detection
    must use the complete file/folder location.  ``resolve(strict=False)``
    also normalizes relative paths without requiring the source to still exist
    (useful while restoring layouts and in synthetic tests).
    """

    raw_path = str(source_path or "").strip()
    if not raw_path:
        return ""
    try:
        normalized = str(Path(raw_path).expanduser().resolve(strict=False))
    except Exception:
        normalized = os.path.abspath(os.path.normpath(raw_path))
    return os.path.normcase(os.path.normpath(normalized))


def _source_layout_token(source_id):
    """Return an opaque layout reference without serializing a local path."""

    canonical_id = _canonical_source_identity(source_id)
    if not canonical_id:
        return ""
    payload = f"log-ansys-layout-source-v1\0{canonical_id}".encode("utf-8")
    return f"src-v1:{hashlib.sha256(payload).hexdigest()}"


def _collision_source_key(filename, source_id, existing_keys):
    """Build a deterministic URI-safe key when a basename is already used."""

    filename = str(filename or "source").strip() or "source"
    digest = hashlib.sha256(str(source_id or filename).encode("utf-8")).hexdigest()[:8]
    try:
        qualifier = Path(str(source_id or "")).parent.name.strip()
    except Exception:
        qualifier = ""
    # Windows source paths cannot contain '|', but replacing it also keeps
    # signal URIs parseable for layouts created on POSIX systems.
    qualifier = qualifier.replace("|", "¦")
    base_key = f"{filename} [{qualifier or digest}]"
    if base_key in set(existing_keys or ()):
        base_key = f"{filename} [{qualifier or 'source'} · {digest}]"
    candidate = base_key
    suffix = 2
    existing = set(existing_keys or ())
    while candidate in existing:
        candidate = f"{base_key}-{suffix}"
        suffix += 1
    return candidate


def _source_qualified_legend_name(file_name, dataset, topic_name, signal_name):
    """Return an unambiguous legend label for cross-log overlays.

    A bare ``topic.signal`` label becomes ambiguous as soon as a PX4, ROS, or
    ArduPilot source uses the same field name.  Keep the common signal name
    readable while always exposing both its parser family and file origin.
    """

    source_format = str(getattr(dataset, "source_format", "custom_series") or "unknown")
    source_label = _SOURCE_FORMAT_LABELS.get(
        source_format,
        "Custom" if source_format == "custom_series" else source_format,
    )
    source_path = str(getattr(dataset, "source_path", "") or "")
    origin = os.path.basename(os.path.normpath(source_path)) if source_path else ""
    origin = origin or os.path.basename(str(file_name or "source"))
    # A collision key differs from the original basename.  Keep the normal
    # single-log label unchanged, while reusing the collision key's readable
    # folder qualifier (and hash only when needed) to keep legends unique.
    if str(file_name or "") != origin:
        origin = str(file_name or origin)
    return f"[{source_label} · {origin}] {topic_name}.{signal_name}"


def _metadata_from_load_result(load_result):
    """비 PX4 reader의 공통 metadata를 기존 로그 정보 UI 계약에 맞춥니다."""
    format_id = str(getattr(load_result, "format_id", "unknown") or "unknown")
    dataset = getattr(load_result, "dataset", None)
    reader_metadata = dict(getattr(load_result, "metadata", {}) or {})
    warnings = list(getattr(load_result, "warnings", []) or [])
    messages = []
    for item in list(getattr(load_result, "messages", []) or []):
        if isinstance(item, dict):
            messages.append(dict(item))
        else:
            messages.append({"timestamp": "", "level": "INFO", "text": str(item)})
    for warning in warnings:
        messages.append({"timestamp": "", "level": "WARNING", "text": str(warning)})

    overview = {
        "Source Format": _SOURCE_FORMAT_LABELS.get(format_id, format_id),
        "Topics": len(getattr(dataset, "topics", {}) or {}),
    }
    overview.update(reader_metadata)
    return {
        "overview": overview,
        "firmware": {
            "Log Format": _SOURCE_FORMAT_LABELS.get(format_id, format_id),
            "Source": str(getattr(load_result, "source_path", "") or ""),
        },
        "parameters": dict(getattr(load_result, "parameters", {}) or {}),
        "messages": messages,
        "warnings": warnings,
        "evaluation": {
            "overall_score": None,
            "overall_status": "unavailable",
            "overall_status_label": "형식별 분석 미지원",
            "items": [],
            "top_issues": [],
        },
    }


class LogLoadWorker(QObject):
    """Load log files without exposing partially processed datasets.

    Cancellation is cooperative.  ``LogIOEngine.load_result`` and the PX4
    preprocessing/evaluation helpers currently have no interruption callback,
    so an in-flight call is allowed to return.  The worker then discards that
    result, emits no ``fileLoaded`` signal for it, and skips every remaining
    file.  This avoids unsafe QThread termination while keeping the UI state
    transactional at the dataset commit boundary.
    """

    progressChanged = Signal(object)
    fileLoaded = Signal(object)
    finished = Signal(object)

    def __init__(self, file_paths, existing_names=None, existing_source_ids=None):
        # 백그라운드 로그 로딩 워커 초기화. 별도 스레드에서 로그 파일을 읽어
        # 진행률 시그널을 메인 윈도우 진행 패널에 전달합니다. 보통 수정 X.
        super().__init__()
        self.file_paths = list(file_paths or [])
        # ``existing_names`` is retained for callers compiled against the old
        # constructor.  Duplicate safety now relies on canonical full-source
        # identities so equal basenames in different folders are permitted.
        self.existing_names = set(existing_names or [])
        self.existing_source_ids = set(existing_source_ids or [])
        # A queued Qt slot cannot run while ``load_result`` is blocking the
        # worker event loop.  threading.Event is therefore intentionally set
        # directly from the GUI thread and read at explicit safe boundaries.
        self._cancel_event = threading.Event()

    def request_cancel(self):
        """Request cancellation at the next safe processing boundary."""
        self._cancel_event.set()

    def is_cancel_requested(self):
        return self._cancel_event.is_set()

    def _emit_progress(self, processed_before, total, file_path, stage, stage_percent):
        # 좌측 상단 진행 패널에 표시될 진행률 정보를 시그널로 emit. dict 의
        # "stage" 문자열을 바꾸면 진행 라벨이 바뀝니다.
        total = max(int(total or 0), 1)
        stage_percent = max(0.0, min(100.0, float(stage_percent or 0.0)))
        overall = int(round(((float(processed_before) + (stage_percent / 100.0)) / float(total)) * 100.0))
        self.progressChanged.emit({
            "processed_before": int(processed_before),
            "total": int(total),
            "file_path": str(file_path or ""),
            "filename": os.path.basename(os.path.normpath(str(file_path or ""))),
            "stage": str(stage or ""),
            "stage_percent": stage_percent,
            "overall_percent": max(0, min(100, overall)),
        })

    def run(self):
        io_engine = LogIOEngine()
        emitted_count = 0
        skipped_missing = []
        skipped_duplicate = []
        failed = []
        candidates = []
        seen_source_ids = set(self.existing_source_ids)
        cancelled = False
        cancelled_file_path = ""

        for file_path in self.file_paths:
            if not file_path or not os.path.exists(file_path):
                if file_path:
                    skipped_missing.append(file_path)
                continue
            filename = os.path.basename(os.path.normpath(file_path))
            source_id = _canonical_source_identity(file_path)
            if source_id and source_id in seen_source_ids:
                skipped_duplicate.append(filename)
                continue
            if source_id:
                seen_source_ids.add(source_id)
            candidates.append((file_path, source_id))

        total = len(candidates)
        if total <= 0:
            summary = {
                "emitted_count": 0,
                "skipped_missing": skipped_missing,
                "skipped_duplicate": skipped_duplicate,
                "failed": failed,
            }
            if self.is_cancel_requested():
                summary.update({"cancelled": True, "cancelled_file_path": ""})
            self.finished.emit(summary)
            return

        for processed_before, (file_path, source_id) in enumerate(candidates):
            if self.is_cancel_requested():
                cancelled = True
                cancelled_file_path = file_path
                break
            filename = os.path.basename(os.path.normpath(file_path))
            try:
                self._emit_progress(processed_before, total, file_path, "Format detection / cache load", 5.0)
                load_result = io_engine.load_result(file_path)
                if self.is_cancel_requested():
                    cancelled = True
                    cancelled_file_path = file_path
                    break
                dataset = load_result.dataset
                if not dataset:
                    failed.append({"file_path": file_path, "error": "dataset load returned None"})
                    self._emit_progress(processed_before, total, file_path, "Load failed", 100.0)
                    continue

                # Evaluation/preprocessing are PX4-specific.  Require both
                # the concrete reader format and its capability marker so a
                # third-party reader cannot accidentally enter the PX4 path.
                is_px4 = (
                    str(load_result.format_id or "") == "px4_ulog"
                    and "px4" in set(load_result.capabilities or ())
                )
                if is_px4:
                    self._emit_progress(processed_before, total, file_path, "PX4 dataset preprocessing", 60.0)
                    _preprocess_loaded_dataset(dataset)
                    if self.is_cancel_requested():
                        cancelled = True
                        cancelled_file_path = file_path
                        break
                    self._emit_progress(processed_before, total, file_path, "Aircraft type detection", 75.0)
                    aircraft_type = _detect_aircraft_type_for_dataset(dataset)
                    if self.is_cancel_requested():
                        cancelled = True
                        cancelled_file_path = file_path
                        break
                    self._emit_progress(processed_before, total, file_path, "Metadata / evaluation", 85.0)
                    metadata = _extract_log_metadata_for_dataset(
                        file_path,
                        dataset=dataset,
                        aircraft_type=aircraft_type,
                    )
                    if load_result.warnings:
                        metadata["warnings"] = list(load_result.warnings)
                else:
                    self._emit_progress(processed_before, total, file_path, "Normalizing topics", 70.0)
                    aircraft_type = _SOURCE_FORMAT_LABELS.get(load_result.format_id, load_result.format_id)
                    metadata = _metadata_from_load_result(load_result)

                if self.is_cancel_requested():
                    cancelled = True
                    cancelled_file_path = file_path
                    break
                self._emit_progress(processed_before, total, file_path, "Applying to UI", 95.0)
                self.fileLoaded.emit({
                    "file_path": file_path,
                    "filename": filename,
                    "source_id": source_id,
                    "dataset": dataset,
                    "aircraft_type": aircraft_type,
                    "metadata": metadata,
                    "format_id": load_result.format_id,
                })
                emitted_count += 1
                self._emit_progress(processed_before, total, file_path, "Complete", 100.0)
            except Exception as e:
                if self.is_cancel_requested():
                    cancelled = True
                    cancelled_file_path = file_path
                    break
                failed.append({"file_path": file_path, "error": str(e)})
                print(f"\n[GUI][Worker] 로그 로드 오류: {file_path} | {e}")
                traceback.print_exc()
                self._emit_progress(processed_before, total, file_path, "Load failed", 100.0)

        summary = {
            "emitted_count": emitted_count,
            "skipped_missing": skipped_missing,
            "skipped_duplicate": skipped_duplicate,
            "failed": failed,
        }
        if cancelled or self.is_cancel_requested():
            summary.update({
                "cancelled": True,
                "cancelled_file_path": cancelled_file_path,
            })
        self.finished.emit(summary)

class DraggableTreeView(QTreeView):
    ROLE_FILE_NAME = Qt.UserRole + 2
    ROLE_TOPIC_NAME = Qt.UserRole + 3
    ROLE_SIGNAL_NAME = Qt.UserRole + 4
    ROLE_SIGNAL_URI = Qt.UserRole + 5
    # Internal MIME used for drag-to-reorder of the top-level log file
    # nodes. Distinct from the signal-URI MIME so plot widgets don't try
    # to render the dropped payload. 2026-05-15.
    REORDER_MIME = "application/x-px4-log-reorder"
    # Emitted on a successful internal drop. Arguments:
    #   source_file (str): the file_name being moved
    #   target_file (str): the file_name above/below which it should land
    #   insert_below (bool): True = land after target, False = before
    fileReorderRequested = Signal(str, str, bool)

    def __init__(self):
        # 좌측 신호 트리 초기화. setDragEnabled/setAcceptDrops 를 False 로 바꾸면 드래그·드롭이 막히고, setSelectionMode 를 SingleSelection 으로 바꾸면 한 번에 한 행만 선택됩니다.
        super().__init__()
        self.setDragEnabled(True)
        self.setSelectionMode(QAbstractItemView.ExtendedSelection)
        self.setSelectionBehavior(QAbstractItemView.SelectRows)
        # Was DragOnly — now also accepts internal drops so file-node drags
        # can be dropped back into the tree to reorder. External signal
        # drops to plots are not affected (they target the plot widget).
        self.setDragDropMode(QAbstractItemView.DragDrop)
        self.setAcceptDrops(True)
        self.setDefaultDropAction(Qt.CopyAction)
        self.setEditTriggers(QAbstractItemView.NoEditTriggers)
        self._drag_start_pos = None
        self._drag_start_index = QModelIndex()
        self._drag_start_button = Qt.NoButton
        self._last_drag_was_right = False
        self._pending_ignore_drop_uris = None
        self._pending_ignore_drop_retries = 0
        # Right-click-during-drag cancel state (2026-05-20)
        self._drag_cancelled_by_right_click = False
        self._suppress_next_context_menu = False

    def contextMenuEvent(self, event):
        # 트리에서 우클릭했을 때 자동 호출. 보통 수정 X.
        """Swallow the next context menu when a drag was just cancelled by
        right-click. Without this guard, the right-click that cancelled the
        drag would also pop the tree's context menu immediately afterward.
        (2026-05-20)"""
        if self._suppress_next_context_menu:
            self._suppress_next_context_menu = False
            event.accept()
            return
        super().contextMenuEvent(event)

    def mousePressEvent(self, event):
        # 트리에서 마우스 버튼을 누를 때 자동 호출. 보통 수정 X.
        if event.button() in (Qt.LeftButton, Qt.RightButton):
            point = event.position().toPoint()
            self._drag_start_pos = point
            self._drag_start_index = self.indexAt(point)
            self._drag_start_button = event.button()
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        # 트리에서 마우스를 움직일 때 자동 호출 — 드래그 시작 거리 판정에 사용. 보통 수정 X.
        if not (event.buttons() & (Qt.LeftButton | Qt.RightButton)):
            super().mouseMoveEvent(event)
            return
        if self._drag_start_pos is None:
            super().mouseMoveEvent(event)
            return
        point = event.position().toPoint()
        if (point - self._drag_start_pos).manhattanLength() < QApplication.startDragDistance():
            super().mouseMoveEvent(event)
            return
        if not self._drag_start_index.isValid():
            self._drag_start_index = self.currentIndex()
            if not self._drag_start_index.isValid():
                selected = self.selectionModel().selectedRows(0)
                if selected:
                    self._drag_start_index = selected[0]
            if not self._drag_start_index.isValid():
                super().mouseMoveEvent(event)
                return

        if not self.selectionModel().isSelected(self._drag_start_index):
            self.selectionModel().select(
                self._drag_start_index,
                QItemSelectionModel.ClearAndSelect | QItemSelectionModel.Rows
            )
            self.setCurrentIndex(self._drag_start_index)

        if event.buttons() & Qt.RightButton:
            self._drag_start_button = Qt.RightButton
        elif event.buttons() & Qt.LeftButton:
            self._drag_start_button = Qt.LeftButton

        self.startDrag(Qt.CopyAction)
        self._drag_start_pos = None
        self._drag_start_index = QModelIndex()
        event.accept()

    def mouseReleaseEvent(self, event):
        # 트리에서 마우스 버튼을 뗄 때 자동 호출. 보통 수정 X.
        if event.button() in (Qt.LeftButton, Qt.RightButton):
            self._drag_start_pos = None
            self._drag_start_index = QModelIndex()
            self._drag_start_button = Qt.NoButton
            if self._pending_ignore_drop_uris:
                QTimer.singleShot(0, self._flush_pending_ignore_drop)
        super().mouseReleaseEvent(event)

    def _is_file_node(self, index):
        # Top-level item: no parent in the QStandardItemModel.
        return bool(index.isValid()) and (not index.parent().isValid())

    def _file_name_for_index(self, index):
        if not index.isValid():
            return None
        item = self.model().itemFromIndex(index)
        if item is None:
            return None
        name = item.data(self.ROLE_FILE_NAME)
        if not name:
            name = item.data(Qt.UserRole)
        return str(name) if name else None

    def _is_topic_node(self, index):
        """Mid-level (topic) node: has ROLE_TOPIC_NAME but no
        ROLE_SIGNAL_URI. Drag must be blocked here because the default
        recursive URI collection would gather every child signal under
        the topic (often dozens) and flood the target plot. (2026-05-20)"""
        if not index.isValid():
            return False
        item = self.model().itemFromIndex(index)
        if item is None:
            return False
        has_uri = bool(str(item.data(self.ROLE_SIGNAL_URI) or "").strip())
        has_topic = bool(str(item.data(self.ROLE_TOPIC_NAME) or "").strip())
        return has_topic and not has_uri

    def startDrag(self, supportedActions):
        # 트리에서 드래그가 시작될 때 호출 — 선택된 노드들로부터 signal URI 목록을 만들어 MIME 데이터에 실어 보냅니다. 보통 수정 X.
        perf_started_at = time.perf_counter()
        indexes = self.selectionModel().selectedRows(0)
        if not indexes and self.currentIndex().isValid():
            indexes = [self.currentIndex()]
        if not indexes:
            print("[DND][Tree] startDrag: no selection")
            return

        # 2026-05-20: stale-selection rescue. The mouse-press source of
        # truth is `_drag_start_index`. If the selection model still
        # reflects a previously-dragged row (selection update lagging
        # behind the press), the user's *new* press intent is lost and
        # we ship the wrong URIs. Force-update selection to the press
        # target so the actual grabbed row wins.
        press_idx = (
            self._drag_start_index if self._drag_start_index.isValid() else QModelIndex()
        )
        if press_idx.isValid() and not any(idx == press_idx for idx in indexes):
            self.selectionModel().select(
                press_idx,
                QItemSelectionModel.ClearAndSelect | QItemSelectionModel.Rows,
            )
            self.setCurrentIndex(press_idx)
            indexes = [press_idx]

        # If the user is dragging a TOP-LEVEL file node, treat the gesture
        # as an internal reorder rather than collecting all child signal
        # URIs. The previous behavior recursively gathered every signal
        # under that file (potentially thousands) and built one giant
        # drop payload, which froze / crashed the receiver on drop.
        # 2026-05-15.
        if len(indexes) == 1 and self._is_file_node(indexes[0]):
            self._start_internal_file_reorder_drag(indexes[0])
            return

        # Block MID-LEVEL (topic) drags — e.g. "actuator_outputs_0". Same
        # rationale as the file-node guard above: recursive child collection
        # silently floods the target plot with every signal under the topic.
        # Users must drag individual signal leaves instead. (2026-05-20)
        if any(self._is_topic_node(idx) for idx in indexes):
            print("[DND][Tree] startDrag aborted: topic-level node in selection")
            return

        uri_build_started_at = time.perf_counter()
        uris = []
        seen = set()
        skipped_count = 0
        for index in indexes:
            item = self.model().itemFromIndex(index)
            if not item:
                skipped_count += 1
                continue
            added_count = self._collect_item_signal_uris(item, uris, seen)
            if added_count == 0:
                skipped_count += 1

        uri_build_ms = (time.perf_counter() - uri_build_started_at) * 1000.0

        if not uris:
            print(f"[DND][Tree] startDrag: no valid signal URI (selection={len(indexes)} skipped={skipped_count})")
            _perf_debug_block(
                "dnd_start",
                [
                    ("selection_count", len(indexes)),
                    ("uri_count", 0),
                    ("skipped_selection_count", skipped_count),
                    ("startDrag_uri_build_ms", f"{uri_build_ms:.3f}"),
                    ("total_ms", f"{(time.perf_counter() - perf_started_at) * 1000.0:.3f}"),
                ],
            )
            return
        
        mimeData = QMimeData()
        joined = "\n".join(uris)
        mimeData.setText(joined)
        mimeData.setData("application/x-px4-signal-list", joined.encode("utf-8"))
        drag_origin = b"right" if self._drag_start_button == Qt.RightButton else b"left"
        self._last_drag_was_right = (drag_origin == b"right")
        mimeData.setData("application/x-px4-drag-origin", drag_origin)
        drag = QDrag(self)
        drag.setMimeData(mimeData)
        drag_pix = self._build_drag_pixmap(len(uris), uris)
        drag.setPixmap(drag_pix)
        drag.setHotSpot(drag_pix.rect().center())
        _perf_debug_block(
            "dnd_start",
            [
                ("selection_count", len(indexes)),
                ("uri_count", len(uris)),
                ("skipped_selection_count", skipped_count),
                ("startDrag_uri_build_ms", f"{uri_build_ms:.3f}"),
                ("total_ms", f"{(time.perf_counter() - perf_started_at) * 1000.0:.3f}"),
            ],
        )
        print(
            f"[DND][Tree] startDrag: {len(uris)} signal(s) "
            f"origin={drag_origin.decode('utf-8')} skipped={skipped_count}"
        )
        # Right-click-during-drag cancel monitor (2026-05-20). Polls the
        # global mouse-button state every ~30 ms while drag.exec() blocks.
        # When the right button is pressed during the drag, terminate the
        # gesture and suppress the trailing context menu.
        self._drag_cancelled_by_right_click = False
        cancel_timer = QTimer(self)
        cancel_timer.setInterval(30)
        def _on_cancel_tick():
            if QApplication.mouseButtons() & Qt.RightButton:
                self._drag_cancelled_by_right_click = True
                self._suppress_next_context_menu = True
                try:
                    QDrag.cancel()
                except (AttributeError, TypeError):
                    pass
                cancel_timer.stop()
        cancel_timer.timeout.connect(_on_cancel_tick)
        cancel_timer.start()
        try:
            result = drag.exec(Qt.CopyAction)
        finally:
            cancel_timer.stop()
        if self._drag_cancelled_by_right_click:
            result = Qt.IgnoreAction
            if PERF_DEBUG_ENABLED:
                print("[DND][Tree] drag cancelled by right-click")
        if PERF_DEBUG_ENABLED:
            print(f"[DND][Tree] drag result: {result}")
        if self._drag_cancelled_by_right_click:
            # Don't retry the drop — the cancel was intentional.
            self._pending_ignore_drop_uris = None
            self._pending_ignore_drop_retries = 0
        elif result == Qt.IgnoreAction:
            self._pending_ignore_drop_uris = list(uris)
            self._pending_ignore_drop_retries = 0
            self._flush_pending_ignore_drop()
        else:
            self._pending_ignore_drop_uris = None
            self._pending_ignore_drop_retries = 0

    def _start_internal_file_reorder_drag(self, index):
        """Build a drag carrying only the file name (no signal URIs) so
        plot widgets reject it and the tree can interpret it as a reorder
        gesture on drop. 2026-05-15."""
        file_name = self._file_name_for_index(index)
        if not file_name:
            return
        mime = QMimeData()
        mime.setData(self.REORDER_MIME, file_name.encode("utf-8"))
        drag = QDrag(self)
        drag.setMimeData(mime)
        try:
            rect = self.visualRect(index)
            if rect.isValid():
                pix = QPixmap(rect.size())
                pix.fill(QColor(36, 51, 102, 180))
                drag.setPixmap(pix)
                drag.setHotSpot(rect.center() - rect.topLeft())
        except Exception:
            pass
        self._last_drag_was_right = False
        drag.exec(Qt.MoveAction)

    def dragEnterEvent(self, event):
        if event.mimeData().hasFormat(self.REORDER_MIME):
            event.acceptProposedAction()
            return
        super().dragEnterEvent(event)

    def dragMoveEvent(self, event):
        if event.mimeData().hasFormat(self.REORDER_MIME):
            event.acceptProposedAction()
            return
        super().dragMoveEvent(event)

    def dropEvent(self, event):
        if event.mimeData().hasFormat(self.REORDER_MIME):
            source_name = bytes(event.mimeData().data(self.REORDER_MIME)).decode("utf-8", "replace")
            drop_pos = event.position().toPoint()
            drop_index = self.indexAt(drop_pos)
            if not drop_index.isValid():
                event.ignore()
                return
            # Walk up to the top-level (file) ancestor of whatever was
            # under the cursor — drops on a sub-topic should still reorder
            # against the parent file's row.
            top_index = drop_index
            while top_index.parent().isValid():
                top_index = top_index.parent()
            target_name = self._file_name_for_index(top_index)
            if not target_name or target_name == source_name:
                event.ignore()
                return
            row_rect = self.visualRect(top_index)
            insert_below = drop_pos.y() > row_rect.center().y()
            self.fileReorderRequested.emit(source_name, target_name, insert_below)
            event.acceptProposedAction()
            return
        super().dropEvent(event)

    def _collect_item_signal_uris(self, item, uris, seen):
        if item is None:
            return 0

        direct_uri = self._resolve_item_signal_uri(item)
        if direct_uri:
            if direct_uri not in seen:
                seen.add(direct_uri)
                uris.append(direct_uri)
                return 1
            return 0

        added_count = 0
        for row in range(item.rowCount()):
            child = item.child(row)
            if child is None:
                continue
            added_count += self._collect_item_signal_uris(child, uris, seen)
        return added_count

    def _resolve_item_signal_uri(self, item):
        if item is None:
            return ""

        resolved_uri = str(item.data(self.ROLE_SIGNAL_URI) or "").strip()
        if resolved_uri:
            return resolved_uri

        signal_name = str(item.data(self.ROLE_SIGNAL_NAME) or "").strip()
        topic_name = str(item.data(self.ROLE_TOPIC_NAME) or "").strip()
        file_name = str(item.data(self.ROLE_FILE_NAME) or "").strip()

        if not signal_name and item.rowCount() > 0:
            return ""

        if not signal_name and item.parent() and item.parent().parent():
            signal_name = item.text().strip()
        if not topic_name and item.parent():
            topic_name = item.parent().text().strip()
        if not file_name and item.parent() and item.parent().parent():
            file_item = item.parent().parent()
            file_name = str(file_item.data(self.ROLE_FILE_NAME) or file_item.data(Qt.UserRole) or "").strip()
            if not file_name:
                display_text = str(file_item.text() or "")
                if " | Type :" in display_text:
                    display_text = display_text.split(" | Type :", 1)[0]
                elif " | Aircraft :" in display_text:
                    display_text = display_text.split(" | Aircraft :", 1)[0]
                if display_text.startswith("[DIR] "):
                    display_text = display_text[6:]
                elif display_text.startswith("[FILE] "):
                    display_text = display_text[7:]
                file_name = display_text.strip()

        if not file_name or not topic_name or not signal_name:
            return ""

        return f"{file_name}|{topic_name}|{signal_name}"

    @staticmethod
    def _build_drag_pixmap(count, uris=None):
        # 드래그할 때 마우스 옆에 떠다니는 작은 라벨 그리기. QColor(26, 45, 87, 200) 을 바꾸면 라벨 배경색이, QFont("Segoe UI", 9, QFont.Bold) 의 9 를 키우면 글자가 커집니다.
        if uris:
            lines = []
            for u in uris[:6]:
                parts = u.split("|")
                label = parts[2] if len(parts) >= 3 else u
                lines.append(label)
            if len(uris) > 6:
                lines.append(f"... +{len(uris) - 6}")
            text = "\n".join(lines)
        else:
            text = f"+ {count} signal(s)"
        font = QFont("Segoe UI", 9, QFont.Bold)
        fm = QFontMetrics(font)
        text_lines = text.split("\n")
        line_height = fm.height()
        max_width = max(fm.horizontalAdvance(ln) for ln in text_lines)
        pad_x, pad_y = 10, 4
        pix_w = max_width + pad_x * 2
        pix_h = line_height * len(text_lines) + pad_y * 2
        pix = QPixmap(pix_w, pix_h)
        pix.fill(Qt.transparent)
        painter = QPainter(pix)
        painter.setRenderHint(QPainter.Antialiasing, True)
        painter.setPen(Qt.NoPen)
        painter.setBrush(QColor(26, 45, 87, 200))
        painter.drawRoundedRect(0, 0, pix_w, pix_h, 4, 4)
        painter.setPen(QColor("#ffffff"))
        painter.setFont(font)
        y = pad_y + fm.ascent()
        for ln in text_lines:
            painter.drawText(pad_x, y, ln)
            y += line_height
        painter.end()
        return pix

    def _flush_pending_ignore_drop(self):
        if not self._pending_ignore_drop_uris:
            return
        if QApplication.mouseButtons() & Qt.LeftButton:
            self._pending_ignore_drop_retries += 1
            if self._pending_ignore_drop_retries < 40:
                QTimer.singleShot(15, self._flush_pending_ignore_drop)
            return

        uris = self._pending_ignore_drop_uris
        self._pending_ignore_drop_uris = None
        self._pending_ignore_drop_retries = 0

        global_pos = QCursor.pos()
        widget_at = QApplication.widgetAt(global_pos)
        if widget_at is not None:
            target = widget_at
            while target is not None:
                if isinstance(target, SignalDropLineEdit):
                    dlg = target.window()
                    if isinstance(dlg, CustomSeriesEditorDialog):
                        dlg._apply_signal_drop(target, uris)
                    else:
                        target.set_signal_uri(uris[0])
                    if PERF_DEBUG_ENABLED:
                        print(f"[DND][Tree] release-drop fallback -> SignalDropLineEdit uris={len(uris)}")
                    return
                target = target.parentWidget()

        main_window = self.window()
        if main_window and hasattr(main_window, "handle_signal_drop_from_cursor"):
            rendered = main_window.handle_signal_drop_from_cursor(
                uris,
                global_pos,
                strict_target=False,
                prefer_curve_popup=self._last_drag_was_right,
            )
            if PERF_DEBUG_ENABLED:
                print(f"[DND][Tree] release-drop fallback rendered={rendered} uris={len(uris)}")

def _parse_signal_uri_text(uri_text):
    parts = [p.strip() for p in str(uri_text).split("|")]
    if len(parts) < 3:
        return None
    file_name, topic_name, signal_name = parts[:3]
    x_axis_col = parts[3] if len(parts) > 3 and parts[3] else "timestamp_sec"
    return file_name, topic_name, signal_name, x_axis_col

def _format_signal_uri_label(uri_text):
    parsed = _parse_signal_uri_text(uri_text)
    if not parsed:
        return str(uri_text)
    file_name, topic_name, signal_name, _ = parsed
    short_file = file_name[:20] + ".." if len(file_name) > 22 else file_name
    return f"[{short_file}] {topic_name}.{signal_name}"

class DataFilterDialog(QDialog):
    """PlotJuggler-style 'Apply Filter to Data' dialog.

    Lets the user pick one of the plotted source curves, choose a filter
    transform, set parameters, then apply.  The result is returned via
    ``result_data()`` after ``accept()``.
    """

    FILTER_TYPES = [
        ("-- NO Transform --", "none"),
        ("Absolute", "absolute"),
        ("Derivative", "derivative"),
        ("Integral", "integral"),
        ("Moving Average", "moving_average"),
        ("Moving Root Mean Squared", "moving_rms"),
        ("Outlier Removal", "outlier_removal"),
        ("Scale/Offset", "scale_offset"),
    ]

    def __init__(self, parent, plotted_uris):
        # 데이터 필터 팝업 초기화. plotted_uris 로 받은 신호 목록과 FILTER_TYPES 리스트로 콤보박스가 채워집니다.
        """
        Parameters
        ----------
        parent : QWidget
        plotted_uris : list[str]
            URI strings currently plotted (keys of ``plotted_signals``).
        """
        super().__init__(parent)
        # 팝업 창 크기·타이틀·전체 스타일 정의. setWindowTitle 문자열을 바꾸면 창 상단 제목이, resize(680, 420) 의 픽셀을 키우면 팝업이 커집니다. setStyleSheet 의 background-color 를 바꾸면 팝업 배경색이 바뀝니다.
        self.setWindowTitle("Apply Filter to Data")
        self.resize(680, 420)
        self.setMinimumSize(560, 360)
        self._result = None
        self._uris = list(plotted_uris)

        # ── stylesheet ────────────────────────────────────────────
        self.setStyleSheet("""
            QDialog { background-color: #f4f5f7; }
            QLabel { color: #1f2b36; border: none; padding: 0px; }
            QLineEdit, QComboBox {
                background-color: #ffffff;
                color: #1f2b36;
                border: 1px solid #a4adb7;
                border-radius: 3px;
                padding: 3px 6px;
                min-height: 22px;
            }
            QListWidget {
                background-color: #ffffff;
                color: #1f2b36;
                border: 1px solid #a4adb7;
                border-radius: 3px;
                font-size: 12px;
            }
            QListWidget::item:selected {
                background-color: #0078d7;
                color: #ffffff;
            }
            QPushButton {
                background-color: #e8eaed;
                color: #1f2b36;
                border: 1px solid #a4adb7;
                border-radius: 3px;
                min-height: 26px;
                padding: 2px 12px;
            }
            QPushButton:hover { background-color: #d0d3d8; }
            QPushButton#applyBtn {
                background-color: #0078d7;
                color: #ffffff;
                border: none;
                font-weight: bold;
            }
            QPushButton#applyBtn:hover { background-color: #005fa3; }
            QGroupBox {
                font-weight: bold;
                border: 1px solid #c8cdd2;
                border-radius: 4px;
                margin-top: 8px;
                padding: 12px 8px 8px 8px;
            }
            QGroupBox::title {
                subcontrol-origin: margin;
                left: 10px;
                padding: 0 4px;
            }
        """)

        root = QVBoxLayout(self)
        root.setContentsMargins(12, 12, 12, 12)
        root.setSpacing(8)

        # ── top row: alias ────────────────────────────────────────
        alias_row = QHBoxLayout()
        alias_row.setSpacing(6)
        # 필터 결과 곡선 이름 입력란 라벨. QLabel("Alias:") 의 문자열을 바꾸면 화면에 보이는 라벨이 바뀝니다.
        lbl_alias = QLabel("Alias:")
        lbl_alias.setStyleSheet("font-weight: 600;")
        alias_row.addWidget(lbl_alias)
        self.ed_alias = QLineEdit()
        self.ed_alias.setPlaceholderText("(auto-generated)")
