        root.addLayout(alias_row)

        # ── body: 3 columns ──────────────────────────────────────
        body = QHBoxLayout()
        body.setSpacing(10)

        # Column 1 — Source curve
        col_src = QVBoxLayout()
        col_src.setSpacing(4)
        # 첫 번째 컬럼(어떤 곡선을 필터링할지) 라벨. QLabel("Source curve:") 문자열을 바꾸면 라벨이 바뀝니다.
        lbl_src = QLabel("Source curve:")
        lbl_src.setStyleSheet("font-weight: 600;")
