        lbl_no_param = QLabel("No parameters needed.")
        lbl_no_param.setStyleSheet("color: #6b7785; font-style: italic;")
        lbl_no_param.setAlignment(Qt.AlignCenter)
        page_empty_layout.addWidget(lbl_no_param)
