        # Page 1 — window size (Moving Avg / Moving RMS)
        page_window = QWidget()
        page_window_layout = QVBoxLayout(page_window)
        page_window_layout.setContentsMargins(4, 4, 4, 4)
        page_window_layout.setSpacing(6)
        # 이동평균·RMS 필터의 윈도우 크기 입력 라벨. QLabel("Window size (samples):") 문자열을 바꾸면 라벨이 바뀝니다.
        lbl_win = QLabel("Window size (samples):")
        page_window_layout.addWidget(lbl_win)
        self.ed_window = QLineEdit("10")
        self.ed_window.setPlaceholderText("10")
        page_window_layout.addWidget(self.ed_window)
        page_window_layout.addStretch()
        self.param_stack.addWidget(page_window)  # index 1

        # Page 2 — threshold (Outlier Removal)
        page_outlier = QWidget()
        page_outlier_layout = QVBoxLayout(page_outlier)
        page_outlier_layout.setContentsMargins(4, 4, 4, 4)
        page_outlier_layout.setSpacing(6)
        # 이상치 제거 필터의 임계값(시그마 배수) 입력 라벨. QLabel("Threshold (σ):") 문자열을 바꾸면 라벨이 바뀝니다.
        lbl_thr = QLabel("Threshold (σ):")
        page_outlier_layout.addWidget(lbl_thr)
        self.ed_threshold = QLineEdit("3.0")
        self.ed_threshold.setPlaceholderText("3.0")
        page_outlier_layout.addWidget(self.ed_threshold)
        page_outlier_layout.addStretch()
        self.param_stack.addWidget(page_outlier)  # index 2

        # Page 3 — Scale/Offset (most detailed)
        page_so = QWidget()
        page_so_layout = QVBoxLayout(page_so)
        page_so_layout.setContentsMargins(4, 4, 4, 4)
        page_so_layout.setSpacing(8)

        # Apply offset section
        # Scale/Offset 필터의 오프셋 섹션 헤더. QLabel("Apply offset") 문자열을 바꾸면 헤더 문구가 바뀝니다.
        lbl_offset_header = QLabel("Apply offset")
        lbl_offset_header.setStyleSheet("font-weight: bold; font-size: 13px;")
        page_so_layout.addWidget(lbl_offset_header)

        row_time_off = QHBoxLayout()
        row_time_off.setSpacing(6)
        # 시간축을 좌우로 이동시키는 입력란 라벨. QLabel("Time offset:") 문자열을 바꾸면 라벨이 바뀝니다.
        row_time_off.addWidget(QLabel("Time offset:"))
        self.ed_time_offset = QLineEdit("0")
        self.ed_time_offset.setFixedWidth(90)
        row_time_off.addWidget(self.ed_time_offset)
        row_time_off.addStretch()
        page_so_layout.addLayout(row_time_off)

        row_val_off = QHBoxLayout()
        row_val_off.setSpacing(6)
        # 값을 위아래로 이동시키는 입력란 라벨. QLabel("Value offset:") 문자열을 바꾸면 라벨이 바뀝니다.
        row_val_off.addWidget(QLabel("Value offset:"))
        self.ed_value_offset = QLineEdit("0")
        self.ed_value_offset.setFixedWidth(90)
        row_val_off.addWidget(self.ed_value_offset)
        row_val_off.addStretch()
        page_so_layout.addLayout(row_val_off)

        # Scale section
        # 스케일(배수) 섹션 헤더. QLabel("Scale (multiply value)") 문자열을 바꾸면 헤더 문구가 바뀝니다.
        lbl_scale_header = QLabel("Scale (multiply value)")
        lbl_scale_header.setStyleSheet("font-weight: bold; font-size: 13px;")
