        row_mult = QHBoxLayout()
        row_mult.setSpacing(6)
        # 값을 곱할 배수 입력란 라벨. QLabel("Value multiplier:") 문자열을 바꾸면 라벨이 바뀝니다.
        row_mult.addWidget(QLabel("Value multiplier:"))
        self.ed_multiplier = QLineEdit("1.0")
        self.ed_multiplier.setFixedWidth(90)
        row_mult.addWidget(self.ed_multiplier)
        row_mult.addStretch()
        page_so_layout.addLayout(row_mult)

        # Useful constants
        # 자주 쓰는 단위 변환 상수 안내 라벨. QLabel("Useful constants:") 문자열을 바꾸면 라벨이 바뀝니다.
        lbl_useful = QLabel("Useful constants:")
        lbl_useful.setStyleSheet("color: #4a5568;")
        page_so_layout.addWidget(lbl_useful)

        const_row = QHBoxLayout()
        const_row.setSpacing(6)
        # 라디안↔도 변환 단축 버튼. QPushButton("Rad to Deg")/QPushButton("Deg to Rad") 문자열을 바꾸면 버튼 라벨이, setToolTip 문구를 바꾸면 호버 안내가 바뀝니다.
        self.btn_rad_to_deg = QPushButton("Rad to Deg")
        self.btn_rad_to_deg.setToolTip("Set multiplier to 180/π ≈ 57.2958")
        self.btn_rad_to_deg.clicked.connect(lambda: self.ed_multiplier.setText("57.2957795"))
