        page_so_layout.addLayout(const_row)

        page_so_layout.addStretch()
        self.param_stack.addWidget(page_so)  # index 3

        col_params.addWidget(self.param_stack, 1)
        body.addLayout(col_params, 3)

        root.addLayout(body, 1)

        # ── bottom buttons ────────────────────────────────────────
        btn_row = QHBoxLayout()
