    def _write_evaluation_detail_xlsx(self, output_path, export_payload):
        report = export_payload if isinstance(export_payload, dict) else {}
        row_specs = self._evaluation_detail_row_specs(report)
        sheet_name = self._xlsx_safe_sheet_name(report.get("sheet_name", "Evaluation"))
        self._write_structured_xlsx(
            output_path,
            sheet_name,
            row_specs,
            document_title=report.get("document_title", "PX4 Evaluation Detail"),
        )

    @staticmethod
    def _docx_text_run(text, bold=False):
        content = xml_escape("" if text is None else str(text))
        rpr_parts = [
            '<w:rFonts w:ascii="Malgun Gothic" w:hAnsi="Malgun Gothic" w:eastAsia="Malgun Gothic" w:cs="Malgun Gothic"/>',
            '<w:sz w:val="22"/>',
            '<w:szCs w:val="22"/>',
        ]
        if bold:
            rpr_parts.insert(1, '<w:b/>')
            rpr_parts.insert(2, '<w:bCs/>')
        return f'<w:r><w:rPr>{"".join(rpr_parts)}</w:rPr><w:t xml:space="preserve">{content}</w:t></w:r>'

    @classmethod
    def _docx_paragraph(cls, text="", style="BodyText"):
        body = ""
        text_value = "" if text is None else str(text)
        if text_value:
            body = cls._docx_text_run(text_value)
        return f'<w:p><w:pPr><w:pStyle w:val="{xml_escape(str(style or "BodyText"))}"/></w:pPr>{body}</w:p>'

    @classmethod
    def _docx_labeled_paragraph(cls, label, value, style="BodyText"):
        label_txt = str(label or "").strip()
        value_txt = str(value or "").strip()
        runs = cls._docx_text_run(f"{label_txt}: ", bold=True) + cls._docx_text_run(value_txt)
        return f'<w:p><w:pPr><w:pStyle w:val="{xml_escape(str(style or "BodyText"))}"/></w:pPr>{runs}</w:p>'

    @classmethod
    def _write_evaluation_detail_docx(cls, output_path, export_payload):
        report = export_payload if isinstance(export_payload, dict) else {}
        title = str(report.get("document_title", "자동평가 상세 보고서")).strip() or "자동평가 상세 보고서"
        body_xml = [cls._docx_paragraph(title, style="Title")]

        for label, value in report.get("meta_rows", []) or []:
            label_txt = str(label or "").strip()
            value_txt = str(value or "").strip()
            if label_txt and value_txt:
                body_xml.append(cls._docx_labeled_paragraph(label_txt, value_txt, style="BodyText"))

        sections = report.get("sections", []) if isinstance(report.get("sections", []), list) else []
        if report.get("meta_rows") and sections:
            body_xml.append(cls._docx_paragraph("", style="BodyText"))

        for section in sections:
            if not isinstance(section, dict):
                continue
            section_title = str(section.get("title", "")).strip()
            items = section.get("items", []) if isinstance(section.get("items", []), list) else []
            kind = str(section.get("kind", "list")).strip().lower()
            ordered = bool(section.get("ordered", False))
