    @classmethod
    def _confidence_lines_ko(cls, conf_breakdown):
        if not isinstance(conf_breakdown, dict):
            return []
        mapping = [
            ("sample_factor", "샘플 충분도"),
            ("topic_factor", "Topic 확보율"),
            ("quality_factor", "신호 품질"),
            ("mode_factor", "비행 모드 적합성"),
            ("semantic_factor", "PX4 의미 명확성"),
            ("fallback_factor", "대체 계산 영향"),
        ]
        lines = []
        for key_name, label in mapping:
            if key_name in conf_breakdown:
                lines.append(f"{label}: {cls._value_to_text(conf_breakdown.get(key_name))}")
        return lines

    @staticmethod
    def _duration_text_sec(value):
        try:
            return f"{float(value):.1f} s"
        except Exception:
            return ""

    @staticmethod
    def _intervals_text_sec(intervals, max_show=8):
        """Format list of (start, end) tuples as 'S1.0-E1.0 s/S2.0-E2.0 s/...' with truncation."""
        if not isinstance(intervals, (list, tuple)) or not intervals:
            return ""
        parts = []
        shown = 0
        for iv in intervals:
            if shown >= max_show:
                parts.append(f"...외 {len(intervals) - shown}개")
                break
            try:
                if isinstance(iv, (list, tuple)) and len(iv) >= 2:
                    s = float(iv[0])
                    e = float(iv[1])
                    parts.append(f"{s:.1f}-{e:.1f} s")
                    shown += 1
            except Exception:
                continue
        return "/".join(parts)

    @staticmethod
    def _unit_si_only(unit):
        """Strip statistical/semantic suffix from unit so display doesn't duplicate '평균 오차' etc."""
        text = str(unit or "").strip()
        if not text:
            return ""
        for suffix in (" MAE", " RMS", " peak/median", " CV", " mismatch", " duration", " residual", " gap", " eq"):
            while text.endswith(suffix):
                text = text[:-len(suffix)].strip()
        return text

    @classmethod
    def _evaluation_scope_lines(cls, payload):
        lines = []
        strategy = str(payload.get("evaluation_strategy", "") or "").strip()
        if strategy:
            lines.append("평가 방식: " + cls._simplify_evaluation_text(strategy))
        total_log = payload.get("total_log_time_sec", None)
        evaluated_time = payload.get("evaluated_time_sec", None)
        excluded_time = payload.get("excluded_time_sec", None)
        applied_ratio = payload.get("applied_ratio_pct", None)
        if total_log is not None:
            lines.append(f"전체 로그 시간: {cls._duration_text_sec(total_log)}")
        if evaluated_time is not None:
            lines.append(f"평가 적용 시간: {cls._duration_text_sec(evaluated_time)}")
        if excluded_time is not None:
            lines.append(f"평가 제외 시간: {cls._duration_text_sec(excluded_time)}")
        if applied_ratio is not None:
            lines.append(f"평가 적용률: {cls._value_to_text(applied_ratio)} %")
        applicable_modes = cls._clean_tooltip_list(payload.get("applicable_modes", []), limit=12)
        if applicable_modes:
            lines.append("평가 대상 비행모드 기준: " + ", ".join(applicable_modes))
        evaluated_modes = cls._clean_tooltip_list(payload.get("evaluated_modes", []), limit=12)
        if evaluated_modes:
            lines.append("적용된 비행모드 목록: " + ", ".join(evaluated_modes))
        excluded_modes = cls._clean_tooltip_list(payload.get("excluded_modes", []), limit=12)
        if excluded_modes:
            lines.append("제외된 비행모드 목록: " + ", ".join(excluded_modes))
        not_evaluated_reason = str(payload.get("not_evaluated_reason", "") or "").strip()
        if not_evaluated_reason:
            lines.append("평가 불가/제외 사유: " + cls._simplify_evaluation_text(not_evaluated_reason))
        return lines

    @classmethod
    def _mode_result_lines(cls, key, payload):
        results = payload.get("mode_results", [])
        if not isinstance(results, list):
            return []
        label = cls.EVALUATION_MEASUREMENT_LABELS.get(str(key or "").strip(), "측정값")
        lines = []
        for result in results[:8]:
            if not isinstance(result, dict):
                continue
            mode = str(result.get("mode", "") or "").strip()
            if not mode:
                continue
            status_label = cls._status_label_ko(result.get("status"), result.get("status_label", ""))
            try:
                value_text = f"{label} {float(result.get('value')):.3f}"
            except Exception:
                value_text = label
            unit_txt = cls._unit_si_only(result.get("unit", ""))
            if unit_txt:
                value_text = f"{value_text} {unit_txt}".strip()
            intervals_txt = cls._intervals_text_sec(result.get("time_intervals", []))
            if intervals_txt:
                time_txt = intervals_txt
            else:
                time_txt = cls._duration_text_sec(result.get("time_sec", 0.0))
            sample_count = result.get("sample_count", None)
            sample_txt = f" | 샘플 {sample_count}" if sample_count is not None else ""
            ratio = result.get("evaluated_ratio_pct", None)
            ratio_txt = ""
            if ratio is not None:
                ratio_txt = f" | 전체 평가시간 대비 {cls._value_to_text(ratio)}%"
            lines.append(f"{mode}: {status_label} | {value_text} | 적용시간 {time_txt}{ratio_txt}{sample_txt}")
        return lines

    @classmethod
    def _mode_verdict_lines(cls, payload):
        payload = payload if isinstance(payload, dict) else {}
        lines = []
        overall_avg_label = cls._status_label_ko(payload.get("overall_average_status"), payload.get("overall_average_status_label", ""))
        if overall_avg_label:
            lines.append(f"전체 평균 기준 판정: {overall_avg_label}")
        worst_mode_label = cls._status_label_ko(payload.get("worst_mode_status"), payload.get("worst_mode_status_label", ""))
        if worst_mode_label:
            lines.append(f"모드별 최악 판정: {worst_mode_label}")
        problem_modes = payload.get("problem_modes", [])
        if isinstance(problem_modes, list) and problem_modes:
            names = [str(item.get("mode", "")).strip() for item in problem_modes if isinstance(item, dict) and str(item.get("mode", "")).strip()]
            if names:
                lines.append("문제 발생 모드 목록: " + ", ".join(names))
            for item in problem_modes[:6]:
                if not isinstance(item, dict):
                    continue
                mode = str(item.get("mode", "") or "").strip()
                if not mode:
                    continue
                try:
                    value_text = f"{float(item.get('value')):.3f}"
                except Exception:
                    value_text = "-"
                unit_txt = cls._unit_si_only(item.get("unit", ""))
                intervals_txt = cls._intervals_text_sec(item.get("time_intervals", []))
                if intervals_txt:
                    time_txt = intervals_txt
                else:
                    time_txt = cls._duration_text_sec(item.get("time_sec", 0.0))
                ratio_txt = cls._value_to_text(item.get("evaluated_ratio_pct", 0.0))
                value_with_unit = f"{value_text} {unit_txt}".strip()
                lines.append(f"{mode}: 문제 모드 적용시간 {time_txt}, 평균 오차 {value_with_unit}, 전체 평가시간 대비 {ratio_txt}%")
        elif bool(payload.get("mode_attention_flag", False)):
            warning_modes = payload.get("warning_modes", [])
            names = [str(item.get("mode", "")).strip() for item in warning_modes if isinstance(item, dict) and str(item.get("mode", "")).strip()]
            if names:
                lines.append("모드별 확인 필요 구간: " + ", ".join(names))
        safety_issue_modes = [str(item.get("mode", "")).strip() for item in payload.get("safety_critical_issue_modes", []) if isinstance(item, dict) and str(item.get("mode", "")).strip()]
        if safety_issue_modes:
            lines.append("안전상 중요 모드 확인 권고: " + ", ".join(safety_issue_modes[:5]))
        for line in cls._clean_tooltip_list(payload.get("mode_interpretation_lines", []), limit=6):
            if line not in lines:
                lines.append(line)
        return lines

