    @classmethod
    def _evaluation_quant_lines(cls, key, value, unit, payload):
        lines = []
        measurement = cls._evaluation_measurement_text(key, value, unit)
        if measurement and measurement != "측정값 부족":
            lines.append(measurement)
        evidence_values = payload.get("evidence_values", {}) if isinstance(payload.get("evidence_values", {}), dict) else {}
        label_map = cls._evidence_label_map()
        for ev_key in sorted(evidence_values.keys()):
            lines.append(f"{label_map.get(ev_key, ev_key)}: {cls._value_to_text(evidence_values.get(ev_key))}")
        lines.extend(cls._confidence_lines_ko(payload.get("confidence_breakdown", {})))
        return lines

    @classmethod
    def _evaluation_final_summary(cls, key, display_name, status, value, unit, payload=None):
        payload = payload if isinstance(payload, dict) else {}
        measurement = cls._evaluation_measurement_text(key, value, unit)
        status_key = str(status or "").strip().lower()
        overall_avg_label = cls._status_label_ko(payload.get("overall_average_status"), payload.get("overall_average_status_label", ""))
        problem_modes = [str(item.get("mode", "")).strip() for item in payload.get("problem_modes", []) if isinstance(item, dict) and str(item.get("mode", "")).strip()]
        safety_modes = [str(item.get("mode", "")).strip() for item in payload.get("safety_critical_issue_modes", []) if isinstance(item, dict) and str(item.get("mode", "")).strip()]
        if bool(payload.get("mode_attention_flag", False)) and problem_modes:
            summary = (
                f"전체 시간 가중 평균 기준으로는 {overall_avg_label}입니다. "
                f"다만 {', '.join(problem_modes[:5])} 구간에서 문제 수준이 확인되었습니다. "
                "적용 시간이 긴 다른 모드가 평균을 끌어올렸을 수 있으므로, 문제 모드를 별도로 확대 확인해야 합니다."
            )
            if safety_modes:
                summary += f" 특히 {', '.join(safety_modes[:5])} 구간은 안전상 중요한 비행모드이므로 짧아도 우선 확인이 필요합니다."
            return summary
        if bool(payload.get("mode_attention_flag", False)):
            warning_modes = [str(item.get("mode", "")).strip() for item in payload.get("warning_modes", []) if isinstance(item, dict) and str(item.get("mode", "")).strip()]
            summary = (
                f"전체 시간 가중 평균 기준으로는 {overall_avg_label}입니다. "
                f"다만 {', '.join(warning_modes[:5])} 구간에서 모드별 확인이 필요한 신호가 있어 평균값만으로 단정하지 않는 것이 좋습니다."
            )
            if safety_modes:
                summary += f" 특히 {', '.join(safety_modes[:5])} 구간은 안전상 중요한 비행모드이므로 짧아도 우선 확인이 필요합니다."
            return summary
        if status_key in ("problem", "critical", "error"):
            return f"{display_name}가 크게 나타났습니다. {measurement} 수준이므로 재비행 전 관련 제어계와 센서 상태를 우선 점검하는 것이 좋습니다."
        if status_key in ("warning", "warn"):
            return f"{display_name}가 일부 구간에서 좋지 않을 가능성이 있습니다. {measurement} 기준으로 원인 구간을 먼저 확인하는 것을 권장합니다."
        if status_key in ("good", "normal", "ok"):
            return f"{display_name}는 현재 기준 안에 있습니다. {measurement} 수준이며 큰 이상 신호는 보이지 않습니다."
        if status_key == "excluded":
            return f"{display_name}는 적용 가능한 자동 비행모드 구간이 없어 점수에서 제외했습니다. 제외 구간을 문제로 간주하지 마세요."
        return f"{display_name}는 현재 로그만으로 충분히 판단하기 어렵습니다. 필요한 토픽 확보 여부를 먼저 확인하세요."

    @staticmethod
    def _format_tooltip_section(title, lines):
        clean_lines = [str(line).strip() for line in lines if str(line).strip()]
        if not clean_lines:
            return ""
        return f"[{title}]\n- " + "\n- ".join(clean_lines)

    @staticmethod
    def _tooltip_html_section(title, lines, *, accent="#EEF2FF"):
        # 평가/튜닝 셀 호버 시 보이는 HTML 툴팁의 한 섹션을 만드는 헬퍼. <div> 의 color/border 스타일을 바꾸면 툴팁 섹션의 글자색·구분선이 바뀝니다.
        clean_lines = [str(line).strip() for line in lines if str(line).strip()]
        if not clean_lines:
            return ""
        list_html = "".join(
            f"<li style='margin:0 0 4px 0;'>{html_escape(line)}</li>"
            for line in clean_lines
        )
        return (
            "<div style='margin:0 0 10px 0; padding:2px 0 8px 0; "
            "border:none; border-bottom:1px solid #E5E7EB;'>"
            f"<div style='font-weight:700; color:#162033; margin:0 0 4px 0;'>{html_escape(title)}</div>"
            f"<ul style='margin:0 0 0 18px; padding:0; color:#223046;'>{list_html}</ul>"
            "</div>"
        )

    @staticmethod
    def _localize_tooltip_text(text):
        # 영문 툴팁 문자열을 한글로 치환. replacements 사전의 값("[상위 이슈]" 등)을 바꾸면 툴팁의 한글 라벨이 바뀝니다.
        localized = str(text or "").strip()
        replacements = {
            "[Top Issues]": "[상위 이슈]",
            "[Likely Causes]": "[가능 원인]",
            "[Recommended Software Actions]": "[소프트웨어/파라미터 조치]",
            "[Recommended Hardware Actions]": "[하드웨어/기체 점검]",
            "[Recommended Actions]": "[권장 조치]",
            "[Priority Checks]": "[우선 확인]",
            "[Tuning Actions]": "[튜닝 조치]",
            "[Verification Checklist]": "[검증 체크리스트]",
            "Average confidence": "평균 신뢰도",
            "Tuning confidence": "튜닝 신뢰도",
            "Confidence": "신뢰도",
            "Value": "측정값",
            "Scope/Segment": "범위/구간",
            "Topics": "관련 토픽",
            "Signals": "관련 신호",
            "Suggestion": "제안",
            "(conf ": "(신뢰도 ",
        }
        for old, new in replacements.items():
            localized = localized.replace(old, new)
        return localized

    def _metric_graph_guidance(self, key, name, payload=None, is_tuning=False):
        payload = payload if isinstance(payload, dict) else {}
        status = payload.get("status", payload.get("overall_status", ""))
        graph_titles = self._metric_graph_titles_for_status(key, name, payload, status)
        guidance = []
        if graph_titles:
            guidance.append("추천 그래프: " + " / ".join(graph_titles[:4]))

        text_blob = " ".join(
            str(x or "")
            for x in [
                key,
                name,
                payload.get("reason", ""),
                payload.get("evidence", ""),
                payload.get("suggestion", ""),
                payload.get("title", ""),
                payload.get("issue_id", ""),
            ]
        ).lower()
        guidance.append("해당 행이 악화된 시간대를 먼저 좁히고, 관련 그래프를 같은 X축으로 묶어 확대합니다.")
        if key == "tecs_altitude_tracking_error":
            guidance.append("PX4 TECS는 throttle로 total energy, pitch로 speed-vs-height balance를 조절합니다. 고도 오차만 보지 말고 pitch 추종과 throttle 반응을 함께 봐야 합니다.")
            guidance.append("고도 추종이 느리면 Altitude vs Altitude Setpoint와 Pitch Angle, TECS throttle 그래프를 같은 구간에서 비교해 altitude lag가 pitch 부족인지 throttle 여유 부족인지 구분합니다.")
        elif key == "tecs_airspeed_tracking_error":
            guidance.append("속도 오차는 TAS 추종만 보면 부족합니다. Airspeed vs GPS Ground Speed와 Pitch/Throttle 그래프를 함께 보고, 속도 회복을 위해 고도를 과하게 희생하는지 같이 확인합니다.")
        elif key == "tecs_energy_balance_error":
            guidance.append("에너지 평가는 고도와 속도를 동시에 봐야 합니다. 고도 회복 시 속도가 무너지는지, 또는 속도 유지 때문에 고도 추종이 늦는지를 같은 시간축에서 확인합니다.")
        elif key == "airspeed_scale_appropriateness":
            guidance.append("PX4 공식 가이드는 tas_scale_validated 수렴 여부와 TAS가 wind-corrected groundspeed와 일치하는지를 함께 보라고 안내합니다.")
            guidance.append("validated scale 토픽이 없으면 이 툴은 순항 구간 TAS vs GPS 속도 평균 차이로 조건부 판정을 내립니다. 이 경우 바람 정보가 없어 보수적으로 해석해야 합니다.")
        elif key == "navigation_path_tracking_error":
            guidance.append("항법 평가는 2D Flight Path와 roll/yaw 응답을 같이 봐야 합니다. 경로 overshoot가 roll 추종 문제인지 NPFG/path tuning 문제인지 분리해서 봅니다.")
        elif key == "navigation_path_tracking_reliability":
            guidance.append("이 항목은 순수 경로 오차가 아니라 해석 신뢰도입니다. 2D Path가 좋아 보여도 NAV_ACC_RAD 대비 tail error와 xy_valid가 나쁘면 별도 경고가 날 수 있습니다.")
            guidance.append("경로 형태와 점수를 같이 볼 때는 2D Flight Path뿐 아니라 local_position valid 플래그와 GPS/estimator 상태를 함께 확인해야 합니다.")
        elif any(token in text_blob for token in ("rate", "attitude", "roll", "pitch", "yaw", "tracking", "setpoint")):
            guidance.append("Roll/Pitch/Yaw Actual vs Setpoint, Angular Rate Actual vs Setpoint를 함께 열어 지연, overshoot, 진동을 확인합니다.")
        elif any(token in text_blob for token in ("vibration", "imu", "clip", "gyro", "accel")):
            guidance.append("IMU vibration/clipping 계열 신호와 actuator output을 같은 구간에서 비교해 기체 진동 또는 포화 여부를 봅니다.")
        elif any(token in text_blob for token in ("gps", "position", "estimator", "ekf", "innovation", "local_position")):
            guidance.append("estimator/gps/local position 관련 신호에서 innovation, accuracy, position jump가 같은 시점에 발생했는지 확인합니다.")
        elif any(token in text_blob for token in ("battery", "voltage", "current", "power", "throttle")):
            guidance.append("battery voltage/current sag와 throttle/actuator 출력 상승이 동시에 나타나는지 확인합니다.")
        if is_tuning:
            guidance.append("튜닝 변경 전에는 동일 로그 내 setpoint 추종성, 출력 포화, 진동 증가 여부를 먼저 확인합니다.")
        return guidance

