        self.btn_workspace_v_split.clicked.connect(self._on_workspace_v_split_clicked)

        control_layout.addStretch()
        control_layout.addWidget(self.lbl_aircraft_type, 0, Qt.AlignVCenter)
        control_layout.addWidget(self.btn_reset_zoom, 0, Qt.AlignVCenter)
        control_layout.addWidget(self.btn_workspace_px, 0, Qt.AlignVCenter)
        control_layout.addWidget(self.btn_workspace_view_reset, 0, Qt.AlignVCenter)
        control_layout.addWidget(self.btn_workspace_grid_action, 0, Qt.AlignVCenter)
        control_layout.addWidget(self.btn_workspace_h_split, 0, Qt.AlignVCenter)
        control_layout.addWidget(self.btn_workspace_v_split, 0, Qt.AlignVCenter)

        self.grid_root = QSplitter(Qt.Vertical)
