    def __init__(self):
        # 메인 창 전체 초기화. 여기서 로드된 로그 캐시/단축키/스플리터 기본 비율 같은 기본값이 정해집니다.
        super().__init__()
        # 메인 창 기본 레이아웃. setWindowTitle(APP_DISPLAY_NAME) 로 창 제목이 정해지고, resize(1400, 700) 의 픽셀 값을 키우면 시작 시 창 크기가 커집니다.
        self.setWindowTitle(APP_DISPLAY_NAME)
        self.resize(1400, 700)
        self.setAcceptDrops(True)
        self._signal_drop_hover_plot = None
        self._ui_icon_cache = None
        self._main_icon_override_path = None
        self._ui_icon_override_path = None
