    def set_plot_text_pt_override(self, pt_value=None):
        # 그래프 텍스트 크기 자동조절을 끄고 사용자가 정한 pt 값으로 고정. showMessage 의 "그래프 텍스트 크기를 자동 조절로 복원했습니다." 문자열을 바꾸면 상태바 안내가 바뀝니다.
        try:
            self.plot_text_pt_override = float(pt_value) if pt_value is not None else None
        except Exception:
            self.plot_text_pt_override = None

        for plot_widget in self.findChildren(AdvancedPlot):
            plot_widget._last_text_scale_key = None
            plot_widget._apply_adaptive_plot_text_scale()

        if self.plot_text_pt_override is None:
            self.statusBar().showMessage("그래프 텍스트 크기를 자동 조절로 복원했습니다.", 3000)
        else:
            self.statusBar().showMessage(
                f"그래프 legend/index 텍스트 크기: {self.plot_text_pt_override:.1f} pt",
                3000,
            )
        self.statusBar().showMessage("Ready | Upload log file", 5000)

    def _icon_search_roots(self):
        # 프로그램 아이콘을 찾을 후보 폴더 리스트를 반환. 보통 수정 X.
        roots = []
        if getattr(sys, "frozen", False):
            try:
                roots.append(os.path.dirname(sys.executable))
            except Exception:
                pass
            meipass = getattr(sys, "_MEIPASS", None)
            if meipass:
                roots.append(meipass)
        roots.append(os.path.abspath(os.path.join(src_dir, "../../")))
        roots.append(os.path.abspath(os.path.join(src_dir, "../")))
        roots.append(os.getcwd())
        unique = []
        seen = set()
        for r in roots:
            if not r or r in seen:
                continue
            seen.add(r)
            unique.append(r)
        return unique

    @staticmethod
    def _default_icon_override_dir():
        # 사용자 아이콘 설정 파일을 저장할 기본 폴더 경로를 반환. 보통 수정 X.
        candidates = []
        try:
            app_config_dir = QStandardPaths.writableLocation(QStandardPaths.AppConfigLocation)
            if app_config_dir:
                candidates.append(app_config_dir)
        except Exception:
            pass
        candidates.append(os.path.join(os.path.abspath(os.path.join(src_dir, "../")), "user_config"))
        for path in candidates:
            if not path:
                continue
            try:
                os.makedirs(path, exist_ok=True)
                return path
            except Exception:
                continue
        return os.path.abspath(os.path.join(src_dir, "../"))

    @classmethod
    def _icon_override_config_path(cls):
        # 아이콘 오버라이드 설정 JSON 파일의 전체 경로를 반환. 보통 수정 X.
        return os.path.join(cls._default_icon_override_dir(), cls.ICON_OVERRIDE_CONFIG_NAME)

    @staticmethod
    def _normalize_icon_override_path(path_text):
        if not path_text:
            return None
        try:
            normalized = os.path.abspath(os.path.expanduser(str(path_text).strip()))
        except Exception:
            return None
        return normalized if normalized else None

    def _load_icon_overrides(self):
        # 저장된 사용자 아이콘 경로를 디스크에서 읽어옴. 자동 호출 — 보통 수정 X.
        self._main_icon_override_path = None
        self._ui_icon_override_path = None
        config_path = self._icon_override_config_path()
        if not os.path.exists(config_path):
            return
        try:
            with open(config_path, "r", encoding="utf-8") as f:
                data = json.load(f)
        except Exception:
            return
        if not isinstance(data, dict):
            return
        self._main_icon_override_path = self._normalize_icon_override_path(data.get("main_icon"))
        self._ui_icon_override_path = self._normalize_icon_override_path(data.get("ui_icon"))

    def _save_icon_overrides(self):
        # 사용자 아이콘 경로 설정을 JSON 으로 디스크에 저장. QMessageBox 의 "아이콘 설정 저장 실패:\n{e}" 문자열을 바꾸면 저장 실패 안내가 바뀝니다.
        config_path = self._icon_override_config_path()
        payload = {
            "main_icon": self._main_icon_override_path or "",
            "ui_icon": self._ui_icon_override_path or "",
        }
        try:
            os.makedirs(os.path.dirname(config_path), exist_ok=True)
            with open(config_path, "w", encoding="utf-8") as f:
                json.dump(payload, f, ensure_ascii=False, indent=2)
            return True
        except Exception as e:
            QMessageBox.warning(self, "Settings", f"아이콘 설정 저장 실패:\n{e}")
            return False

    def _resolve_main_icon_override_path(self):
        path = self._normalize_icon_override_path(self._main_icon_override_path)
        return path if path and os.path.exists(path) else None

    def _resolve_ui_icon_override_path(self):
        path = self._normalize_icon_override_path(self._ui_icon_override_path)
        return path if path and os.path.exists(path) else None

    def _select_icon_override_file(self, title, current_path=None):
        # 아이콘 파일을 선택하는 파일 대화상자. "Icon/Image Files (*.ico *.png *.svg *.jpg *.jpeg *.bmp);;All Files (*)" 필터 문자열을 바꾸면 선택 가능한 파일 형식이 바뀝니다.
        start_path = ""
        resolved_current = self._normalize_icon_override_path(current_path)
        if resolved_current and os.path.exists(resolved_current):
            start_path = resolved_current
        file_path, _ = QFileDialog.getOpenFileName(
            self,
            title,
            start_path,
            "Icon/Image Files (*.ico *.png *.svg *.jpg *.jpeg *.bmp);;All Files (*)",
        )
        if not file_path:
            return None
        return self._normalize_icon_override_path(file_path)

    def _change_program_icon(self):
        # 프로그램 자체 아이콘(작업표시줄 등) 변경 — 파일 선택 후 적용. "프로그램 아이콘 선택" / QMessageBox 의 "선택한 파일을 프로그램 아이콘으로 사용할 수 없습니다." / showMessage 의 "프로그램 아이콘 변경 완료: {}" 문자열을 바꾸면 화면 안내가 바뀝니다.
        current_path = self._resolve_main_icon_override_path() or self._find_main_icon_path()
        file_path = self._select_icon_override_file("프로그램 아이콘 선택", current_path=current_path)
        if not file_path:
            return
        icon = QIcon(file_path)
        if icon.isNull():
            QMessageBox.warning(self, "Settings", "선택한 파일을 프로그램 아이콘으로 사용할 수 없습니다.")
            return
        self._main_icon_override_path = file_path
        self._save_icon_overrides()
        self._apply_brand_icon()
        self.statusBar().showMessage(f"프로그램 아이콘 변경 완료: {os.path.basename(file_path)}", 4000)

    def _change_top_left_logo(self):
        # 좌상단 사용자 로고 변경. 회사 전용 기본 자산은 포함하지 않는다.
        current_path = self._resolve_ui_icon_override_path() or self._find_ui_icon_path()
        file_path = self._select_icon_override_file("좌상단 로고 선택", current_path=current_path)
        if not file_path:
            return
        pixmap = QPixmap(file_path)
        if pixmap.isNull():
            icon = QIcon(file_path)
            if icon.isNull():
                QMessageBox.warning(self, "Settings", "선택한 파일을 좌상단 로고로 사용할 수 없습니다.")
                return
        self._ui_icon_override_path = file_path
        self._ui_icon_cache = None
        self._save_icon_overrides()
        self._apply_brand_icon()
        self.statusBar().showMessage(f"좌상단 로고 변경 완료: {os.path.basename(file_path)}", 4000)

    def _reset_icon_overrides(self):
        # 사용자 아이콘 설정을 초기화하고 기본 아이콘으로 복원. showMessage 의 "아이콘이 이미 기본값 상태입니다." / "기본 아이콘으로 복원했습니다." 문자열을 바꾸면 상태바 안내가 바뀝니다.
        if not self._main_icon_override_path and not self._ui_icon_override_path:
            self.statusBar().showMessage("아이콘이 이미 기본값 상태입니다.", 3000)
            return
        self._main_icon_override_path = None
        self._ui_icon_override_path = None
        self._ui_icon_cache = None
        self._save_icon_overrides()
        self._apply_brand_icon()
        self.statusBar().showMessage("기본 아이콘으로 복원했습니다.", 4000)

    @staticmethod
    def _default_desktop_dir():
        try:
            desktop_dir = QStandardPaths.writableLocation(QStandardPaths.DesktopLocation)
            if desktop_dir:
                return desktop_dir
        except Exception:
            pass
        return os.path.expanduser("~/Desktop")

    @staticmethod
    def _safe_export_stem(name):
        stem = re.sub(r"[^0-9A-Za-z가-힣._-]+", "_", str(name or "metadata").strip())
        return stem.strip("._-") or "metadata"

    @staticmethod
    def _write_rows_to_csv(output_path, headers, rows):
        with open(output_path, "w", newline="", encoding="utf-8-sig") as f:
            writer = csv.writer(f)
            if headers:
                writer.writerow(headers)
            writer.writerows(rows or [])

    @staticmethod
    def _join_csv_texts(values):
        if not isinstance(values, (list, tuple)):
            return ""
        cleaned = []
        for value in values:
            text = str(value).strip()
            if text:
                cleaned.append(text)
        return " | ".join(cleaned)

    @staticmethod
    def _format_mode_entries_csv(entries):
        if not isinstance(entries, (list, tuple)):
            return ""
        parts = []
        for e in entries:
            if not isinstance(e, dict):
                text = str(e).strip()
                if text:
                    parts.append(text)
                continue
            mode = str(e.get("mode", "") or "").strip()
            if not mode:
                continue
            status = str(e.get("status_label", e.get("status", "")) or "").strip()
            val = e.get("value", None)
            unit = str(e.get("unit", "") or "").strip()
            t_sec = e.get("time_sec", None)
            ratio = e.get("evaluated_ratio_pct", None)
            extras = []
            if status:
                extras.append(status)
            if val is not None:
                try:
                    extras.append(f"mean={float(val):.3f}{(' ' + unit) if unit else ''}")
                except Exception:
                    pass
            if t_sec is not None:
                try:
                    extras.append(f"t={float(t_sec):.1f}s")
                except Exception:
                    pass
            if ratio is not None:
                try:
                    extras.append(f"ratio={float(ratio):.1f}%")
                except Exception:
                    pass
            parts.append(f"{mode}({', '.join(extras)})" if extras else mode)
        return " | ".join(parts)

    @staticmethod
    def _format_mode_results_summary_csv(results):
        # results: list of dicts with mode/status/value/unit/time_sec/evaluated_ratio_pct
        if not isinstance(results, (list, tuple)):
            return ""
        parts = []
        for r in results:
            if not isinstance(r, dict):
                continue
            mode = str(r.get("mode", "") or "").strip()
            if not mode:
                continue
            status = str(r.get("status_label", r.get("status", "")) or "").strip() or "-"
            unit = str(r.get("unit", "") or "").strip()
            val = r.get("value", None)
            try:
                val_text = f"{float(val):.3f}{(' ' + unit) if unit else ''}" if val is not None else "-"
            except Exception:
                val_text = "-"
            try:
                t_text = f"{float(r.get('time_sec', 0.0) or 0.0):.1f}s"
            except Exception:
                t_text = "-"
            try:
                ratio_text = f"{float(r.get('evaluated_ratio_pct', 0.0) or 0.0):.1f}%"
            except Exception:
                ratio_text = "-"
            parts.append(f"{mode}: {status}, mean={val_text}, t={t_text}, ratio={ratio_text}")
        return " | ".join(parts)

    @staticmethod
    def _scoring_policy_from_item(item):
        if not isinstance(item, dict):
            return ""
        mode_results = item.get("mode_results")
        applicable = item.get("applicable_modes") or []
        excluded = item.get("excluded_modes") or []
        if isinstance(mode_results, list) and mode_results:
            return "mode_aware"
        if applicable or excluded:
            return "mode_aware_no_results"
        status = str(item.get("status", "") or "").lower()
        if status in ("excluded", "unavailable"):
            return "not_evaluated"
        return "all_log"

    @staticmethod
    def _mode_names_csv(entries):
        if not isinstance(entries, (list, tuple)):
            return ""
        names = []
        for e in entries:
            if isinstance(e, dict):
                name = str(e.get("mode", "") or "").strip()
            else:
                name = str(e or "").strip()
            if name and name not in names:
                names.append(name)
        return " | ".join(names)

    def _open_ulg_to_csv_export_dialog(self):
        # ULG → CSV 변환 팝업을 띄우고 결과를 받아 실제 export 실행. QMessageBox 의 "먼저 로그를 로드해 주세요." / "선택한 로그를 찾지 못했습니다." / "출력 CSV 경로가 비어 있습니다." / "선택된 토픽이 없습니다." / "CSV 내보내기 실패:\n{e}" / "ULG to CSV 내보내기 완료" 등 문자열을 바꾸면 안내 팝업 문구가 바뀝니다.
        if not self.loaded_datasets:
            QMessageBox.information(self, "ULG to CSV", "먼저 로그를 로드해 주세요.")
            return
        file_names = list(self.loaded_datasets.keys())
        dialog = UlgCsvExportDialog(
            file_names=file_names,
            datasets_by_name=self.loaded_datasets,
            active_file=self.active_analysis_log if self.active_analysis_log in self.loaded_datasets else (file_names[0] if file_names else None),
            default_output_dir=self._default_desktop_dir(),
            parent=self,
        )
        if dialog.exec() != QDialog.Accepted:
            return
        result = dialog.result_data() or {}
        file_name = result.get("file_name", "").strip()
        output_path = result.get("output_path", "").strip()
        selected_topics = list(result.get("selected_topics", []))
        if not file_name or file_name not in self.loaded_datasets:
            QMessageBox.warning(self, "ULG to CSV", "선택한 로그를 찾지 못했습니다.")
            return
        if not output_path:
            QMessageBox.warning(self, "ULG to CSV", "출력 CSV 경로가 비어 있습니다.")
            return
        if not selected_topics:
            QMessageBox.information(self, "ULG to CSV", "선택된 토픽이 없습니다.")
            return
        try:
            summary = self._export_merged_topics_csv(file_name, output_path, selected_topics)
        except Exception as e:
            QMessageBox.warning(self, "ULG to CSV", f"CSV 내보내기 실패:\n{e}")
            return

        merged_rows = int(summary.get("row_count", 0))
        merged_cols = int(summary.get("column_count", 0))
        topic_count = int(summary.get("topic_count", 0))
        msg_lines = [
            "ULG to CSV 내보내기 완료",
            f"로그: {file_name}",
            f"저장 파일: {output_path}",
            f"토픽 수: {topic_count}",
            f"행 / 열: {merged_rows} / {merged_cols}",
        ]
        self.statusBar().showMessage(
            f"ULG to CSV 완료: {os.path.basename(output_path)} ({merged_rows} rows × {merged_cols} cols)",
            5000,
        )
        QMessageBox.information(self, "ULG to CSV", "\n".join(msg_lines))

    def _export_merged_topics_csv(self, file_name, output_path, selected_topics):
        """Merge selected topics into a single CSV file.

        - First column is always `timestamp` (μs, from ULog).
        - All selected topic timestamps are unioned to form the unified
          timeline; each topic's columns are forward-filled (last known value)
          onto that timeline so topics with different sampling rates align
          row-by-row.
        - Non-timestamp columns are renamed `<topic_unique_name>.<field>` to
          avoid collisions when multiple topics share field names.
        """
        import polars as pl
        import numpy as np

        dataset = self.loaded_datasets.get(file_name)
        if dataset is None:
            raise ValueError("선택한 로그 dataset을 찾지 못했습니다.")

        topic_frames = []
        timestamp_arrays = []
        for unique_name in selected_topics:
            topic = (getattr(dataset, "topics", {}) or {}).get(unique_name)
            if topic is None:
                continue
            df = getattr(topic, "dataframe", None)
            if df is None or len(df) == 0:
                continue
            if "timestamp" not in df.columns:
                continue

            sorted_df = df.sort("timestamp")
            # Drop derived columns we do not want in the merged output.
            drop_cols = [c for c in ("timestamp_sec",) if c in sorted_df.columns]
            if drop_cols:
                sorted_df = sorted_df.drop(drop_cols)
            # Cast timestamp to a common Int64 dtype so all topics align under
            # join_asof regardless of the source dtype (uint64 / int64).
            sorted_df = sorted_df.with_columns(pl.col("timestamp").cast(pl.Int64))
            # Prefix every non-timestamp column with the topic identifier.
            rename_map = {
                col: f"{unique_name}.{col}"
                for col in sorted_df.columns
                if col != "timestamp"
            }
            if rename_map:
                sorted_df = sorted_df.rename(rename_map)

            topic_frames.append((unique_name, sorted_df))
            timestamp_arrays.append(sorted_df.get_column("timestamp").to_numpy())

        if not topic_frames:
            raise ValueError("내보낼 토픽 데이터가 없습니다.")

        # Build unified timeline: union of all selected topic timestamps,
        # sorted ascending and unique.
        unified_ts = np.unique(np.concatenate(timestamp_arrays))
        merged = pl.DataFrame({"timestamp": pl.Series(unified_ts).cast(pl.Int64)})

        # Forward-fill each topic onto the unified timeline using join_asof
        # with strategy="backward" (latest record where topic.ts <= base.ts).
        for unique_name, frame in topic_frames:
            merged = merged.join_asof(frame, on="timestamp", strategy="backward")

        # Make sure `timestamp` is always the first column.
        cols = merged.columns
        if cols and cols[0] != "timestamp":
            ordered = ["timestamp"] + [c for c in cols if c != "timestamp"]
            merged = merged.select(ordered)

        os.makedirs(os.path.dirname(os.path.abspath(output_path)) or ".", exist_ok=True)
        merged.write_csv(output_path)

        return {
            "row_count": int(len(merged)),
            "column_count": int(len(merged.columns)),
            "topic_count": len(topic_frames),
            "output_path": output_path,
        }

    def _export_loaded_log_csv_bundle(self, file_name, output_dir, selected_keys):
        dataset = self.loaded_datasets.get(file_name)
        if dataset is None:
            raise ValueError("선택한 로그 dataset을 찾지 못했습니다.")
        os.makedirs(output_dir, exist_ok=True)

        metadata = self.loaded_log_metadata.get(file_name, {}) or {}
        aircraft_type = self.loaded_aircraft_types.get(file_name, "Unknown")
        log_stem = self._safe_export_stem(os.path.splitext(os.path.basename(file_name))[0])

        exported_paths = []
        topic_file_count = 0
        topics_dir = ""

        def root_csv_path(suffix):
            return os.path.join(output_dir, f"{log_stem}__{suffix}.csv")

        selected = set(selected_keys or [])
        if "summary" in selected:
            path = root_csv_path("summary")
            self._export_log_summary_csv(path, file_name, dataset, metadata, aircraft_type)
            exported_paths.append(path)
        if "firmware" in selected:
            path = root_csv_path("firmware_info")
            self._export_key_value_csv(path, metadata.get("firmware", {}) or {}, key_header="key", value_header="value")
            exported_paths.append(path)
        if "parameters" in selected:
            path = root_csv_path("parameters")
            self._export_key_value_csv(path, metadata.get("parameters", {}) or {}, key_header="parameter", value_header="value")
            exported_paths.append(path)
        if "messages" in selected:
            path = root_csv_path("messages")
            self._export_messages_csv(path, metadata.get("messages", []) or [])
            exported_paths.append(path)
        if "evaluation" in selected:
            path = root_csv_path("evaluation")
            self._export_single_log_evaluation_csv(path, file_name, metadata.get("evaluation", {}) or {}, aircraft_type)
            exported_paths.append(path)
        if "issues" in selected:
            path = root_csv_path("issues")
            self._export_single_log_issue_csv(path, file_name, metadata.get("evaluation", {}) or {}, aircraft_type)
            exported_paths.append(path)
        if "topics" in selected:
            topics_dir, topic_paths = self._export_dataset_topics_csv_bundle(output_dir, log_stem, dataset)
            exported_paths.extend(topic_paths)
            topic_file_count = len(topic_paths)

        return {
            "exported_file_count": len(exported_paths),
            "exported_paths": exported_paths,
            "topic_file_count": topic_file_count,
            "topics_dir": topics_dir,
        }

    def _export_log_summary_csv(self, output_path, file_name, dataset, metadata, aircraft_type):
        topic_count = len(getattr(dataset, "topics", {}) or {})
        signal_count = 0
        for topic in (getattr(dataset, "topics", {}) or {}).values():
            try:
                signal_count += len(getattr(topic, "signals", {}) or {})
            except Exception:
                continue
        evaluation = metadata.get("evaluation", {}) if isinstance(metadata, dict) else {}
        rows = [
            ["file_name", file_name],
            ["aircraft_type", aircraft_type],
            ["topic_count", topic_count],
            ["signal_count", signal_count],
            ["firmware_item_count", len(metadata.get("firmware", {}) or {}) if isinstance(metadata, dict) else 0],
            ["parameter_count", len(metadata.get("parameters", {}) or {}) if isinstance(metadata, dict) else 0],
            ["message_count", len(metadata.get("messages", []) or []) if isinstance(metadata, dict) else 0],
            ["evaluation_overall_score", evaluation.get("overall_score", "") if isinstance(evaluation, dict) else ""],
            ["evaluation_overall_status", evaluation.get("overall_status_label", evaluation.get("overall_status", "")) if isinstance(evaluation, dict) else ""],
            ["evaluation_metric_count", len(evaluation.get("items", []) or []) if isinstance(evaluation, dict) else 0],
            ["evaluation_issue_count", len(evaluation.get("issues", []) or []) if isinstance(evaluation, dict) else 0],
        ]
        self._write_rows_to_csv(output_path, ["key", "value"], rows)

    def _export_key_value_csv(self, output_path, data_map, key_header="key", value_header="value"):
        rows = []
        for key in sorted((data_map or {}).keys(), key=lambda x: str(x).lower()):
            rows.append([str(key), self._metadata_value_to_text((data_map or {}).get(key))])
        self._write_rows_to_csv(output_path, [key_header, value_header], rows)

    def _export_messages_csv(self, output_path, messages):
        rows = []
        for item in messages or []:
            if isinstance(item, dict):
                rows.append([
                    self._metadata_value_to_text(item.get("timestamp", "")),
                    self._metadata_value_to_text(item.get("level", "")),
                    self._metadata_value_to_text(item.get("text", "")),
                ])
            else:
                rows.append(["", "", self._metadata_value_to_text(item)])
        self._write_rows_to_csv(output_path, ["timestamp", "level", "text"], rows)

    def _export_single_log_evaluation_csv(self, output_path, file_name, evaluation, aircraft_type):
        headers = [
            "file_name", "aircraft_type", "metric_key", "metric_name", "score", "status",
            "value", "unit", "confidence(%)", "scope", "segment", "reason", "evidence",
            "topics", "missing_topics", "signals", "px4_version", "reference_class", "signal_semantics",
            "threshold_source", "mode_gate", "evaluated_modes", "fallback_used", "fallback_source",
            "confidence_breakdown_json", "evidence_values_json", "likely_causes", "priority_checks", "tuning_actions",
            "verification_checklist", "recommendation",
            # Mode-aware fields (backward compatible — appended at end)
            "overall_average_status", "worst_mode_status", "final_display_status",
            "problem_modes", "warning_modes", "safety_critical_issue_modes",
            "applied_modes", "excluded_modes",
            "applicable_duration_sec", "excluded_duration_sec", "applied_ratio(%)",
            "evaluation_basis", "scoring_policy", "exclusion_reason", "mode_results_summary",
        ]
        rows = []
        eval_data = evaluation if isinstance(evaluation, dict) else {}
        # Overall row: mode-aware fields are N/A (overall is aggregate, not per-mode)
        rows.append([
            file_name,
            aircraft_type,
            "overall",
            "Overall",
            eval_data.get("overall_score", ""),
            eval_data.get("overall_status_label", eval_data.get("overall_status", "")),
            "",
            "",
            (eval_data.get("confidence_summary", {}) or {}).get("average_confidence", ""),
            "overall",
            "all",
            self._join_csv_texts(eval_data.get("top_issues", [])[:5]),
            "",
            "",
            "",
            eval_data.get("px4_version", ""),
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            json.dumps(eval_data.get("confidence_summary", {}), ensure_ascii=False),
            "",
            self._join_csv_texts((eval_data.get("recommendation_view", {}) or {}).get("likely_causes", [])[:10]),
            "",
            self._join_csv_texts((eval_data.get("recommendation_view", {}) or {}).get("recommended_software_actions", [])[:10]),
            self._join_csv_texts((eval_data.get("recommendation_view", {}) or {}).get("verification_checklist", [])[:10]),
            self._join_csv_texts(list((eval_data.get("recommendation_view", {}) or {}).get("recommended_hardware_actions", [])[:10]) + list(eval_data.get("recommended_actions", [])[:5])),
            # Mode-aware fields (overall row → N/A)
            "N/A", "N/A", eval_data.get("overall_status_label", eval_data.get("overall_status", "")),
            "N/A", "N/A", "N/A",
            "N/A", "N/A",
            "N/A", "N/A", "N/A",
            "overall", "all_log_aggregate", "N/A", "N/A",
        ])
        for item in eval_data.get("items", []) or []:
            if not isinstance(item, dict):
                continue
            problem_modes_list = item.get("problem_modes", []) or []
            warning_modes_list = item.get("warning_modes", []) or []
            safety_modes_list = item.get("safety_critical_issue_modes", []) or []
            mode_results_list = item.get("mode_results", []) or []
            evaluated_modes_list = item.get("evaluated_modes", []) or []
            excluded_modes_list = item.get("excluded_modes", []) or []
            applicable_duration = item.get("evaluated_time_sec")
            excluded_duration = item.get("excluded_time_sec")
            applied_ratio = item.get("applied_ratio_pct")
            evaluation_basis = item.get("evaluation_strategy", "") or ""
            exclusion_reasons = item.get("excluded_reasons", []) or []
            not_evaluated_reason = item.get("not_evaluated_reason", "") or ""
            # If item is excluded/unavailable and no mode_results, surface not_evaluated_reason as exclusion_reason
            exclusion_reason_csv = self._join_csv_texts(exclusion_reasons)
            if not exclusion_reason_csv and not_evaluated_reason:
                exclusion_reason_csv = str(not_evaluated_reason)
            rows.append([
                file_name,
                aircraft_type,
                item.get("key", ""),
                item.get("name", item.get("key", "")),
                item.get("score", ""),
                item.get("status_label", item.get("status", "")),
                item.get("value", ""),
                item.get("unit", ""),
                item.get("confidence", item.get("metric_confidence", "")),
                item.get("scope", "common"),
                item.get("segment", "all"),
                item.get("reason", ""),
                item.get("evidence", ""),
                self._join_csv_texts(item.get("found_topics", [])),
                self._join_csv_texts(item.get("missing_topics", [])),
                self._join_csv_texts(item.get("used_signals", [])),
                item.get("px4_version", eval_data.get("px4_version", "")),
                item.get("reference_class", ""),
                item.get("signal_semantics", ""),
                item.get("threshold_source", ""),
                item.get("mode_gate", ""),
                self._join_csv_texts(evaluated_modes_list),
                item.get("fallback_used", ""),
                item.get("fallback_source", ""),
                json.dumps(item.get("confidence_breakdown", {}), ensure_ascii=False),
                json.dumps(item.get("evidence_values", {}), ensure_ascii=False),
                self._join_csv_texts(item.get("likely_causes", [])),
                self._join_csv_texts(item.get("priority_checks", [])),
                self._join_csv_texts(item.get("tuning_actions", [])),
                self._join_csv_texts(item.get("verification_checklist", [])),
                item.get("recommendation", item.get("suggestion", "")),
                # Mode-aware columns
                str(item.get("overall_average_status_label", item.get("overall_average_status", "")) or ""),
                str(item.get("worst_mode_status_label", item.get("worst_mode_status", "")) or ""),
                str(item.get("status_label", item.get("status", "")) or ""),
                self._format_mode_entries_csv(problem_modes_list),
                self._format_mode_entries_csv(warning_modes_list),
                self._format_mode_entries_csv(safety_modes_list),
                self._join_csv_texts(evaluated_modes_list),
                self._join_csv_texts(excluded_modes_list),
                ("" if applicable_duration is None else f"{float(applicable_duration):.3f}"),
                ("" if excluded_duration is None else f"{float(excluded_duration):.3f}"),
                ("" if applied_ratio is None else f"{float(applied_ratio):.3f}"),
                evaluation_basis,
                self._scoring_policy_from_item(item),
                exclusion_reason_csv,
                self._format_mode_results_summary_csv(mode_results_list),
            ])
        self._write_rows_to_csv(output_path, headers, rows)

    def _export_single_log_issue_csv(self, output_path, file_name, evaluation, aircraft_type):
        headers = [
            "file_name", "aircraft_type", "overall_score", "overall_status", "issue_id", "title",
            "severity", "segment", "confidence(%)", "evidence", "metric_value_json",
            "threshold_reference_json", "likely_causes", "software_actions", "hardware_actions",
            "verification_checklist", "tuning_candidates",
        ]
        rows = []
        eval_data = evaluation if isinstance(evaluation, dict) else {}
        issues = eval_data.get("issues", []) if isinstance(eval_data, dict) else []
        if not issues:
            rows.append([
                file_name,
                aircraft_type,
                eval_data.get("overall_score", ""),
                eval_data.get("overall_status_label", eval_data.get("overall_status", "")),
                "",
                "",
                "N/A",
                "",
                "",
                "No tuning issues generated",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
            ])
        else:
            for issue in issues:
                if not isinstance(issue, dict):
                    continue
                rows.append([
                    file_name,
                    aircraft_type,
                    eval_data.get("overall_score", ""),
                    eval_data.get("overall_status_label", eval_data.get("overall_status", "")),
                    issue.get("issue_id", ""),
                    issue.get("title", ""),
                    issue.get("severity", ""),
                    issue.get("segment", ""),
                    issue.get("confidence", ""),
                    issue.get("evidence", ""),
                    json.dumps(issue.get("metric_value", {}), ensure_ascii=False),
                    json.dumps(issue.get("threshold_reference", {}), ensure_ascii=False),
                    self._join_csv_texts(issue.get("likely_causes", [])),
                    self._join_csv_texts(issue.get("software_actions", [])),
                    self._join_csv_texts(issue.get("hardware_actions", [])),
                    self._join_csv_texts(issue.get("verification_checklist", [])),
                    self._join_csv_texts(issue.get("tuning_candidates", [])),
                ])
        self._write_rows_to_csv(output_path, headers, rows)

    def _export_dataset_topics_csv_bundle(self, output_dir, log_stem, dataset):
        topics_dir = os.path.join(output_dir, f"{log_stem}__topics")
        os.makedirs(topics_dir, exist_ok=True)
        exported_paths = []
        used_names = set()
        for idx, topic_name in enumerate(sorted((getattr(dataset, "topics", {}) or {}).keys()), start=1):
            topic = dataset.topics.get(topic_name)
            df = getattr(topic, "dataframe", None)
            if df is None:
                continue
            topic_stem = self._safe_export_stem(topic_name)
            base_name = f"{idx:03d}_{topic_stem}"
            unique_name = base_name
            suffix = 2
            while unique_name in used_names:
                unique_name = f"{base_name}_{suffix}"
                suffix += 1
            used_names.add(unique_name)
            output_path = os.path.join(topics_dir, f"{unique_name}.csv")
            if hasattr(df, "write_csv"):
                df.write_csv(output_path)
            elif hasattr(df, "to_csv"):
                df.to_csv(output_path, index=False, encoding="utf-8-sig")
            else:
                raise TypeError(f"지원하지 않는 dataframe 타입입니다: {type(df)}")
            exported_paths.append(output_path)
        return topics_dir, exported_paths

    def _find_icon_by_names(self, primary_name, fallback_names=None):
        fallback_names = fallback_names or []
        names = [primary_name] + list(fallback_names)
        for root in self._icon_search_roots():
            for name in names:
                if not name:
                    continue
                rel = name
                if os.path.isabs(rel):
                    cand = rel
                else:
                    cand = os.path.join(root, rel)
                if os.path.exists(cand):
                    return cand
        return None

    def _find_main_icon_path(self):
        override_path = self._resolve_main_icon_override_path()
        if override_path:
            return override_path
        return self._find_icon_by_names(
            DEFAULT_PROGRAM_ICON_NAMES[0],
            fallback_names=DEFAULT_PROGRAM_ICON_NAMES[1:],
        )

    def _find_ui_icon_path(self):
        override_path = self._resolve_ui_icon_override_path()
        if override_path:
            return override_path
        path = self._find_icon_by_names(
            DEFAULT_UI_ICON_NAMES[0],
            fallback_names=DEFAULT_UI_ICON_NAMES[1:],
        )
        return path

    def _get_ui_icon(self):
        # 좌상단 UI 아이콘을 캐시에서 가져오거나 새로 로드. 보통 수정 X.
        if isinstance(self._ui_icon_cache, QIcon) and not self._ui_icon_cache.isNull():
            return self._ui_icon_cache
        icon_path = self._find_ui_icon_path()
        if icon_path and os.path.exists(icon_path):
            icon = QIcon(icon_path)
            if not icon.isNull():
                self._ui_icon_cache = icon
                return icon
        return QIcon()

    @staticmethod
    def _trim_transparent_logo_pixmap(pixmap):
        if pixmap.isNull():
            return pixmap
        image = pixmap.toImage()
        if image.isNull():
            return pixmap

        min_x = image.width()
        min_y = image.height()
        max_x = -1
        max_y = -1

        for y in range(image.height()):
            for x in range(image.width()):
                if image.pixelColor(x, y).alpha() <= 0:
                    continue
                if x < min_x:
                    min_x = x
                if y < min_y:
                    min_y = y
                if x > max_x:
                    max_x = x
                if y > max_y:
                    max_y = y

        if max_x < min_x or max_y < min_y:
            return pixmap
        return pixmap.copy(min_x, min_y, (max_x - min_x) + 1, (max_y - min_y) + 1)

    def _apply_startup_splitter_ratio(self, force=False):
        if not hasattr(self, "main_splitter") or self.main_splitter.count() < 2:
            return

        if self._startup_splitter_applied and not force:
            return

        total_w = self.main_splitter.width()
        if total_w <= 1:
            total_w = self.width()
        if total_w <= 1:
            return

        left_w = max(self._startup_splitter_min_left, int(total_w * self._startup_splitter_ratio))
        right_w = max(1, total_w - left_w)

        self.main_splitter.setStretchFactor(0, 1)
        self.main_splitter.setStretchFactor(1, 6)
        self.main_splitter.setSizes([left_w, right_w])
        self._startup_splitter_applied = True

    def _update_layout_action_button_sizes(self):
        # IMPORT/EXPORT 버튼의 가로/세로 크기를 글자 폭에 맞춰 다시 계산. max(50, text_w + 8) / max(17, fm.height() + 4) 의 값을 키우면 IMPORT/EXPORT 버튼 최소 가로/세로가 커집니다.
        if not hasattr(self, "layout_btn_load") or not hasattr(self, "layout_btn_save"):
            return

        fm = self.layout_btn_load.fontMetrics()
        text_w = max(
            fm.horizontalAdvance(self.layout_btn_load.text()),
            fm.horizontalAdvance(self.layout_btn_save.text()),
        )
        if hasattr(self, "csv_export_button"):
            text_w = max(text_w, fm.horizontalAdvance(self.csv_export_button.text()))
        # Make IMPORT/EXPORT boxes clearly smaller while keeping text readable.
        btn_h = max(17, fm.height() + 4)
        btn_w = max(50, text_w + 8)
        self.layout_btn_load.setFixedSize(btn_w, btn_h)
        self.layout_btn_save.setFixedSize(btn_w, btn_h)
        if hasattr(self, "csv_export_button"):
            self.csv_export_button.setFixedSize(btn_w, btn_h)
        if hasattr(self, "layout_btn_more"):
            self.layout_btn_more.setFixedSize(22, btn_h)

