        action_actuator_vtol_fw.setToolTip("VTOL / Fixed-Wing: actuator_motors[0~4] + actuator_servos[0~4] 를 2행으로 도시 (조종면 포함)")

        flight_path_menu = tools_menu.addMenu("Flight Path")
