        gcs_submenu = com_status_menu.addMenu("GCS")
        action_gcs_panel_0 = gcs_submenu.addAction("Telemetry Status 0")
        action_gcs_panel_1 = gcs_submenu.addAction("Telemetry Status 1")

        # 좌상단 Auto Panels 메뉴. addMenu("Auto Panels"/"Multicopter"/"Fixed-Wing"/"VTOL") / addAction("표준 분석 패널 1"/"표준 분석 패널 2"/"Com Link") 의 따옴표 안 문자열을 바꾸면 메뉴/항목 이름이 바뀝니다.
        function_menu = self.top_menu_bar.addMenu("Auto Panels")
