    def _add_gnss_gps_menu(self, parent_menu):
        gnss_gps_menu = parent_menu.addMenu("GNSS/GPS")
        for section_label, section_actions in self._gnss_gps_menu_spec():
            section_menu = gnss_gps_menu.addMenu(section_label)
            for action_label, title, signal_specs in section_actions:
                action = section_menu.addAction(action_label)
                action.triggered.connect(
                    lambda checked=False, plot_title=title, specs=tuple(signal_specs): self._generate_candidate_signal_group_plot(
                        plot_title,
                        specs,
                    )
                )

    def _open_px4_flight_review(self):
        # App → PX4 Flight Review 메뉴 핸들러 — 브라우저로 https://review.px4.io/ 열기. showMessage 의 "PX4 Flight Review 페이지를 여는 데 실패했습니다." 문자열을 바꾸면 실패 안내가 바뀝니다.
        url = QUrl("https://review.px4.io/")
        opened = False
        try:
            opened = bool(QDesktopServices.openUrl(url))
        except Exception:
            opened = False
        if not opened:
            try:
                self.statusBar().showMessage("PX4 Flight Review 페이지를 여는 데 실패했습니다.", 4000)
            except Exception:
                pass

    def _open_coordinate_calc_dialog(self):
        # App → Coordinate Calc 메뉴 핸들러 — 위경도 십진수 ↔ DMS 변환 다이얼로그 (비모달).
        try:
            dlg = CoordinateCalcDialog(parent=self)
            dlg.show()
        except Exception:
            traceback.print_exc()

    def _open_kma_weather(self):
        # App → 기상확인 메뉴 핸들러 — 브라우저로 기상청 AWS 관측 페이지 열기. showMessage 의 "기상청 페이지를 여는 데 실패했습니다." 문자열을 바꾸면 실패 안내가 바뀝니다.
        url = QUrl("https://www.weather.go.kr/w/weather/land/aws-obs.do")
        opened = False
        try:
            opened = bool(QDesktopServices.openUrl(url))
        except Exception:
            opened = False
        if not opened:
            try:
                self.statusBar().showMessage("기상청 페이지를 여는 데 실패했습니다.", 4000)
            except Exception:
                pass

    def _open_cg_calc_dialog(self, mode, preset_key=None):
        """App → CG Calc → 2 Point / 3 Point 진입점.

        모달이 아닌 일반 다이얼로그로 띄워 사용자가 분석 작업과 병행
        가능하도록 한다. (2026-05-21)

        ``preset_key`` 가 지정되면 ``CGCalcDialog.PRESETS`` 의 정의를
        따라 모드/타이틀/사전 입력값이 자동 적용된다. (2026-05-24)
        """
        preset_values = None
        title_override = None
        if preset_key:
            info = CGCalcDialog.PRESETS.get(preset_key)
            if info:
                mode = info.get("mode", mode)
                preset_values = info.get("values")
                title_override = info.get("title")
        try:
            dlg = CGCalcDialog(
                mode=mode, parent=self,
                preset=preset_values, title_override=title_override,
            )
        except Exception as e:
            QMessageBox.warning(self, "CG Calc", f"CG Calc 다이얼로그를 여는 데 실패했습니다.\n{e}")
            return
        dlg.setAttribute(Qt.WA_DeleteOnClose)
        dlg.show()
        dlg.raise_()
        dlg.activateWindow()

    def _open_generic_aircraft_cg_dialog(self):
        """Open the optional generic two-point aircraft CG worksheet.

        엔진기 전용 OAL 기준 2-Point CG 측정 시트. CGCalcDialog 와는
        구조 자체가 다른 별도 다이얼로그 (GenericAircraftCGDialog).
        """
        try:
            dlg = GenericAircraftCGDialog(parent=self)
        except Exception as e:
            QMessageBox.warning(self, "CG Calc", f"Generic aircraft CG dialog failed.\n{e}")
            return
        dlg.setAttribute(Qt.WA_DeleteOnClose)
        dlg.show()
        dlg.raise_()
        dlg.activateWindow()

    def clear_data_points(self):
        # App → Clear Data Points 메뉴 핸들러 — 활성 그래프 데이터만 비움. showMessage 의 "현재 그래프의 데이터 포인트를 초기화했습니다." 문자열을 바꾸면 안내가 바뀝니다.
        current_ws = self.tab_widget.currentWidget()
        if not isinstance(current_ws, Workspace):
            return

        target_plot = None
        if self.last_active_plot and self.last_active_plot in current_ws.findChildren(AdvancedPlot):
            target_plot = self.last_active_plot
        else:
            for plot in current_ws.findChildren(AdvancedPlot):
                if plot.plotted_signals:
                    target_plot = plot
                    break
            if target_plot is None:
                target_plot = current_ws.first_plot

        if target_plot is None:
            return

        target_plot.clear_plot_data()
        self.statusBar().showMessage("현재 그래프의 데이터 포인트를 초기화했습니다.", 3000)

    def delete_everything(self):
        # App → Delete Everything 메뉴 — 로드된 모든 로그/그래프/탭을 통째로 초기화.
        answer = QMessageBox.question(
            self,
            "Delete Everything",
            "모든 그래프와 로드된 데이터를 초기화할까요?",
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if answer != QMessageBox.Yes:
            return

        load_was_active = self._log_load_thread is not None or self._log_load_active
        if load_was_active:
            # Establish the commit barrier before clearing any visible state.
            # A fileLoaded event may already be queued on the GUI thread.
            if not self.cancel_log_load():
                self._log_load_cancel_requested = True

        self.loaded_datasets.clear()
        self.loaded_aircraft_types.clear()
        self.loaded_log_metadata.clear()
        self.loaded_source_ids.clear()
        self.loaded_source_paths.clear()
        self.active_analysis_log = None
        self.custom_series_defs.clear()
        self._refresh_workspace_tab_log_colors()
        self.custom_series_data.clear()
        self.tree_model.clear()
        self.tree_view.setHeaderHidden(True)
        self.last_active_plot = None
        self._log_load_committed_count = 0
        self._log_load_rejected_count = 0
        self._log_load_apply_failures = []
        if self.log_info_dialog is not None:
            self.log_info_dialog.close()
            self.log_info_dialog.deleteLater()
            self.log_info_dialog = None

        while self.tab_widget.count() > 0:
            ws = self.tab_widget.widget(0)
            self.tab_widget.removeTab(0)
            ws.deleteLater()

        self.workspace_count = 0
        self._update_right_panel_state()
        self._refresh_custom_series_list()
        self.file_drop_widget.setText(self.file_drop_widget.idle_text())
        self.statusBar().showMessage(
            "전체 데이터가 초기화되었으며 진행 중인 로그 로딩을 취소합니다."
            if load_was_active
            else "전체 데이터가 초기화되었습니다.",
            4000,
        )

    @staticmethod
    def _metadata_value_to_text(value):
        return _metadata_value_to_text(value)

    def _extract_log_metadata(self, file_path, dataset=None, aircraft_type="Unknown"):
        return _extract_log_metadata_for_dataset(
            file_path,
            dataset=dataset,
            aircraft_type=aircraft_type,
        )

    def _ensure_log_info_dialog(self):
        # 로그 정보 비교 팝업 인스턴스가 없으면 생성. 자동 호출 — 보통 수정 X.
        # (2026-05-28 v2) parent=None — 완전 독립 윈도우로 띄움 (alt-tab/Win+분할/raise 자유).
        # WA_DeleteOnClose 가 다이얼로그 내부에 설정돼 있어 X 누르면 자동 정리되므로
        # destroyed 시그널로 self.log_info_dialog 핸들을 None 으로 reset → 다음 호출 시 새로 생성.
        if self.log_info_dialog is None:
            self.log_info_dialog = LogInfoCompareDialog(None)
            try:
                self.log_info_dialog.destroyed.connect(self._on_log_info_dialog_destroyed)
            except Exception:
                pass

    def _on_log_info_dialog_destroyed(self, _obj=None):
        # 로그 정보 비교 팝업이 close (WA_DeleteOnClose) 된 직후 호출 — 핸들 정리.
        self.log_info_dialog = None

    def _refresh_log_info_dialog(self):
        # 로그 정보 비교 팝업의 데이터(메타데이터 + active 로그) 를 갱신. 자동 호출 — 보통 수정 X.
        self._ensure_log_info_dialog()
        self.log_info_dialog.update_data(self.loaded_log_metadata, active_file=self.active_analysis_log)

    def show_log_info_dialog(self, target_file=None):
        # 로그 정보 비교 팝업을 띄우고 active 로그를 옮김. 자동 호출 — 보통 수정 X.
        if target_file and target_file in self.loaded_datasets:
            self._set_active_analysis_log(target_file, show_status=False)
        self._refresh_log_info_dialog()
        self.log_info_dialog.show()
        self.log_info_dialog.raise_()
        self.log_info_dialog.activateWindow()

    def _loaded_source_identity_set(self):
        """Return identities for loaded sources, including legacy entries."""

        identities = {value for value in self.loaded_source_ids.values() if value}
        for source_key, dataset in self.loaded_datasets.items():
            if self.loaded_source_ids.get(source_key):
                continue
            source_path = str(getattr(dataset, "source_path", "") or "")
            source_id = _canonical_source_identity(source_path)
            if source_id:
                identities.add(source_id)
        return identities

    def _allocate_loaded_source_key(self, filename, source_id):
        """Preserve the basename key unless it collides in this session."""

        filename = str(filename or "").strip()
        if filename and filename not in self.loaded_datasets:
            return filename
        return _collision_source_key(filename, source_id, self.loaded_datasets.keys())

    def _source_ui_name(self, source_key):
        """Return a readable label without exposing the internal hash key."""

        source_key = str(source_key or "")
        source_path = str(self.loaded_source_paths.get(source_key, "") or "")
        dataset = self.loaded_datasets.get(source_key)
        if not source_path and dataset is not None:
            source_path = str(getattr(dataset, "source_path", "") or "")
        basename = os.path.basename(os.path.normpath(source_path)) if source_path else ""
        basename = basename or source_key
        if source_key == basename:
            return basename
        return source_key

    def _resolve_layout_source_key(
        self,
        file_name,
        source_token="",
        source_id="",
        source_path="",
    ):
        """Resolve both legacy basename layouts and identity-aware layouts."""

        file_name = str(file_name or "")
        target_token = str(source_token or "").strip()
        if target_token:
            for source_key, loaded_id in self.loaded_source_ids.items():
                if (
                    source_key in self.loaded_datasets
                    and _source_layout_token(loaded_id) == target_token
                ):
                    return source_key
            # An identity-bearing layout is authoritative.  Falling through
            # to a coincidentally equal basename could plot the wrong flight.
            return None

        # Transitional layouts briefly stored the canonical absolute identity.
        # Read those files for compatibility, but never write this field again.
        target_id = str(source_id or "").strip()
        if not target_id and source_path:
            target_id = _canonical_source_identity(source_path)
        if target_id:
            for source_key, loaded_id in self.loaded_source_ids.items():
                if loaded_id == target_id and source_key in self.loaded_datasets:
                    return source_key
            return None
        # Layouts written before source identities existed only contain the
        # basename.  Resolve them only when that basename is unique.  Choosing
        # the historical basename-keyed source while a collision sibling is
        # loaded can silently plot the wrong flight.
        basename_matches = []
        wanted_basename = os.path.basename(os.path.normpath(file_name)) if file_name else ""
        for source_key in self.loaded_datasets:
            source_path_value = str(self.loaded_source_paths.get(source_key, "") or "")
            loaded_basename = (
                os.path.basename(os.path.normpath(source_path_value))
                if source_path_value
                else self._source_ui_name(source_key).split(" [", 1)[0]
            )
            if wanted_basename and loaded_basename == wanted_basename:
                basename_matches.append(source_key)
        if len(basename_matches) == 1:
            return basename_matches[0]
        if len(basename_matches) > 1:
            return None
        # A few old layouts used a non-basename application key.  Preserve
        # that compatibility only when the key names one exact loaded source.
        if file_name in self.loaded_datasets:
            return file_name
        return None

    def _layout_source_file_name(self, source_key):
        """Return a portable basename without exposing collision qualifiers."""

        source_key = str(source_key or "")
        source_path = str(self.loaded_source_paths.get(source_key, "") or "")
        dataset = self.loaded_datasets.get(source_key)
        if not source_path and dataset is not None:
            source_path = str(getattr(dataset, "source_path", "") or "")
        if source_path:
            basename = os.path.basename(os.path.normpath(source_path))
            if basename:
                return basename
        return source_key

    def _layout_source_reference(self, source_key):
        reference = {}
        source_id = str(self.loaded_source_ids.get(source_key, "") or "")
        if source_id:
            source_token = _source_layout_token(source_id)
            if source_token:
                reference["source_token"] = source_token
        return reference

    def _iter_tree_file_nodes(self):
        # 좌측 트리의 최상위(파일) 노드를 순회하며 반환. 보통 수정 X.
        root_item = self.tree_model.invisibleRootItem()
        for row in range(root_item.rowCount()):
            item = root_item.child(row)
            if item is not None:
                yield item

    def _update_tree_file_node_styles(self):
        # 좌측 트리의 각 파일 노드 표기 갱신 — 활성 로그 앞에 ▶ 마커를 붙임. "▶ " 접두 문자열을 바꾸면 활성 로그 표시 마커가, QColor("#1A2D57") 를 바꾸면 활성 로그 글자색이 바뀝니다.
        for file_node in self._iter_tree_file_nodes():
            file_name = file_node.data(Qt.UserRole)
            aircraft_type = file_node.data(Qt.UserRole + 1)
            is_active = (file_name == self.active_analysis_log and file_name in self.loaded_datasets)
            prefix = "▶ " if is_active else ""
            file_node.setText(f"{prefix}{self._source_ui_name(file_name)} | Type : {aircraft_type}")
            file_node.setForeground(QBrush(QColor("#1A2D57" if is_active else "#000000")))

    def _set_active_analysis_log(self, file_name, show_status=True):
        # 분석 대상이 되는 활성 로그를 file_name 으로 변경 + 트리/팝업/탭에 반영. showMessage 의 "Active Analysis Log: {file_name} | Aircraft Type: {aircraft}" 문자열을 바꾸면 상태바 안내가 바뀝니다.
        if not file_name or file_name not in self.loaded_datasets:
            return False
        self.active_analysis_log = file_name
        self._update_tree_file_node_styles()
        self._refresh_log_info_dialog()
        ws = self._current_workspace()
        if isinstance(ws, Workspace):
            ws.set_aircraft_type(self.loaded_aircraft_types.get(file_name, "Unknown"))
        # 검색어가 살아있는 상태에서 active 로그를 바꾸면 검색 결과도
        # 새 active 로그 기준으로 다시 좁혀야 한다.
        if (getattr(self, "_pending_tree_filter_text", "") or "").strip():
            self.apply_tree_search()
        if show_status:
            aircraft = self.loaded_aircraft_types.get(file_name, "Unknown")
            self.statusBar().showMessage(
                f"Active Analysis Log: {self._source_ui_name(file_name)} | Aircraft Type: {aircraft}",
                5000,
            )
        return True

    def _remove_tree_file_node(self, file_name):
        # 좌측 트리에서 해당 파일 노드를 제거. 자동 호출 — 보통 수정 X.
        root_item = self.tree_model.invisibleRootItem()
        removed = False
        for row in range(root_item.rowCount() - 1, -1, -1):
            item = root_item.child(row)
            if item is not None and item.data(Qt.UserRole) == file_name:
                root_item.removeRow(row)
                removed = True
        return removed

    def _remove_log_references_from_plots(self, file_name):
        # 모든 분석창의 모든 그래프에서 file_name 으로 그려진 신호를 제거. 자동 호출 — 보통 수정 X.
        removed_signals = 0
        file_prefix = f"{file_name}|"
        for tab_idx in range(self.tab_widget.count()):
            ws = self.tab_widget.widget(tab_idx)
            if not isinstance(ws, Workspace):
                continue
            for plot in ws.findChildren(AdvancedPlot):
                special = getattr(plot, "layout_special_spec", None)
                special_file = str(special.get("file_name", "")) if isinstance(special, dict) else ""
                uris = list(plot.plotted_signals.keys())
                keep_uris = [uri for uri in uris if not uri.startswith(file_prefix)]
                removed_here = len(uris) - len(keep_uris)

                if special_file == file_name:
                    plot.clear_plot_data()
                    removed_signals += max(1, removed_here)
                    continue
                if removed_here <= 0:
                    continue

                title_text = ""
                try:
                    plot_item = plot.plot.getPlotItem()
                    title_text = re.sub("<[^>]+>", "", plot_item.titleLabel.text or "").strip()
                except Exception:
                    title_text = ""

                plot.clear_plot_data()
                for uri in keep_uris:
                    parsed = self._parse_render_uri(uri)
                    if parsed is None:
                        continue
                    f_name, topic_name, signal_name, x_axis_col, is_fft = parsed
                    try:
                        plot.render_signal(f_name, topic_name, signal_name, x_axis_col, is_fft=is_fft)
                    except Exception:
                        continue
                if title_text and (plot.plotted_signals or getattr(plot, "layout_special_spec", None)):
                    plot.plot.setTitle(title_text)
                removed_signals += removed_here
            # ``expand_time_range`` only grows.  After all affected plots in
            # this workspace have been rebuilt, shrink the authoritative
            # domain to the curves that actually remain.
            ws.recompute_time_range_from_plots()
        return removed_signals

    def delete_loaded_log(self, file_name, ask_confirm=True):
        # 단일 로드된 로그를 모든 그래프/캐시에서 제거. QMessageBox 의 "로그 삭제" / "선택한 로그를 삭제할까요?\n\n{file_name}" / showMessage 의 "로그 삭제 완료: {}" 문자열을 바꾸면 안내가 바뀝니다.
        if not file_name or file_name not in self.loaded_datasets:
            return False

        if ask_confirm:
            answer = QMessageBox.question(
                self,
                "로그 삭제",
                f"선택한 로그를 삭제할까요?\n\n{file_name}",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if answer != QMessageBox.Yes:
                return False

        removed_series = len(self.custom_series_defs.get(file_name, {}))
        self.custom_series_defs.pop(file_name, None)
        self.custom_series_data.pop(file_name, None)

        self.loaded_datasets.pop(file_name, None)
        self.loaded_aircraft_types.pop(file_name, None)
        self.loaded_log_metadata.pop(file_name, None)
        self.loaded_source_ids.pop(file_name, None)
        self.loaded_source_paths.pop(file_name, None)
        self._same_log_view_state.pop(file_name, None)
        self._remove_tree_file_node(file_name)
        # 남은 로그 인덱스가 시프트될 수 있어 코너 마커 색을 다시 칠함.
        self._refresh_workspace_tab_log_colors()
        removed_plot_signals = self._remove_log_references_from_plots(file_name)
        self.last_active_plot = None

        if self.active_analysis_log == file_name:
            if self.loaded_datasets:
                next_file = next(iter(self.loaded_datasets.keys()))
                self._set_active_analysis_log(next_file, show_status=False)
            else:
                self.active_analysis_log = None
                self._update_tree_file_node_styles()
                if self.log_info_dialog is not None:
                    self.log_info_dialog.update_data({}, active_file=None)
                for tab_idx in range(self.tab_widget.count()):
                    ws = self.tab_widget.widget(tab_idx)
                    if isinstance(ws, Workspace):
                        ws.set_aircraft_type("-")
        else:
            self._update_tree_file_node_styles()
            if self.log_info_dialog is not None:
                self._refresh_log_info_dialog()

        self._refresh_custom_series_list()
        if self.loaded_datasets:
            self.file_drop_widget.setText(f"Total {len(self.loaded_datasets)} Log Load complete!\n(You can upload more logs)")
        else:
            self.file_drop_widget.setText(self.file_drop_widget.idle_text())

        self.statusBar().showMessage(
            f"로그 삭제 완료: {file_name} (그래프 신호 {removed_plot_signals}개, Custom Series {removed_series}개 정리)",
            5000,
        )
        return True

    def _on_tree_file_reorder_requested(self, source_file, target_file, insert_below):
        """Handle a file-node drag-and-drop within the log tree by moving
        the QStandardItem row in-place and rebuilding `loaded_datasets` /
        `loaded_log_metadata` / `loaded_aircraft_types` so the new order
        is reflected everywhere that iterates those dicts. 2026-05-15."""
        if not source_file or not target_file or source_file == target_file:
            return
        root = self.tree_model.invisibleRootItem()
        source_row = -1
        target_row = -1
        for row in range(root.rowCount()):
            item = root.child(row)
            if item is None:
                continue
            file_name = item.data(Qt.UserRole)
            if file_name == source_file:
                source_row = row
            if file_name == target_file:
                target_row = row
        if source_row < 0 or target_row < 0:
            return
        taken = root.takeRow(source_row)
        if not taken:
            return
        # After taking out source, indices above shift by -1.
        if source_row < target_row:
            target_row -= 1
        insert_idx = target_row + 1 if insert_below else target_row
        insert_idx = max(0, min(root.rowCount(), insert_idx))
        root.insertRow(insert_idx, taken)
        # Re-sync our backing dicts to the new tree row order so any
        # consumer iterating `loaded_datasets.keys()` (Custom Series list,
        # workspace lookups, exports, etc.) sees the user-chosen order.
        new_order = []
        for row in range(root.rowCount()):
            item = root.child(row)
            if item is None:
                continue
            file_name = item.data(Qt.UserRole)
            if file_name and file_name in self.loaded_datasets:
                new_order.append(file_name)
        if new_order:
            for attr in (
                "loaded_datasets",
                "loaded_log_metadata",
                "loaded_aircraft_types",
                "loaded_source_ids",
                "loaded_source_paths",
            ):
                src = getattr(self, attr, None)
                if not isinstance(src, dict):
                    continue
                reordered = {f: src[f] for f in new_order if f in src}
                # Preserve any keys not present in the tree (shouldn't
                # happen, but be defensive).
                for k, v in src.items():
                    if k not in reordered:
                        reordered[k] = v
                src.clear()
                src.update(reordered)
        self._update_tree_file_node_styles()
        try:
            self._refresh_log_info_dialog()
        except Exception:
            pass
        try:
            self._refresh_custom_series_list()
        except Exception:
            pass

    def _on_tree_item_double_clicked(self, index):
        # 좌측 트리의 항목을 더블클릭하면 그 로그를 active 로그로 전환. 자동 호출 — 보통 수정 X.
        """Switch the active analysis log when the user double-clicks any
        item in the log tree. Walks up to the top-level file node so that
        double-clicking on a sub-topic or a leaf signal under the file also
        counts. Idempotent — clicking the already-active file is a no-op
        (avoids re-firing the active-log update / status message)."""
        if index is None or not index.isValid():
            return
        item = self.tree_model.itemFromIndex(index)
        if item is None:
            return
        file_item = item
        while file_item.parent() is not None:
            file_item = file_item.parent()
        file_name = file_item.data(Qt.UserRole)
        if not file_name or file_name not in self.loaded_datasets:
            return
        if file_name == self.active_analysis_log:
            return
        self._set_active_analysis_log(file_name, show_status=True)

    def _show_tree_context_menu(self, pos):
        # 좌측 트리 우클릭 메뉴. addAction("해당 로그로 분석 설정하기") / "로그 정보 비교 창 열기" / "해당 로그 삭제하기" 의 따옴표 안 문자열을 바꾸면 메뉴 항목 이름이 바뀝니다.
        idx = self.tree_view.indexAt(pos)
        if not idx.isValid():
            return
        item = self.tree_model.itemFromIndex(idx)
        if item is None:
            return
        file_item = item
        while file_item.parent() is not None:
            file_item = file_item.parent()
        file_name = file_item.data(Qt.UserRole)
        if not file_name or file_name not in self.loaded_datasets:
            return

        menu = QMenu(self)
        act_set_active = menu.addAction("해당 로그로 분석 설정하기")
        act_show_info = menu.addAction("로그 정보 비교 창 열기")
        menu.addSeparator()
        act_delete_log = menu.addAction("해당 로그 삭제하기")
        selected = menu.exec(self.tree_view.viewport().mapToGlobal(pos))
        if selected == act_set_active:
            self._set_active_analysis_log(file_name, show_status=True)
        elif selected == act_show_info:
            self.show_log_info_dialog(target_file=file_name)
        elif selected == act_delete_log:
            self.delete_loaded_log(file_name, ask_confirm=True)

    @staticmethod
    def _parse_render_uri(uri_text):
        parts = [p.strip() for p in str(uri_text or "").split("|")]
        if len(parts) < 3:
            return None
        file_name = parts[0]
        topic_name = parts[1]
        signal_name = parts[2]
        x_axis_col = parts[3] if len(parts) >= 4 and parts[3] else "timestamp_sec"
        is_fft = False
        if len(parts) >= 5:
            is_fft = parts[4].lower() == "true"
        return file_name, topic_name, signal_name, x_axis_col, is_fft

    def _collect_workspace_export_targets(self, workspace):
        targets = []
        seen = set()
        for plot in workspace.findChildren(AdvancedPlot):
            for uri in plot.plotted_signals.keys():
                parsed = self._parse_render_uri(uri)
                if parsed is None:
                    continue
                file_name, topic_name, signal_name, x_axis_col, is_fft = parsed
                if is_fft:
                    continue
                if x_axis_col != "timestamp_sec":
                    continue
                key = (file_name, topic_name, signal_name, x_axis_col)
                if key in seen:
                    continue
                seen.add(key)
                targets.append(key)
        return targets

    @staticmethod
    def _estimate_signal_hz(timestamps):
        arr = np.asarray(timestamps, dtype=np.float64)
        if arr.size < 2:
            return None
        dt = np.diff(arr)
        dt = dt[np.isfinite(dt) & (dt > 1e-9)]
        if dt.size == 0:
            return None
        median_dt = float(np.median(dt))
        if not np.isfinite(median_dt) or median_dt <= 0.0:
            return None
        return float(1.0 / median_dt)

    @staticmethod
    def _format_hz_label(hz_value):
        if hz_value is None:
            return "NA"
        try:
            hz = float(hz_value)
        except Exception:
            return "NA"
        if not np.isfinite(hz) or hz <= 0:
            return "NA"
        return f"{hz:.2f}Hz"

    @staticmethod
    def _duration_hz_fallback(timestamps):
        arr = np.asarray(timestamps, dtype=np.float64)
        if arr.size < 2:
            return 0.0
        t_min = float(np.min(arr))
        t_max = float(np.max(arr))
        duration = t_max - t_min
        if not np.isfinite(duration) or duration <= 1e-9:
            return 0.0
        return float((arr.size - 1) / duration)

    @staticmethod
    def _build_export_column_name(file_name, topic_name, signal_name, hz_text, used_columns):
        candidates = [
            f"{signal_name} [{hz_text}]",
            f"{topic_name}.{signal_name} [{hz_text}]",
            f"{file_name}.{topic_name}.{signal_name} [{hz_text}]",
        ]
        for cand in candidates:
            if cand not in used_columns:
                return cand
        idx = 2
        while True:
            fallback = f"{file_name}.{topic_name}.{signal_name} [{hz_text}] ({idx})"
            if fallback not in used_columns:
                return fallback
            idx += 1

    def export_current_workspace_csv(self):
        # 좌측 EXPORT 버튼 — 현재 활성 분석창의 모든 시계열 신호를 CSV 로 저장. QMessageBox 의 "현재 활성화된 Tab이 없습니다. 먼저 로그를 업로드해 주세요." / "현재 Tab에 CSV로 내보낼 시계열 신호가 없습니다." 등 문자열을 바꾸면 안내가 바뀝니다.
        current_ws = self.tab_widget.currentWidget()
        if not isinstance(current_ws, Workspace):
            QMessageBox.information(self, "CSV Export", "현재 활성화된 Tab이 없습니다. 먼저 로그를 업로드해 주세요.")
            return

        export_targets = self._collect_workspace_export_targets(current_ws)
        print(f"[CSV] export targets: {len(export_targets)}")

        if not export_targets:
            QMessageBox.information(
                self,
                "CSV Export",
                "현재 Tab에 CSV로 내보낼 시계열 신호가 없습니다.\n"
                "- 시간축(timestamp_sec) 기반 신호를 그래프에 올린 뒤 다시 시도해 주세요.",
            )
            return

        signal_infos = []
        used_columns = set()
        for file_name, topic_name, signal_name, x_axis_col in export_targets:
            uri_text = f"{file_name}|{topic_name}|{signal_name}|{x_axis_col}"
            try:
                xy = self._get_series_xy_from_uri(uri_text, require_time=True)
            except Exception:
                xy = None
            if xy is None:
                continue
            x, y = xy
            if len(x) == 0 or len(y) == 0:
                continue

            signal_df = pl.DataFrame(
                {
                    "timestamp_sec": np.asarray(x, dtype=np.float64),
                    "value": np.asarray(y, dtype=np.float64),
                }
            )
            signal_df = (
                signal_df
                .drop_nulls(subset=["timestamp_sec"])
                .unique(subset=["timestamp_sec"], keep="first")
                .sort("timestamp_sec")
            )
            if signal_df.height == 0:
                continue

            ts = signal_df["timestamp_sec"].to_numpy()
            hz = self._estimate_signal_hz(ts)
            if hz is None:
                hz = self._duration_hz_fallback(ts)
            hz_text = self._format_hz_label(hz)

            col_name = self._build_export_column_name(file_name, topic_name, signal_name, hz_text, used_columns)
            used_columns.add(col_name)
            signal_df = signal_df.rename({"value": col_name})

            signal_infos.append(
                {
                    "file_name": file_name,
                    "topic_name": topic_name,
                    "signal_name": signal_name,
                    "col_name": col_name,
                    "hz": hz,
                    "hz_text": hz_text,
                    "t_min": float(signal_df["timestamp_sec"].min()),
                    "t_max": float(signal_df["timestamp_sec"].max()),
                    "df": signal_df,
                    "sample_count": int(signal_df.height),
                }
            )

        if not signal_infos:
            QMessageBox.warning(self, "CSV Export", "내보낼 데이터프레임을 생성하지 못했습니다.")
            return

        base_info = max(
            signal_infos,
            key=lambda s: (
                float(s["hz"]) if s["hz"] is not None else 0.0,
                s["sample_count"],
            ),
        )

        # Use the highest-rate signal as the common timeline, then align others
        # using backward asof-join (zero-order hold / forward-fill semantics).
        export_df = base_info["df"].select("timestamp_sec")
        for info in signal_infos:
            col_name = info["col_name"]
            source_df = info["df"]
            export_df = export_df.join_asof(source_df, on="timestamp_sec", strategy="backward")
            t_max = float(info["t_max"])
            export_df = export_df.with_columns(
                pl.when(pl.col("timestamp_sec") > pl.lit(t_max))
                .then(pl.lit(None, dtype=pl.Float64))
                .otherwise(pl.col(col_name))
                .alias(col_name)
            )

        current_idx = self.tab_widget.currentIndex()
        current_tab_text = self.tab_widget.tabText(current_idx) if current_idx >= 0 else ""
        default_stem = current_tab_text.split("|")[0].replace("분석:", "").strip().replace(" ", "_")
        if not default_stem:
            default_stem = "workspace_signals"
        default_name = f"{default_stem}.csv"
        output_path, _ = QFileDialog.getSaveFileName(self, "CSV 저장", default_name, "CSV Files (*.csv)")
        if not output_path:
            self.statusBar().showMessage("CSV 저장이 취소되었습니다.", 2500)
            return

        export_df.write_csv(output_path)
        signal_count = len(export_df.columns) - 1
        base_desc = f"{base_info['signal_name']} ({base_info['hz_text']})"
        self.statusBar().showMessage(
            f"CSV 저장 완료: {os.path.basename(output_path)} ({signal_count}개 신호, 기준축: {base_desc})",
            5000,
        )
        hz_preview_lines = []
        for info in signal_infos[:8]:
            hz_preview_lines.append(f"- {info['topic_name']}.{info['signal_name']}: {info['hz_text']}")
        if len(signal_infos) > 8:
            hz_preview_lines.append(f"- ... 외 {len(signal_infos) - 8}개")
        QMessageBox.information(
            self,
            "CSV Export",
            (
                "CSV 저장 완료\n"
                f"경로: {output_path}\n"
                f"신호 수: {signal_count}\n"
                f"기준 시간축: {base_desc}\n\n"
                "신호별 추정 샘플링 주기:\n"
                + "\n".join(hz_preview_lines)
            ),
        )

    def _get_current_workspace_and_plot(self):
        # 현재 활성 분석창과 그 안의 활성 그래프 한 쌍을 찾아 반환. 보통 수정 X.
        current_ws = self.tab_widget.currentWidget()
        if not isinstance(current_ws, Workspace):
            return None, None

        target_plot = None
        try:
            current_plots = current_ws._iter_workspace_plots()
        except Exception:
            current_plots = current_ws.findChildren(AdvancedPlot)
        if self.last_active_plot and self.last_active_plot in current_plots:
            target_plot = self.last_active_plot
        if target_plot is None:
            for plot in current_plots:
                if plot.plotted_signals:
                    target_plot = plot
                    break
        if target_plot is None:
            target_plot = current_ws.first_plot
        return current_ws, target_plot

    def _resolve_active_plot_for_plot_clipboard(self, require_empty=False):
        current_ws = self._active_workspace()
        if current_ws is None:
            return None
        plots = current_ws._iter_workspace_plots() if hasattr(current_ws, "_iter_workspace_plots") else current_ws.findChildren(AdvancedPlot)
        if self.last_active_plot in plots:
            candidate = self.last_active_plot
            if require_empty:
                return candidate if self._plot_is_empty_for_paste(candidate) else None
            return candidate
        if require_empty:
            for plot in plots:
                if self._plot_is_empty_for_paste(plot):
                    return plot
            return None
        for plot in plots:
            if self._plot_has_content_for_copy(plot):
                return plot
        return current_ws.first_plot

    def _copy_active_plot_via_shortcut(self):
        # Ctrl+C 단축키 핸들러 — 활성 그래프를 내부 클립보드에 복사. showMessage 의 "복사할 그래프를 먼저 선택해 주세요. (Ctrl+C)" 문자열을 바꾸면 안내가 바뀝니다.
        target_plot = self._resolve_active_plot_for_plot_clipboard(require_empty=False)
        if target_plot is None or not self._plot_has_content_for_copy(target_plot):
            self.statusBar().showMessage("복사할 그래프를 먼저 선택해 주세요. (Ctrl+C)", 3000)
            return
        self.copy_plot_to_internal_clipboard(target_plot)

    def _paste_active_plot_via_shortcut(self):
        # Ctrl+V 단축키 핸들러 — 복사된 그래프를 활성 그래프에 붙여넣기. showMessage 의 "붙여넣기할 복사 그래프가 없습니다..." / "붙여넣기 대상 그래프를 먼저 선택해 주세요. (Ctrl+V)" 문자열을 바꾸면 안내가 바뀝니다.
        # (2026-05-31) require_empty=False — 빈 그래프든 콘텐츠가 있는 그래프든 둘 다 paste 대상으로 허용.
        # 후자는 paste_plot_from_internal_clipboard 가 overlay 모드로 처리.
        if not self._has_copied_plot_payload():
            self.statusBar().showMessage("붙여넣기할 복사 그래프가 없습니다. 먼저 Ctrl+C를 사용하세요.", 3000)
            return
        target_plot = self._resolve_active_plot_for_plot_clipboard(require_empty=False)
        if target_plot is None:
            self.statusBar().showMessage("붙여넣기 대상 그래프를 먼저 선택해 주세요. (Ctrl+V)", 3000)
            return
        self.paste_plot_from_internal_clipboard(target_plot)

    def _get_dataset_for_tools(self, preferred_plot=None):
        if self.active_analysis_log and self.active_analysis_log in self.loaded_datasets:
            file_name = self.active_analysis_log
            return file_name, self.loaded_datasets[file_name], self.loaded_aircraft_types.get(file_name, "Unknown")

        if preferred_plot and preferred_plot.plotted_signals:
            try:
                first_uri = next(iter(preferred_plot.plotted_signals.keys()))
                file_name = first_uri.split("|")[0]
                if file_name in self.loaded_datasets:
                    return file_name, self.loaded_datasets[file_name], self.loaded_aircraft_types.get(file_name, "Unknown")
            except Exception:
                pass

        current_idx = self.tab_widget.currentIndex()
        tab_text = self.tab_widget.tabText(current_idx) if current_idx >= 0 else ""
        if tab_text.startswith("분석:"):
            file_name = tab_text.split("|")[0].replace("분석:", "").strip()
            if file_name in self.loaded_datasets:
                return file_name, self.loaded_datasets[file_name], self.loaded_aircraft_types.get(file_name, "Unknown")

        if self.loaded_datasets:
            file_name = next(iter(self.loaded_datasets.keys()))
            return file_name, self.loaded_datasets[file_name], self.loaded_aircraft_types.get(file_name, "Unknown")
        return None, None, None

    @staticmethod
    def _find_topic_by_prefixes(dataset, prefixes):
        if isinstance(prefixes, str):
            prefixes = [prefixes]
        for prefix in prefixes:
            if prefix in dataset.topics:
                return prefix
        # Iterate prefixes in priority order (outer) so a more-specific prefix
        # (e.g. "airspeed_validated") always wins over a less-specific one
        # ("airspeed") regardless of topic insertion order in the dataset.
        for prefix in prefixes:
            for topic_name in dataset.topics.keys():
                if topic_name.startswith(prefix):
                    return topic_name
        return None

    @staticmethod
    def _find_signal_in_topic(dataset, topic_name, candidates):
        if not topic_name or topic_name not in dataset.topics:
            return None
        cols = dataset.topics[topic_name].dataframe.columns
        for cand in candidates:
            if cand in cols:
                return cand
        return None

    def _failsafe_active_causes(self, file_name, t):
        """Return a list of active failsafe cause labels at cursor time `t`.

        Walks `_FAILSAFE_CAUSE_TABLE` and, for each (label, topic, signal),
        finds the value at the latest timestamp ≤ t. A bool field is
        considered "active" when the rounded value > 0; `battery_warning`
        is decoded by level via `_BATTERY_WARNING_LEVEL_LABEL`.

        Used by the cursor overlay to enrich the failsafe label as
        "1 (RC Lost, Battery Critical)". Returns an empty list when the
        log lacks the relevant flags or the dataset is missing.
        Added 2026-05-15.
        """
        dataset = self.loaded_datasets.get(file_name) if file_name else None
        if dataset is None:
            return []
        try:
            t = float(t)
        except Exception:
            return []
        if not np.isfinite(t):
            return []
        causes = []
        seen = set()
        for label, topic_prefix, signal_name in self._FAILSAFE_CAUSE_TABLE:
            if label in seen:
                continue
            topic = self._find_topic_by_prefixes(dataset, topic_prefix)
            if not topic or topic not in dataset.topics:
                continue
            df = dataset.topics[topic].dataframe
            if df is None or "timestamp_sec" not in df.columns or signal_name not in df.columns:
                continue
            try:
                ts = np.asarray(df["timestamp_sec"].to_numpy(), dtype=np.float64)
                vals = np.asarray(df[signal_name].to_numpy(), dtype=np.float64)
            except Exception:
                continue
            if ts.size == 0 or vals.size == 0:
                continue
            idx = int(np.searchsorted(ts, t, side="right") - 1)
            if idx < 0 or idx >= vals.size:
                continue
            v = float(vals[idx])
            if not np.isfinite(v):
                continue
            if int(round(v)) > 0:
                causes.append(label)
                seen.add(label)
        # battery_warning is a uint8 level field, not a plain bool, so it
        # gets a separate decode pass with per-level labels.
        try:
            topic = self._find_topic_by_prefixes(dataset, "failsafe_flags")
            if topic and topic in dataset.topics:
                df = dataset.topics[topic].dataframe
                if (
                    df is not None
                    and "timestamp_sec" in df.columns
                    and "battery_warning" in df.columns
                ):
                    ts = np.asarray(df["timestamp_sec"].to_numpy(), dtype=np.float64)
                    vals = np.asarray(df["battery_warning"].to_numpy(), dtype=np.float64)
                    if ts.size and vals.size:
                        idx = int(np.searchsorted(ts, t, side="right") - 1)
                        if 0 <= idx < vals.size and np.isfinite(vals[idx]):
                            level = int(round(float(vals[idx])))
                            level_label = self._BATTERY_WARNING_LEVEL_LABEL.get(level)
                            if level_label:
                                causes.append(level_label)
        except Exception:
            pass
        return causes

    def _prepare_tools_plot(self, title):
        # Analysis 메뉴 진입 시 새 그래프를 분할로 만들고 제목을 지정. 자동 호출 — 보통 수정 X.
        current_ws, target_plot = self._get_current_workspace_and_plot()
        if current_ws is None or target_plot is None:
            self.add_workspace()
            current_ws, target_plot = self._get_current_workspace_and_plot()
            if current_ws is None or target_plot is None:
                return None, None

        if target_plot.plotted_signals:
            new_plot = target_plot.split_layout(Qt.Vertical)
            if new_plot is not None:
                target_plot = new_plot
            else:
                target_plot.clear_plot_data()
        else:
            target_plot.clear_plot_data()

        target_plot.plot.setTitle(title)
        self.last_active_plot = target_plot
        return current_ws, target_plot

    @staticmethod
    def _axis_name(axis):
        return axis.capitalize()

    def _render_pair(
        self,
        plot,
        file_name,
        sp_topic,
        sp_signal,
        act_topic,
        act_signal,
        title,
        show_message=True,
    ):
        # 두 신호(setpoint vs actual) 를 한 그래프에 빨강/파랑으로 그림. color="#FF0000"/"#0000FF" 의 hex 값을 바꾸면 두 곡선 색이 바뀌고, QMessageBox 의 "필요한 신호를 찾지 못했습니다: {title}" 문자열을 바꾸면 안내 팝업 문구가 바뀝니다.
        if not sp_topic or not sp_signal or not act_topic or not act_signal:
            if show_message:
                QMessageBox.warning(self, "Analysis", f"필요한 신호를 찾지 못했습니다: {title}")
            return False
        plot.clear_plot_data()
        plot.plot.setTitle(title)
        ok1 = plot.render_signal(
            file_name,
            sp_topic,
            sp_signal,
            color="#FF0000",
        )
        ok2 = plot.render_signal(
            file_name,
            act_topic,
            act_signal,
            color="#0000FF",
        )
        if not (ok1 or ok2):
            if show_message:
                QMessageBox.warning(self, "Analysis", f"그래프 생성에 실패했습니다: {title}")
            return False
        plot.auto_fit_view()
        self._reset_tools_workspace_to_full_range(plot)
        return True

    def _render_signals(
        self,
        plot,
        file_name,
        items,
        title,
        show_message=True,
    ):
        # 여러 신호를 한 그래프에 색을 지정해 그림. QMessageBox 의 "필요한 신호를 찾지 못했습니다: {title}" / "그래프 생성에 실패했습니다: {title}" 문자열을 바꾸면 안내 팝업 문구가 바뀝니다.
        valid_items = [(t, s, c) for (t, s, c) in items if t and s]
        if not valid_items:
            if show_message:
                QMessageBox.warning(self, "Analysis", f"필요한 신호를 찾지 못했습니다: {title}")
            return False
        plot.clear_plot_data()
        plot.plot.setTitle(title)
        any_ok = False
        for (topic, signal, color) in valid_items:
            ok = plot.render_signal(
                file_name,
                topic,
                signal,
                color=color,
            )
            any_ok = any_ok or ok
        if not any_ok:
            if show_message:
                QMessageBox.warning(self, "Analysis", f"그래프 생성에 실패했습니다: {title}")
            return False
        plot.auto_fit_view()
        self._reset_tools_workspace_to_full_range(plot)
        return True

    def _generate_candidate_signal_group_plot(self, title, signal_specs):
        _, target_plot = self._prepare_tools_plot(title)
        if target_plot is None:
            return
        file_name, dataset, _ = self._get_dataset_for_tools(target_plot)
        if dataset is None:
            QMessageBox.information(self, "Analysis", "먼저 로그를 로드해 주세요.")
            return

        items = []
        for topic_prefixes, signal_candidates, color in signal_specs:
            if isinstance(signal_candidates, str):
                signal_candidates = [signal_candidates]
            topic = self._find_topic_by_prefixes(dataset, topic_prefixes)
            signal = self._find_signal_in_topic(dataset, topic, signal_candidates)
            items.append((topic, signal, color))
        self._render_signals(target_plot, file_name, items, title)

    def _reset_tools_workspace_to_full_range(self, plot):
        # Analysis 메뉴로 그린 그래프 직후 분석창 X 범위를 로그 전체 범위로 복원. 자동 호출 — 보통 수정 X.
        """Force the host workspace's X range to the full log span
        (global_min_x..global_max_x).

        Mirrors the post-build `reset_zoom` step used by Auto Panels so
        Analysis-menu graphs default to the full time view rather than
        inheriting any narrow zoom that was active on the workspace.
        """
        try:
            workspace = getattr(plot, "workspace", None)
            if not isinstance(workspace, Workspace):
                return
            if (
                workspace.global_min_x is None
                or workspace.global_max_x is None
            ):
                return
            try:
                min_x = float(workspace.global_min_x)
                max_x = float(workspace.global_max_x)
            except Exception:
                return
            if not (np.isfinite(min_x) and np.isfinite(max_x)) or max_x <= min_x:
                return
            workspace._set_xrange_debug_action("reset_zoom")
            workspace._set_perf_debug_action(
                "reset_zoom", started_at=time.perf_counter()
            )
            workspace.set_time_range(min_x, max_x, clamp_to_global=False)
        except Exception:
            pass

    def generate_angle_plot(self, axis):
        # Analysis → Angle (Pitch/Roll/Yaw) 메뉴 핸들러 — Setpoint vs Actual 그래프 생성. setTitle f"{axis} Angle (Actual) vs {axis} Angle Setpoint" 의 영어 문장을 바꾸면 그래프 제목이 바뀝니다.
        _, target_plot = self._prepare_tools_plot(f"{self._axis_name(axis)} Angle (Actual) vs {self._axis_name(axis)} Angle Setpoint")
        if target_plot is None:
            return
        file_name, dataset, aircraft_type = self._get_dataset_for_tools(target_plot)
        if dataset is None:
            QMessageBox.information(self, "Analysis", "먼저 로그를 로드해 주세요.")
            return

        sp_topic = self._find_topic_by_prefixes(dataset, "vehicle_attitude_setpoint")
        act_topic = self._find_topic_by_prefixes(dataset, "vehicle_attitude")
        sp_candidates = {
            "pitch": ["pitch_sp_euler", "pitch", "pitch_body"],
            "roll": ["roll_sp_euler", "roll", "roll_body"],
            "yaw": ["yaw_sp_euler", "yaw", "yaw_body"],
        }
        act_candidates = {
            "pitch": ["pitch_euler", "pitch"],
            "roll": ["roll_euler", "roll"],
            "yaw": ["yaw_euler", "yaw"],
        }
        sp_signal = self._find_signal_in_topic(dataset, sp_topic, sp_candidates.get(axis, []))
        act_signal = self._find_signal_in_topic(dataset, act_topic, act_candidates.get(axis, []))
        rendered = self._render_pair(
            target_plot,
            file_name,
            sp_topic,
            sp_signal,
            act_topic,
            act_signal,
            f"{self._axis_name(axis)} Angle (Actual) vs {self._axis_name(axis)} Angle Setpoint",
        )
        if rendered and self._normalize_aircraft_label(aircraft_type) == "vtol":
            self._add_transition_mode_overlay_to_plot(target_plot, dataset, color="#FF8800")

    def generate_angular_rate_plot(self, axis):
        # Analysis → Angular (Pitch/Roll/Yaw) 메뉴 핸들러 — Setpoint vs Actual 각속도 그래프. setTitle 의 영어 문장을 바꾸면 그래프 제목이 바뀝니다.
        _, target_plot = self._prepare_tools_plot(f"{self._axis_name(axis)} Angular Rate (Actual) vs {self._axis_name(axis)} Angular Rate Setpoint")
        if target_plot is None:
            return
        file_name, dataset, aircraft_type = self._get_dataset_for_tools(target_plot)
        if dataset is None:
            QMessageBox.information(self, "Analysis", "먼저 로그를 로드해 주세요.")
            return

        sp_topic = self._find_topic_by_prefixes(dataset, "vehicle_rates_setpoint")
        act_topic = self._find_topic_by_prefixes(dataset, "vehicle_angular_velocity")
        idx_map = {"roll": 0, "pitch": 1, "yaw": 2}
        idx = idx_map.get(axis, 0)
        sp_signal = self._find_signal_in_topic(dataset, sp_topic, [axis, f"xyz[{idx}]"])
        act_signal = self._find_signal_in_topic(dataset, act_topic, [f"xyz[{idx}]", axis])
        rendered = self._render_pair(
            target_plot,
            file_name,
            sp_topic,
            sp_signal,
            act_topic,
            act_signal,
            f"{self._axis_name(axis)} Angular Rate (Actual) vs {self._axis_name(axis)} Angular Rate Setpoint",
        )
        if rendered and self._normalize_aircraft_label(aircraft_type) == "vtol":
            self._add_transition_mode_overlay_to_plot(target_plot, dataset, color="#FF8800")

    def generate_speed_plot(self):
        # Analysis → Airspeed vs Ground Speed 메뉴 핸들러. setTitle("Airspeed vs GPS Ground Speed") 의 문자열을 바꾸면 그래프 제목이 바뀝니다.
        _, target_plot = self._prepare_tools_plot("Airspeed vs GPS Ground Speed")
        if target_plot is None:
            return
        file_name, dataset, _ = self._get_dataset_for_tools(target_plot)
        if dataset is None:
            QMessageBox.information(self, "Analysis", "먼저 로그를 로드해 주세요.")
            return

        ground_topic = self._find_topic_by_prefixes(dataset, ["vehicle_gps_position", "vehicle_local_position"])
        ground_signal = self._find_signal_in_topic(dataset, ground_topic, ["vel_m_s", "ground_speed_mag", "vx"])

        # Use validated true airspeed (`airspeed_validated.true_airspeed_m_s`) as the
        # primary source. Fall back to TECS-filtered estimate or raw airspeed only when
        # the validated topic is unavailable (e.g. older PX4 log without airspeed_validated).
        air_topic = self._find_topic_by_prefixes(dataset, ["airspeed_validated", "tecs_status", "airspeed"])
        air_signal = self._find_signal_in_topic(
            dataset,
            air_topic,
            ["true_airspeed_m_s", "true_airspeed_filtered", "indicated_airspeed_m_s"],
        )

        self._render_pair(
            target_plot,
            file_name,
            air_topic,
            air_signal,
            ground_topic,
            ground_signal,
            "Airspeed vs GPS Ground Speed",
        )

