    def generate_altitude_tracking_plot(self):
        # Analysis → Altitude Tracking 메뉴 핸들러. setTitle("Altitude vs Altitude Setpoint") 의 문자열을 바꾸면 그래프 제목이 바뀝니다.
        _, target_plot = self._prepare_tools_plot("Altitude vs Altitude Setpoint")
        if target_plot is None:
            return
        file_name, dataset, _ = self._get_dataset_for_tools(target_plot)
        if dataset is None:
            QMessageBox.information(self, "Analysis", "먼저 로그를 로드해 주세요.")
            return

        sp_topic = self._find_topic_by_prefixes(dataset, "vehicle_local_position_setpoint")
        act_topic = self._find_topic_by_prefixes(dataset, "vehicle_local_position")
        # Prefer the math_engine-generated up-positive virtual signals so the
        # plot reads as "altitude up = positive". Fall back to NED z only when
        # the virtual signal is unavailable.
        sp_signal = self._find_signal_in_topic(dataset, sp_topic, ["alt_sp_up"])
        act_signal = self._find_signal_in_topic(dataset, act_topic, ["alt_up"])
        if sp_signal is None:
            sp_signal = self._find_signal_in_topic(dataset, sp_topic, ["z_deriv", "z"])
        if act_signal is None:
            act_signal = self._find_signal_in_topic(dataset, act_topic, ["z"])
        self._render_pair(
            target_plot,
            file_name,
            sp_topic,
            sp_signal,
            act_topic,
            act_signal,
            "Altitude vs Altitude Setpoint",
        )

    # ── Battery Status auto plots (2026-05-14) ──────────────────────────
    # Per-instance one-shot Analysis menu shortcuts that build plots from
    # the matching `battery_status_<inst>` topic. Power_W / Remaining %
    # are computed on the fly and cached in `custom_series_data` without a
    # registered spec, so they render via the standard custom-series URI
    # path but do NOT pollute the user-facing Custom Series list.

    def _battery_topic_name(self, dataset, instance):
        topic = f"battery_status_{int(instance)}"
        if topic in dataset.topics:
            return topic
        return None

    def _battery_missing_msg(self, instance):
        QMessageBox.warning(
            self,
            "Analysis",
            f"battery_status_{int(instance)} 토픽을 로그에서 찾지 못했습니다.",
        )

    def generate_battery_voltage_plot(self, instance):
        title = f"Battery {int(instance)} Voltage"
        _, target_plot = self._prepare_tools_plot(title)
        if target_plot is None:
            return
        file_name, dataset, _ = self._get_dataset_for_tools(target_plot)
        if dataset is None:
            QMessageBox.information(self, "Analysis", "먼저 로그를 로드해 주세요.")
            return
        topic = self._battery_topic_name(dataset, instance)
        if topic is None:
            self._battery_missing_msg(instance)
            return
        items = []
        # (2026-05-31) 두 토픽 동시 표시: raw=빨강(#FF0000), filtered=파랑(#0000FF) 로 고정.
        if self._find_signal_in_topic(dataset, topic, ["voltage_v"]):
            items.append((topic, "voltage_v", "#FF0000"))
        if self._find_signal_in_topic(dataset, topic, ["voltage_filtered_v"]):
            items.append((topic, "voltage_filtered_v", "#0000FF"))
        self._render_signals(target_plot, file_name, items, title)

