    def _battery_inject_custom_series(self, file_name, series_name, t_arr, y_arr):
        """Cache (t, y) into custom_series_data without registering a spec.
        Hidden from the user-facing Custom Series list (which iterates only
        custom_series_defs)."""
        mask = np.isfinite(t_arr) & np.isfinite(y_arr)
        if not np.any(mask):
            return False
        t_clean = np.asarray(t_arr[mask], dtype=np.float64)
        y_clean = np.asarray(y_arr[mask], dtype=np.float64)
        self.custom_series_data.setdefault(file_name, {})[series_name] = (t_clean, y_clean)
        return True

    def generate_battery_power_plot(self, instance):
        title = f"Battery {int(instance)} Power (W)"
        _, target_plot = self._prepare_tools_plot(title)
        if target_plot is None:
            return
        file_name, dataset, _ = self._get_dataset_for_tools(target_plot)
        if dataset is None:
            QMessageBox.information(self, "Analysis", "먼저 로그를 로드해 주세요.")
            return
        topic = self._battery_topic_name(dataset, instance)
        if topic is None:
            self._battery_missing_msg(instance)
            return
        df = dataset.topics[topic].dataframe
        if "timestamp_sec" not in df.columns:
            QMessageBox.warning(self, "Analysis", "timestamp_sec 컬럼을 찾지 못했습니다.")
            return
        t = np.asarray(df["timestamp_sec"].to_numpy(), dtype=np.float64)
        items = []
        if "voltage_v" in df.columns and "current_a" in df.columns:
            v = np.asarray(df["voltage_v"].to_numpy(), dtype=np.float64)
            a = np.asarray(df["current_a"].to_numpy(), dtype=np.float64)
            series_name = f"Battery {int(instance)} Power (W)"
            # (2026-05-31) 두 토픽 동시 표시: raw=빨강(#FF0000), filtered=파랑(#0000FF) 로 고정.
            if self._battery_inject_custom_series(file_name, series_name, t, v * a):
                items.append((self.CUSTOM_SERIES_TOPIC, series_name, "#FF0000"))
        if "voltage_filtered_v" in df.columns and "current_filtered_a" in df.columns:
            vf = np.asarray(df["voltage_filtered_v"].to_numpy(), dtype=np.float64)
            af = np.asarray(df["current_filtered_a"].to_numpy(), dtype=np.float64)
            series_name = f"Battery {int(instance)} Power Filtered (W)"
            if self._battery_inject_custom_series(file_name, series_name, t, vf * af):
                items.append((self.CUSTOM_SERIES_TOPIC, series_name, "#0000FF"))
        if not items:
            QMessageBox.warning(self, "Analysis", "Power_W 계산에 필요한 voltage/current 신호를 찾지 못했습니다.")
            return
        self._render_signals(target_plot, file_name, items, title)

    def generate_battery_usage_plot(self, instance):
        title_top = f"Battery {int(instance)} Discharged (mAh)"
        title_bot = f"Battery {int(instance)} Remaining (%)"
        _, target_plot = self._prepare_tools_plot(title_top)
        if target_plot is None:
            return
        file_name, dataset, _ = self._get_dataset_for_tools(target_plot)
        if dataset is None:
            QMessageBox.information(self, "Analysis", "먼저 로그를 로드해 주세요.")
            return
        topic = self._battery_topic_name(dataset, instance)
        if topic is None:
            self._battery_missing_msg(instance)
            return
        df = dataset.topics[topic].dataframe
        if "timestamp_sec" not in df.columns:
            QMessageBox.warning(self, "Analysis", "timestamp_sec 컬럼을 찾지 못했습니다.")
            return

        has_disc = "discharged_mah" in df.columns
        has_remaining = "remaining" in df.columns
        if not has_disc and not has_remaining:
            QMessageBox.warning(self, "Analysis", "discharged_mah / remaining 신호를 찾지 못했습니다.")
            return

        # Top plot: discharged_mah (or remaining if discharged missing).
        if has_disc:
            self._render_signals(
                target_plot,
                file_name,
                [(topic, "discharged_mah", "#1f77b4")],
                title_top,
            )
        # Vertical split → bottom plot for remaining%.
        bottom_plot = target_plot.split_layout(Qt.Vertical)
        if bottom_plot is None:
            QMessageBox.warning(self, "Analysis", "그래프 분할에 실패했습니다.")
            return
        if has_remaining:
            t = np.asarray(df["timestamp_sec"].to_numpy(), dtype=np.float64)
            r = np.asarray(df["remaining"].to_numpy(), dtype=np.float64)
            series_name = f"Battery {int(instance)} Remaining (%)"
            if self._battery_inject_custom_series(file_name, series_name, t, r * 100.0):
                self._render_signals(
                    bottom_plot,
                    file_name,
                    [(self.CUSTOM_SERIES_TOPIC, series_name, "#2ca02c")],
                    title_bot,
                )

    def _build_attitude_error_topic(self, dataset, axis):
        sp_topic = self._find_topic_by_prefixes(dataset, "vehicle_attitude_setpoint")
        act_topic = self._find_topic_by_prefixes(dataset, "vehicle_attitude")
        sp_candidates = {
            "pitch": ["pitch_sp_euler", "pitch"],
            "roll": ["roll_sp_euler", "roll"],
            "yaw": ["yaw_sp_euler", "yaw"],
        }
        act_candidates = {
            "pitch": ["pitch_euler", "pitch"],
            "roll": ["roll_euler", "roll"],
            "yaw": ["yaw_euler", "yaw"],
        }
        sp_signal = self._find_signal_in_topic(dataset, sp_topic, sp_candidates.get(axis, []))
        act_signal = self._find_signal_in_topic(dataset, act_topic, act_candidates.get(axis, []))
        if not sp_topic or not act_topic or not sp_signal or not act_signal:
            return None, None

        act_df = (
            dataset.topics[act_topic].dataframe
            .select([
                pl.col("timestamp_sec").cast(pl.Float64),
                pl.col(act_signal).cast(pl.Float64).alias("actual"),
            ])
            .drop_nulls()
            .sort("timestamp_sec")
        )
        sp_df = (
            dataset.topics[sp_topic].dataframe
            .select([
                pl.col("timestamp_sec").cast(pl.Float64),
                pl.col(sp_signal).cast(pl.Float64).alias("setpoint"),
            ])
            .drop_nulls()
            .sort("timestamp_sec")
        )
        if len(act_df) == 0 or len(sp_df) == 0:
            return None, None

        merged = act_df.join_asof(sp_df, on="timestamp_sec", strategy="nearest")
        merged = merged.drop_nulls(subset=["actual", "setpoint"])
        if len(merged) == 0:
            return None, None
        merged = merged.with_columns((pl.col("actual") - pl.col("setpoint")).alias("error"))
        error_df = merged.select(["timestamp_sec", "error"])

        base_name = f"analysis_attitude_error_{axis}"
        topic_inst = TopicInstance(base_name=base_name, instance_id=0, dataframe=error_df)
        topic_inst.signals["error"] = LogSignal(name="error", data=error_df["error"])
        dataset.add_topic(topic_inst)
        return topic_inst.unique_name, "error"

    def generate_attitude_error_plot(self, axis):
        # Analysis → Attitude Error → Pitch/Roll/Yaw 메뉴 핸들러. color="#FFB300" 의 hex 색을 바꾸면 곡선 색이, setTitle 문자열을 바꾸면 그래프 제목이 바뀝니다.
        _, target_plot = self._prepare_tools_plot(f"{self._axis_name(axis)} Attitude Error (Actual - Setpoint)")
        if target_plot is None:
            return
        file_name, dataset, _ = self._get_dataset_for_tools(target_plot)
        if dataset is None:
            QMessageBox.information(self, "Analysis", "먼저 로그를 로드해 주세요.")
            return

        error_topic, error_signal = self._build_attitude_error_topic(dataset, axis)
        if not error_topic:
            QMessageBox.warning(self, "Analysis", f"{self._axis_name(axis)} error 계산용 신호를 찾지 못했습니다.")
            return

        target_plot.clear_plot_data()
        target_plot.plot.setTitle(f"{self._axis_name(axis)} Attitude Error (Actual - Setpoint)")
        target_plot.render_signal(file_name, error_topic, error_signal, color="#FFB300")
        target_plot.auto_fit_view()
        self._reset_tools_workspace_to_full_range(target_plot)

    def generate_vibration_fft_plot(self):
        # Analysis → Vibration Analysis (가속도계 X/Y/Z 동시 FFT) 메뉴 핸들러. candidates 의 hex 색(#FF6B6B/#33CC66/#4DA3FF) 을 바꾸면 축별 곡선 색이 바뀝니다.
        _, target_plot = self._prepare_tools_plot("Vibration Analysis: Accel FFT")
        if target_plot is None:
            return
        file_name, dataset, _ = self._get_dataset_for_tools(target_plot)
        if dataset is None:
            QMessageBox.information(self, "Analysis", "먼저 로그를 로드해 주세요.")
            return

        accel_topic = self._find_topic_by_prefixes(dataset, "sensor_combined")
        if not accel_topic:
            QMessageBox.warning(self, "Analysis", "sensor_combined 토픽을 찾지 못했습니다.")
            return

        cols = dataset.topics[accel_topic].dataframe.columns
        candidates = [("accelerometer_m_s2[0]", "#FF6B6B"), ("accelerometer_m_s2[1]", "#33CC66"), ("accelerometer_m_s2[2]", "#4DA3FF")]

        target_plot.clear_plot_data()
        target_plot.plot.setTitle("Vibration Analysis: Accel FFT")
        rendered = False
        for col, color in candidates:
            if col in cols:
                rendered = target_plot.render_signal(file_name, accel_topic, col, color=color, is_fft=True) or rendered
        if not rendered:
            QMessageBox.warning(self, "Analysis", "가속도 FFT에 사용할 신호를 찾지 못했습니다.")
            return
        target_plot.auto_fit_view()

    @staticmethod
    def _fft_axis_color(axis_idx):
        if axis_idx == 0:
            return "#FF6B6B"
        if axis_idx == 1:
            return "#33CC66"
        if axis_idx == 2:
            return "#4DA3FF"
        return "#4DA3FF"

    @staticmethod
    def _find_signal_with_tokens(columns, axis_idx, token_groups):
        axis_tag = f"[{axis_idx}]"
        for col in columns:
            lower_col = col.lower()
            if axis_tag not in lower_col:
                continue
            for tokens in token_groups:
                if all(t in lower_col for t in tokens):
                    return col
        return None

    def _resolve_fft_source(self, dataset, sensor_kind, axis_idx):
        if sensor_kind == "accel":
            topic_prefixes = ["sensor_combined", "vehicle_acceleration", "vehicle_imu"]
            candidate_signals = [
                f"accelerometer_m_s2[{axis_idx}]",
                f"accel_m_s2[{axis_idx}]",
                f"accelerometer[{axis_idx}]",
                f"accel[{axis_idx}]",
                f"xyz[{axis_idx}]",
            ]
            token_groups = [
                ("accelerometer",),
                ("accel",),
                ("m_s2",),
            ]
        else:
            topic_prefixes = ["sensor_combined", "vehicle_angular_velocity", "vehicle_imu"]
            candidate_signals = [
                f"gyro_rad[{axis_idx}]",
                f"gyroscope_rad[{axis_idx}]",
                f"gyro[{axis_idx}]",
                f"angular_velocity_rad_s[{axis_idx}]",
                f"angular_rate_rad_s[{axis_idx}]",
                f"xyz[{axis_idx}]",
            ]
            token_groups = [
                ("gyro",),
                ("gyroscope",),
                ("angular", "velocity"),
                ("angular", "rate"),
            ]

        for prefix in topic_prefixes:
            topic_name = self._find_topic_by_prefixes(dataset, prefix)
            if not topic_name:
                continue
            signal_name = self._find_signal_in_topic(dataset, topic_name, candidate_signals)
            if signal_name:
                return topic_name, signal_name

            cols = dataset.topics[topic_name].dataframe.columns
            fallback_signal = self._find_signal_with_tokens(cols, axis_idx, token_groups)
            if fallback_signal:
                return topic_name, fallback_signal

        return None, None

    def generate_vibration_fft_axis(self, sensor_kind, axis_idx):
        # Analysis → Vibration Analysis → Accel/Gyro FFT [N] 메뉴 핸들러. _fft_axis_color 의 hex 값을 바꾸면 축별 곡선 색이, QMessageBox 의 "지원하지 않는 FFT 타입입니다." / "축 인덱스는 0, 1, 2만 지원합니다." 등 문자열을 바꾸면 안내가 바뀝니다.
        sensor_kind = (sensor_kind or "").strip().lower()
        if sensor_kind not in ("accel", "gyro"):
            QMessageBox.warning(self, "Analysis", "지원하지 않는 FFT 타입입니다.")
            return
        if axis_idx not in (0, 1, 2):
            QMessageBox.warning(self, "Analysis", "축 인덱스는 0, 1, 2만 지원합니다.")
            return

        label_prefix = "Accel" if sensor_kind == "accel" else "Gyro"
        target_title = f"Vibration Analysis: {label_prefix}[{axis_idx}] FFT"
        _, target_plot = self._prepare_tools_plot(target_title)
        if target_plot is None:
            return

        file_name, dataset, _ = self._get_dataset_for_tools(target_plot)
        if dataset is None:
            QMessageBox.information(self, "Analysis", "먼저 로그를 로드해 주세요.")
            return

        topic_name, signal_name = self._resolve_fft_source(dataset, sensor_kind, axis_idx)
        if not topic_name or not signal_name:
            QMessageBox.warning(
                self,
                "Analysis",
                f"{label_prefix}[{axis_idx}] FFT에 사용할 신호를 찾지 못했습니다.",
            )
            return

        target_plot.clear_plot_data()
        target_plot.plot.setTitle(target_title)
        color = self._fft_axis_color(axis_idx)
        ok = target_plot.render_signal(file_name, topic_name, signal_name, color=color, is_fft=True)
        if not ok:
            QMessageBox.warning(self, "Analysis", f"{label_prefix}[{axis_idx}] FFT 그래프 생성에 실패했습니다.")
            return
        target_plot.auto_fit_view()

    # (2026-05-31) Actuator PWM 색상 팔레트 — MC, VTOL/FW 둘 다 공통 사용.
    # 0/2 = 빨강 (#FF0000), 1/3 = 파랑 (#0000FF) — PX4 멀티콥터 모터 회전방향(CW/CCW) 구분에 맞춤.
    # 4번 이상은 보조 색상.
    _ACTUATOR_PWM_COLORS = (
        "#FF0000",  # 0: 빨강
        "#0000FF",  # 1: 파랑
        "#FF0000",  # 2: 빨강
        "#0000FF",  # 3: 파랑
        "#FFCC33",  # 4: 노랑 (호버 모터 등)
        "#9966FF",  # 5
        "#FF9966",  # 6
        "#66CCCC",  # 7
    )

    def _collect_actuator_pwm_items(self, dataset, topic_prefix, indices):
        # 공통 헬퍼 — 주어진 토픽 prefix(actuator_motors / actuator_servos) 에서 control_pwm[idx] 시그널
        # 들을 색상 매핑해 반환. 데이터 없는 인덱스는 자동 skip.
        topic = self._find_topic_by_prefixes(dataset, topic_prefix)
        if topic is None or topic not in dataset.topics:
            return None, []
        df = dataset.topics[topic].dataframe
        items = []
        for idx in indices:
            col = f"control_pwm[{idx}]"
            if col in df.columns:
                items.append((topic, col, self._ACTUATOR_PWM_COLORS[idx % len(self._ACTUATOR_PWM_COLORS)]))
        return topic, items

    def generate_actuator_pwm_mc_plot(self):
        # Analysis → Actuator → MC (PWM) 메뉴 핸들러.
        # 순수 멀티콥터 — actuator_motors_0.control_pwm[0~4] 를 한 화면에 5 라인 도시화. 조종면(서보)
        # 분석이 필요한 VTOL 은 VTOL/FW 메뉴를 사용. preprocess 가 control_pwm 컬럼을 미리 만들어 둠.
        title = "Actuator PWM — MC (Motors 0~4)"
        _, target_plot = self._prepare_tools_plot(title)
        if target_plot is None:
            return
        file_name, dataset, _ = self._get_dataset_for_tools(target_plot)
        if dataset is None:
            QMessageBox.information(self, "Analysis", "먼저 로그를 로드해 주세요.")
            return
        _, items = self._collect_actuator_pwm_items(dataset, "actuator_motors", (0, 1, 2, 3, 4))
        if not items:
            QMessageBox.warning(
                self, "Analysis",
                f"{title}: 사용 가능한 actuator_motors.control_pwm[i] 컬럼이 없습니다.\n"
                "ulg 를 다시 로드해 preprocess 가 PWM 컬럼을 만들도록 해 주세요.",
            )
            return
        self._render_signals(target_plot, file_name, items, title)

    def generate_actuator_pwm_vtol_fw_plot(self):
        # Analysis → Actuator → VTOL/FW (Motors + Servos) 메뉴 핸들러.
        # VTOL/Fixed-Wing 둘 다 조종면(서보) 분석이 필요해 모터+서보를 2행 분할로 함께 도시.
        # 위 row: actuator_motors[0~4] / 아래 row: actuator_servos[0~4]. split_layout(Qt.Vertical) 로
        # 같은 그래프 창을 위/아래 2행으로 자동 분할. 단위는 둘 다 PWM(us) — 같은 스케일이라 비교 용이.
        title_motor = "VTOL/FW Actuator PWM — Motors (0~4)"
        title_servo = "VTOL/FW Servo Output PWM (0~4)"
        _, motor_plot = self._prepare_tools_plot(title_motor)
        if motor_plot is None:
            return
        file_name, dataset, _ = self._get_dataset_for_tools(motor_plot)
        if dataset is None:
            QMessageBox.information(self, "Analysis", "먼저 로그를 로드해 주세요.")
            return

        # 1) 위 row: 모터 PWM
        _, motor_items = self._collect_actuator_pwm_items(
            dataset, "actuator_motors", (0, 1, 2, 3, 4)
        )
        if motor_items:
            self._render_signals(motor_plot, file_name, motor_items, title_motor)

        # 2) 아래 row: 서보 PWM — split 후 새 plot 에 그림.
        _, servo_items = self._collect_actuator_pwm_items(
            dataset, "actuator_servos", (0, 1, 2, 3, 4)
        )
        if not servo_items:
            # 서보 데이터 자체가 없으면 분할 의미 X — 모터만 띄우고 안내.
            QMessageBox.information(
                self, "Analysis",
                "actuator_servos 토픽이 없어 모터 PWM 만 표시합니다. (F/W 서보 출력 데이터 없음)",
            )
            return
        try:
            # Qt.Vertical splitter = 자식 위젯을 위/아래로 배치 → 2행 분할.
            servo_plot = motor_plot.split_layout(Qt.Vertical)
        except Exception:
            servo_plot = None
            traceback.print_exc()
        if servo_plot is None:
            QMessageBox.warning(self, "Analysis", "그래프 분할에 실패해 모터 PWM 만 표시됩니다.")
            return
        self._render_signals(servo_plot, file_name, servo_items, title_servo)

    def generate_flight_path_2d_plot(self):
        # Analysis → Flight Path → 2D Path 메뉴 핸들러. setTitle("2D Flight Path") 문자열을 바꾸면 그래프 제목이, QMessageBox 의 "2D Flight Path 생성에 필요한 좌표 신호를 찾지 못했습니다." 문자열을 바꾸면 안내가 바뀝니다.
        _, target_plot = self._prepare_tools_plot("2D Flight Path")
        if target_plot is None:
            return
        file_name, dataset, _ = self._get_dataset_for_tools(target_plot)
        if dataset is None:
            QMessageBox.information(self, "Analysis", "먼저 로그를 로드해 주세요.")
            return
        if not self._render_2d_flight_path_in_plot(target_plot, file_name, dataset):
            QMessageBox.warning(self, "Analysis", "2D Flight Path 생성에 필요한 좌표 신호를 찾지 못했습니다.")

    def generate_flight_path_2d_with_satellite_plot(self):
        # Analysis → Flight Path → 2D Path with Satellite 메뉴 핸들러.
        # 2D Path 를 먼저 렌더 → plot._geo_origin_latlon 결정됨 → 위성 배경 추가.
        # setTitle 문자열을 바꾸면 그래프 제목이 바뀝니다.
        title = "2D Flight Path + Satellite"
        _, target_plot = self._prepare_tools_plot(title)
        if target_plot is None:
            return
        file_name, dataset, _ = self._get_dataset_for_tools(target_plot)
        if dataset is None:
            QMessageBox.information(self, "Analysis", "먼저 로그를 로드해 주세요.")
            return
        if not self._render_2d_flight_path_in_plot(target_plot, file_name, dataset):
            QMessageBox.warning(self, "Analysis", "2D Flight Path 생성에 필요한 좌표 신호를 찾지 못했습니다.")
            return
        try:
            target_plot.plot.setTitle(title)
        except Exception:
            pass
        self._add_satellite_background_to_2d_plot(target_plot, dataset, silent=False)

    def _add_satellite_background_to_2d_plot(self, plot, dataset, silent=False):
        # 비행 영역에 위성 타일 stitch → pyqtgraph.ImageItem 으로 2D Path 바닥 평면에 깖.
        # 정합 핵심: _render_2d_flight_path_in_plot 이 plot._geo_origin_latlon 에 저장해 둔
        # 원점 (global 모드 = median, local 모드 = ref_lat/ref_lon) 을 그대로 사용 → 비행 path 와 픽셀 align.
        try:
            from engines.satellite_tiles import build_flight_area_satellite, lla_to_enu
        except Exception as e:
            if not silent:
                QMessageBox.warning(self, "Analysis", f"위성 모듈 로드 실패:\n{e}")
            return False
        origin = getattr(plot, "_geo_origin_latlon", None)
        if origin is None:
            if not silent:
                QMessageBox.warning(
                    self, "Analysis",
                    "위성 배경 정렬용 원점이 없습니다. (vehicle_global_position 또는 ref_lat 필요)",
                )
            return False
        lat0, lon0 = float(origin[0]), float(origin[1])
        try:
            self.statusBar().showMessage("위성 타일 다운로드 중...", 0)
            QApplication.processEvents()
        except Exception:
            pass
        try:
            # (2026-05-28) plot._geo_origin_latlon 을 ref 로 전달 → 위성 영역이 비행 path 와
            # 같은 NED 좌표계 범위로 잡힘. global_position GPS fix 가 일부만 있어도 cover OK.
            result = build_flight_area_satellite(dataset, ref_lat=lat0, ref_lon=lon0)
        except Exception as e:
            traceback.print_exc()
            if not silent:
                QMessageBox.warning(self, "Analysis", f"위성 타일 다운로드 실패:\n{e}")
            return False
        if result is None:
            if not silent:
                QMessageBox.warning(
                    self, "Analysis",
                    "위성 타일을 가져오지 못했습니다.\n인터넷 연결 또는 캐시(~/.log_ansys_cache)를 확인하세요.",
                )
            return False
        rgba, latlon_bbox, zoom, missing = result
        lat_north, lat_south, lon_west, lon_east = latlon_bbox

        # 4 corners → ENU 변환. plot 좌표계: X=east, Y=north (m).
        east_west, _ = lla_to_enu(lat0, lon_west, lat0, lon0)
        east_east, _ = lla_to_enu(lat0, lon_east, lat0, lon0)
        _, north_south = lla_to_enu(lat_south, lon0, lat0, lon0)
        _, north_north = lla_to_enu(lat_north, lon0, lat0, lon0)
        rect_x = float(east_west)
        rect_y = float(north_south)
        rect_w = float(east_east - east_west)
        rect_h = float(north_north - north_south)

        # 이전 위성 배경 제거 (재진입 정리).
        prev = getattr(plot, "_satellite_overlay_items_2d", None) or []
        for prev_item in prev:
            try:
                plot.plot.removeItem(prev_item)
            except Exception:
                pass
        plot._satellite_overlay_items_2d = []

        try:
            # ImageItem 은 numpy (H, W, 4) 받음. axisOrder='row-major' 에서 row 0 → y_min
            # 매핑이라 numpy 자체를 vertical flip 해야 화면에서 위쪽=북쪽이 됨.
            # horizontal flip 은 불필요 — col 0 → x_min 매핑이 정상.
            from PySide6.QtCore import QRectF
            rgba_flipped = np.ascontiguousarray(rgba[::-1, :, :])
            img_item = pg.ImageItem(image=rgba_flipped, axisOrder="row-major")
            img_item.setRect(QRectF(rect_x, rect_y, rect_w, rect_h))
            img_item.setZValue(-100)  # 비행 경로 라인 아래로.
            try:
                img_item.setOpacity(0.92)
            except Exception:
                pass
            plot.plot.addItem(img_item, ignoreBounds=True)
            plot._satellite_overlay_items_2d.append(img_item)
        except Exception:
            traceback.print_exc()
            if not silent:
                QMessageBox.warning(self, "Analysis", "ImageItem 생성/추가 실패.")
            return False

        # (2026-05-28) 위성 영역은 비행 path 보다 크게 fetch 됐음 → viewport 를 비행 path 영역으로
        # 강제 set → 화면 가득 위성. 그 외 영역은 사용자가 줌아웃하면 보임 (위성 cover 한계까지).
        try:
            flight_extent = self._compute_flight_path_extent_enu(dataset)
            if flight_extent is not None:
                east_min, east_max, north_min, north_max = flight_extent
                vb = plot.plot.getViewBox()
                vb.setRange(
                    xRange=(east_min, east_max),
                    yRange=(north_min, north_max),
                    padding=0.08,
                )
        except Exception:
            traceback.print_exc()

        try:
            self.statusBar().showMessage(
                f"2D 위성 배경 추가 (Esri World Imagery, zoom {zoom}, missing tiles: {missing})",
                4500,
            )
        except Exception:
            pass
        return True

    def generate_flight_path_2d_with_kmz_overlay_plot(self):
        # Analysis → Flight Path → 2D Path with Map Overlay (KMZ)... 메뉴 핸들러.
        # 사용자가 미리 만든 KMZ (GroundOverlay + 위경도 4 corner 포함) 를 골라 2D Path 배경으로 사용.
        # 인터넷 없이 현장에서 정확한 지도 활용 가능. setTitle 문자열 바꾸면 그래프 제목 바뀜.
        file_path, _ = QFileDialog.getOpenFileName(
            self,
            "KMZ/KML 파일 선택 (GroundOverlay 포함)",
            "",
            "KMZ/KML files (*.kmz *.kml);;All files (*.*)",
        )
        if not file_path:
            return
        title = "2D Flight Path + Map Overlay"
        _, target_plot = self._prepare_tools_plot(title)
        if target_plot is None:
            return
        file_name, dataset, _ = self._get_dataset_for_tools(target_plot)
        if dataset is None:
            QMessageBox.information(self, "Analysis", "먼저 로그를 로드해 주세요.")
            return
        if not self._render_2d_flight_path_in_plot(target_plot, file_name, dataset):
            QMessageBox.warning(self, "Analysis", "2D Flight Path 생성에 필요한 좌표 신호를 찾지 못했습니다.")
            return
        try:
            target_plot.plot.setTitle(title)
        except Exception:
            pass
        try:
            from engines.kmz_loader import load_kml_items, decode_groundoverlay_image, lla_to_enu
            items = load_kml_items(file_path)
        except Exception as e:
            traceback.print_exc()
            QMessageBox.warning(self, "Analysis", f"KMZ/KML 파싱 실패:\n{e}")
            return
        overlays = [it for it in items if it.get("type") == "groundoverlay"]
        if not overlays:
            QMessageBox.warning(
                self, "Analysis",
                "KMZ 안에 GroundOverlay 가 없습니다.\n"
                "Google Earth Pro: 추가 → 이미지 오버레이 로 만든 후 KMZ 로 저장하세요.",
            )
            return
        origin = getattr(target_plot, "_geo_origin_latlon", None)
        if origin is None:
            QMessageBox.warning(
                self, "Analysis",
                "지도 정렬용 원점이 없습니다. (vehicle_global_position 또는 ref_lat 필요)",
            )
            return
        lat0, lon0 = float(origin[0]), float(origin[1])

        # 기존 KMZ 배경 제거 (재진입 정리).
        prev = getattr(target_plot, "_kmz_overlay_items_2d", None) or []
        for prev_item in prev:
            try:
                target_plot.plot.removeItem(prev_item)
            except Exception:
                pass
        target_plot._kmz_overlay_items_2d = []

        added_count = 0
        from PySide6.QtCore import QRectF
        for ov in overlays:
            rgba = decode_groundoverlay_image(ov)
            if rgba is None:
                continue
            north, south = ov["north"], ov["south"]
            east, west = ov["east"], ov["west"]
            # 4 corner → ENU
            east_w, _ = lla_to_enu(lat0, west, lat0, lon0)
            east_e, _ = lla_to_enu(lat0, east, lat0, lon0)
            _, north_s = lla_to_enu(south, lon0, lat0, lon0)
            _, north_n = lla_to_enu(north, lon0, lat0, lon0)
            rect_x = float(east_w)
            rect_y = float(north_s)
            rect_w = float(east_e - east_w)
            rect_h = float(north_n - north_s)
            # 위성 코드와 동일하게 vertical flip (row 0 → y_min 매핑 보정).
            rgba_flipped = np.ascontiguousarray(rgba[::-1, :, :])
            try:
                img_item = pg.ImageItem(image=rgba_flipped, axisOrder="row-major")
                img_item.setRect(QRectF(rect_x, rect_y, rect_w, rect_h))
                img_item.setZValue(-100)
                # 사용자 KMZ 는 의도된 지도 — 투명도 살짝만 (가독성).
                try:
                    img_item.setOpacity(0.95)
                except Exception:
                    pass
                target_plot.plot.addItem(img_item, ignoreBounds=True)
                target_plot._kmz_overlay_items_2d.append(img_item)
                added_count += 1
            except Exception:
                traceback.print_exc()

        # 비행 path 영역으로 viewport fit.
        try:
            flight_extent = self._compute_flight_path_extent_enu(dataset)
            if flight_extent is not None:
                east_min, east_max, north_min, north_max = flight_extent
                vb = target_plot.plot.getViewBox()
                vb.setRange(
                    xRange=(east_min, east_max),
                    yRange=(north_min, north_max),
                    padding=0.08,
                )
        except Exception:
            pass

        try:
            self.statusBar().showMessage(
                f"Map Overlay 추가: {added_count}개 ({os.path.basename(file_path)})",
                5000,
            )
        except Exception:
            pass

    @staticmethod
    def _compute_flight_path_extent_enu(dataset):
        # (2026-05-28) vehicle_local_position 의 (x=N, y=E) min/max → (east_min, east_max, north_min, north_max).
        # 위성 viewport fit 용 — 비행 path 가 화면 가운데 잘 들어가도록.
        try:
            topic = dataset.topics.get("vehicle_local_position_0") if hasattr(dataset, "topics") else None
            if topic is None:
                return None
            df = topic.dataframe
            if "x" not in df.columns or "y" not in df.columns:
                return None
            x = df["x"].to_numpy().astype("float64")
            y = df["y"].to_numpy().astype("float64")
            valid = np.isfinite(x) & np.isfinite(y)
            if not valid.any():
                return None
            x = x[valid]; y = y[valid]
            north_min, north_max = float(np.min(x)), float(np.max(x))
            east_min, east_max = float(np.min(y)), float(np.max(y))
            return (east_min, east_max, north_min, north_max)
        except Exception:
            return None

    def generate_flight_path_3d_plot(self):
        # Analysis → Flight Path → 3D Path 메뉴 핸들러. setTitle("3D Flight Path (Interactive)") / showMessage(f"3D Flight Path 생성 완료: {mode_text}") 문자열을 바꾸면 그래프 제목과 상태바 안내가 바뀝니다.
        _, target_plot = self._prepare_tools_plot("3D Flight Path (Interactive)")
