    def _find_arming_timestamp_seconds(self, dataset):
        """Return timestamp_sec at which the vehicle first armed, or None.

        Robust across PX4 firmware versions: finds the first index where
        `arming_state` reaches its maximum value seen in the trace (typically
        ARMED == 2 on older PX4 / == 1 on some newer builds). Falls back to
        first non-zero arming_state if the max is 1, since both interpretations
        agree on that boundary.
        """
        if not dataset:
            return None
        topic_name = self._find_topic_by_prefixes(dataset, "vehicle_status")
        if not topic_name:
            return None
        topic = dataset.topics.get(topic_name)
        if not topic:
            return None
        df = topic.dataframe
        if df is None:
            return None
        cols = df.columns
        if "arming_state" not in cols or "timestamp_sec" not in cols:
            return None
        try:
            states = np.asarray(df["arming_state"].to_numpy(), dtype=np.float64)
            ts = np.asarray(df["timestamp_sec"].to_numpy(), dtype=np.float64)
        except Exception:
            return None
        if states.size == 0 or ts.size == 0 or states.size != ts.size:
            return None
        finite_mask = np.isfinite(states) & np.isfinite(ts)
        if not np.any(finite_mask):
            return None
        s = states[finite_mask]
        t = ts[finite_mask]
        try:
            max_state = float(np.nanmax(s))
        except Exception:
            return None
        if not np.isfinite(max_state) or max_state <= 0:
            return None
        armed_mask = s >= max_state - 1e-9
        if not np.any(armed_mask):
            return None
        first_idx = int(np.argmax(armed_mask))
        return float(t[first_idx])

    def _interp_signal_to_grid(self, dataset, topic_name, signal_candidates, t_grid):
        """Find the first available signal in `signal_candidates` from the
        topic and linearly interpolate it onto `t_grid`. Returns NaN array of
        len(t_grid) if any input is missing or invalid."""
        n = int(np.asarray(t_grid).size) if t_grid is not None else 0
        nan_arr = np.full(n, np.nan, dtype=np.float64) if n > 0 else np.array([], dtype=np.float64)
        if n == 0 or not dataset or not topic_name:
            return nan_arr
        topic = dataset.topics.get(topic_name)
        if not topic:
            return nan_arr
        df = topic.dataframe
        if df is None or "timestamp_sec" not in df.columns:
            return nan_arr
        signal_name = self._find_signal_in_topic(dataset, topic_name, list(signal_candidates))
        if not signal_name or signal_name not in df.columns:
            return nan_arr
        try:
            ts = np.asarray(df["timestamp_sec"].to_numpy(), dtype=np.float64)
            vs = np.asarray(df[signal_name].to_numpy(), dtype=np.float64)
        except Exception:
            return nan_arr
        m = np.isfinite(ts) & np.isfinite(vs)
        if not np.any(m):
            return nan_arr
        ts = ts[m]
        vs = vs[m]
        order = np.argsort(ts)
        ts = ts[order]
        vs = vs[order]
        if ts.size < 2:
            # Single sample → broadcast as a constant where the grid is within bounds.
            t_arr = np.asarray(t_grid, dtype=np.float64)
            out = np.full(t_arr.size, np.nan, dtype=np.float64)
            in_range = np.isclose(t_arr, ts[0], atol=1.0)
            out[in_range] = vs[0]
            return out
        unique = np.concatenate(([True], np.diff(ts) > 1e-9))
        ts = ts[unique]
        vs = vs[unique]
        t_arr = np.asarray(t_grid, dtype=np.float64)
        return np.interp(t_arr, ts, vs, left=np.nan, right=np.nan)

    def _sample_signal_to_grid_nearest(self, dataset, topic_name, signal_candidates, t_grid):
        """Sample a discrete signal onto `t_grid` by nearest timestamp."""
        n = int(np.asarray(t_grid).size) if t_grid is not None else 0
        nan_arr = np.full(n, np.nan, dtype=np.float64) if n > 0 else np.array([], dtype=np.float64)
        if n == 0 or not dataset or not topic_name:
            return nan_arr
        topic = dataset.topics.get(topic_name)
        if not topic:
            return nan_arr
        df = topic.dataframe
        if df is None or "timestamp_sec" not in df.columns:
            return nan_arr
        signal_name = self._find_signal_in_topic(dataset, topic_name, list(signal_candidates))
        if not signal_name or signal_name not in df.columns:
            return nan_arr
        try:
            ts = np.asarray(df["timestamp_sec"].to_numpy(), dtype=np.float64)
            vs = np.asarray(df[signal_name].to_numpy(), dtype=np.float64)
            t_arr = np.asarray(t_grid, dtype=np.float64)
        except Exception:
            return nan_arr
        finite = np.isfinite(ts) & np.isfinite(vs)
        if not np.any(finite):
            return nan_arr
        ts = ts[finite]
        vs = vs[finite]
        order = np.argsort(ts)
        ts = ts[order]
        vs = vs[order]
        unique = np.concatenate(([True], np.diff(ts) > 1e-9))
        ts = ts[unique]
        vs = vs[unique]
        if ts.size == 0:
            return nan_arr

        out = np.full(t_arr.shape, np.nan, dtype=np.float64)
        for idx, target_t in enumerate(t_arr):
            if not np.isfinite(target_t):
                continue
            insert_idx = int(np.searchsorted(ts, float(target_t), side="left"))
            if insert_idx >= len(ts):
                nearest_idx = len(ts) - 1
            elif insert_idx > 0:
                prev_idx = insert_idx - 1
                if abs(float(ts[prev_idx]) - float(target_t)) <= abs(float(ts[insert_idx]) - float(target_t)):
                    nearest_idx = prev_idx
                else:
                    nearest_idx = insert_idx
            else:
                nearest_idx = insert_idx
            out[idx] = vs[nearest_idx]
        return out

    def _get_parameters_for_dataset(self, dataset):
        if not dataset:
            return {}
        for file_name, loaded_dataset in self.loaded_datasets.items():
            if loaded_dataset is not dataset:
                continue
            metadata = self.loaded_log_metadata.get(file_name)
            if isinstance(metadata, dict):
                params = metadata.get("parameters")
                if isinstance(params, dict):
                    return params
            break
        return {}

    @staticmethod
    def _param_float(parameters, key, default):
        if not isinstance(parameters, dict):
            return float(default)
        try:
            return float(parameters.get(key, default))
        except Exception:
            return float(default)

    @classmethod
    def _resolve_rc_axis_channel(cls, dataset, topic_name, parameters, map_key, fallback_channel):
        channel = int(fallback_channel)
        try:
            mapped = int(round(cls._param_float(parameters, map_key, float(fallback_channel))))
            if mapped > 0:
                channel = mapped
        except Exception:
            channel = int(fallback_channel)

        topic = dataset.topics.get(topic_name) if dataset and topic_name else None
        cols = set(topic.dataframe.columns) if topic and getattr(topic, "dataframe", None) is not None else set()

        def _signal_candidates(ch_num):
            idx = max(0, int(ch_num) - 1)
            return [f"values[{idx}]", f"value[{idx}]"]

        candidates = _signal_candidates(channel)
        if cols and not any(name in cols for name in candidates):
            channel = int(fallback_channel)
            candidates = _signal_candidates(channel)
        return channel, candidates

    @classmethod
    def _normalize_rc_centered_pwm(cls, pwm_arr, minimum, maximum, trim, reverse=1.0, deadzone=0.0):
        arr = np.asarray(pwm_arr, dtype=np.float64)
        out = np.full(arr.shape, np.nan, dtype=np.float64)
        finite = np.isfinite(arr)
        if not np.any(finite):
            return out

        min_v = float(minimum)
        max_v = float(maximum)
        trim_v = float(trim)
        if not np.isfinite(trim_v):
            trim_v = (min_v + max_v) * 0.5
        trim_v = min(max(trim_v, min_v), max_v)
        neg_span = max(1e-9, trim_v - min_v)
        pos_span = max(1e-9, max_v - trim_v)
        rev = -1.0 if float(reverse) < 0.0 else 1.0
        dz = max(0.0, float(deadzone))

        values = arr[finite]
        delta = values - trim_v
        if dz > 0.0:
            delta = np.where(np.abs(delta) <= dz, 0.0, delta)
        norm = np.empty_like(delta)
        neg_mask = delta < 0.0
        norm[neg_mask] = delta[neg_mask] / neg_span
        norm[~neg_mask] = delta[~neg_mask] / pos_span
        out[finite] = np.clip(norm * rev, -1.0, 1.0)
        return out

    @classmethod
    def _normalize_rc_throttle_pwm(cls, pwm_arr, minimum, maximum, reverse=1.0):
        arr = np.asarray(pwm_arr, dtype=np.float64)
        out = np.full(arr.shape, np.nan, dtype=np.float64)
        finite = np.isfinite(arr)
        if not np.any(finite):
            return out

        min_v = float(minimum)
        max_v = float(maximum)
        span = max(1e-9, max_v - min_v)
        values = (arr[finite] - min_v) / span
        if float(reverse) < 0.0:
            values = 1.0 - values
        out[finite] = np.clip(values, 0.0, 1.0)
        return out

    @staticmethod
    def _angles_to_radians_if_needed(arr):
        values = np.asarray(arr, dtype=np.float64)
        finite = values[np.isfinite(values)]
        if finite.size == 0:
            return values
        try:
            max_abs = float(np.nanmax(np.abs(finite)))
        except Exception:
            return values
        if max_abs > (2.0 * np.pi + 0.25):
            return np.deg2rad(values)
        return values

    @staticmethod
    def _quaternion_to_euler_arrays(qw, qx, qy, qz):
        qw = np.asarray(qw, dtype=np.float64)
        qx = np.asarray(qx, dtype=np.float64)
        qy = np.asarray(qy, dtype=np.float64)
        qz = np.asarray(qz, dtype=np.float64)
        roll = np.full(qw.shape, np.nan, dtype=np.float64)
        pitch = np.full(qw.shape, np.nan, dtype=np.float64)
        yaw = np.full(qw.shape, np.nan, dtype=np.float64)
        finite = np.isfinite(qw) & np.isfinite(qx) & np.isfinite(qy) & np.isfinite(qz)
        if not np.any(finite):
            return roll, pitch, yaw
        norm = np.sqrt(qw * qw + qx * qx + qy * qy + qz * qz)
        finite = finite & np.isfinite(norm) & (norm > 1e-9)
        if not np.any(finite):
            return roll, pitch, yaw

        w = qw[finite] / norm[finite]
        x = qx[finite] / norm[finite]
        y = qy[finite] / norm[finite]
        z = qz[finite] / norm[finite]

        sinr_cosp = 2.0 * (w * x + y * z)
        cosr_cosp = 1.0 - 2.0 * (x * x + y * y)
        roll[finite] = np.arctan2(sinr_cosp, cosr_cosp)

        sinp = 2.0 * (w * y - z * x)
        sinp = np.clip(sinp, -1.0, 1.0)
        pitch[finite] = np.arcsin(sinp)

        siny_cosp = 2.0 * (w * z + x * y)
        cosy_cosp = 1.0 - 2.0 * (y * y + z * z)
        yaw[finite] = np.arctan2(siny_cosp, cosy_cosp)
        return roll, pitch, yaw

    def _build_3d_attitude_to_grid(self, dataset, t_arr):
        # UI 수정 MainWindow._build_3d_attitude_to_grid UI 처리 변경
        nan_arr = np.full(np.asarray(t_arr).shape, np.nan, dtype=np.float64)
        att_topic = self._find_topic_by_prefixes(dataset, "vehicle_attitude")
        if not att_topic:
            return {
                "roll": nan_arr,
                "pitch": nan_arr,
                "yaw": nan_arr,
                "available": False,
            }

        qw = self._interp_signal_to_grid(dataset, att_topic, ["q[0]", "quat[0]"], t_arr)
        qx = self._interp_signal_to_grid(dataset, att_topic, ["q[1]", "quat[1]"], t_arr)
        qy = self._interp_signal_to_grid(dataset, att_topic, ["q[2]", "quat[2]"], t_arr)
        qz = self._interp_signal_to_grid(dataset, att_topic, ["q[3]", "quat[3]"], t_arr)
        if any(np.any(np.isfinite(arr)) for arr in (qw, qx, qy, qz)):
            roll_arr, pitch_arr, yaw_arr = self._quaternion_to_euler_arrays(qw, qx, qy, qz)
        else:
            roll_arr = self._angles_to_radians_if_needed(
                self._interp_signal_to_grid(dataset, att_topic, ["roll_euler", "roll", "roll_body"], t_arr)
            )
            pitch_arr = self._angles_to_radians_if_needed(
                self._interp_signal_to_grid(dataset, att_topic, ["pitch_euler", "pitch", "pitch_body"], t_arr)
            )
            yaw_arr = self._angles_to_radians_if_needed(
                self._interp_signal_to_grid(dataset, att_topic, ["yaw_euler", "yaw", "yaw_body"], t_arr)
            )

        available = any(np.any(np.isfinite(arr)) for arr in (roll_arr, pitch_arr, yaw_arr))
        return {
            "roll": roll_arr,
            "pitch": pitch_arr,
            "yaw": yaw_arr,
            "available": bool(available),
        }

    def _build_3d_flight_mode_to_grid(self, dataset, t_arr):
        # UI 수정 MainWindow._build_3d_flight_mode_to_grid UI 처리 변경
        nan_arr = np.full(np.asarray(t_arr).shape, np.nan, dtype=np.float64)
        vs_topic = self._find_topic_by_prefixes(dataset, "vehicle_status")
        if not vs_topic:
            return {
                "time": np.asarray(t_arr, dtype=np.float64),
                "nav_state": nan_arr,
                "available": False,
            }

        nav_state_arr = self._sample_signal_to_grid_nearest(dataset, vs_topic, ["nav_state"], t_arr)
        available = bool(np.any(np.isfinite(nav_state_arr)))
        return {
            "time": np.asarray(t_arr, dtype=np.float64),
            "nav_state": nav_state_arr,
            "available": available,
        }

    def _build_3d_path_value_extras(self, dataset, t_grid, x_grid, y_grid, alt_grid):
        """Build the value-overlay extras dict for an auto-generated 3D path.

        Returns a dict with arming origin (in path-plot coords) and TAS / GPS
        speed arrays aligned to the path's t_grid. Used by AdvancedPlot to
        enrich the Shift+Click value label with distance and speed lines.
        Returns None if t_grid is empty.
        """
        if t_grid is None or len(t_grid) == 0:
            return None
        t_arr = np.asarray(t_grid, dtype=np.float64)
        n = t_arr.size
        if x_grid is None or y_grid is None:
            return None
        x_arr = np.asarray(x_grid, dtype=np.float64)
        y_arr = np.asarray(y_grid, dtype=np.float64)
        alt_arr = np.asarray(alt_grid, dtype=np.float64) if alt_grid is not None else np.zeros(n, dtype=np.float64)
        if x_arr.size != n or y_arr.size != n or alt_arr.size != n:
            return None

        arming_t = self._find_arming_timestamp_seconds(dataset)
        arming_origin = None
        if arming_t is not None and np.isfinite(arming_t):
            # nearest index in t_arr to arming_t
            idx = int(np.argmin(np.abs(t_arr - float(arming_t))))
            if 0 <= idx < n:
                arming_origin = (
                    float(x_arr[idx]),
                    float(y_arr[idx]),
                    float(alt_arr[idx]),
                    int(idx),
                    float(arming_t),
                )

        tas_topic = self._find_topic_by_prefixes(dataset, ["airspeed_validated", "airspeed", "tecs_status"])
        tas_arr = self._interp_signal_to_grid(
            dataset,
            tas_topic,
            ["true_airspeed_m_s", "true_airspeed_filtered", "indicated_airspeed_m_s", "true_airspeed"],
            t_arr,
        )
        gps_topic = self._find_topic_by_prefixes(dataset, ["vehicle_gps_position", "vehicle_local_position"])
        gps_arr = self._interp_signal_to_grid(
            dataset,
            gps_topic,
            ["vel_m_s", "ground_speed_mag", "speed"],
            t_arr,
        )
        attitude = self._build_3d_attitude_to_grid(dataset, t_arr)
        flight_mode = self._build_3d_flight_mode_to_grid(dataset, t_arr)

        # The 3D joystick follows input_rc raw PWM. Prefer RC_MAP_* driven
        # channel selection, but fall back to the traditional 1/2/3/4 mapping
        # when the mapping is absent, zero, or not present in the log topic.
        rc_topic = self._find_topic_by_prefixes(dataset, "input_rc")
        rc_params = self._get_parameters_for_dataset(dataset)
        roll_ch, roll_sig = self._resolve_rc_axis_channel(dataset, rc_topic, rc_params, "RC_MAP_ROLL", 1)
        pitch_ch, pitch_sig = self._resolve_rc_axis_channel(dataset, rc_topic, rc_params, "RC_MAP_PITCH", 2)
        throttle_ch, throttle_sig = self._resolve_rc_axis_channel(dataset, rc_topic, rc_params, "RC_MAP_THROTTLE", 3)
        yaw_ch, yaw_sig = self._resolve_rc_axis_channel(dataset, rc_topic, rc_params, "RC_MAP_YAW", 4)

        roll_pwm = self._interp_signal_to_grid(dataset, rc_topic, roll_sig, t_arr)
        pitch_pwm = self._interp_signal_to_grid(dataset, rc_topic, pitch_sig, t_arr)
        throttle_pwm = self._interp_signal_to_grid(dataset, rc_topic, throttle_sig, t_arr)
        yaw_pwm = self._interp_signal_to_grid(dataset, rc_topic, yaw_sig, t_arr)

        roll_arr = self._normalize_rc_centered_pwm(
            roll_pwm,
            self._param_float(rc_params, f"RC{roll_ch}_MIN", 1000.0),
            self._param_float(rc_params, f"RC{roll_ch}_MAX", 2000.0),
            self._param_float(rc_params, f"RC{roll_ch}_TRIM", 1500.0),
            reverse=self._param_float(rc_params, f"RC{roll_ch}_REV", 1.0),
            deadzone=self._param_float(rc_params, f"RC{roll_ch}_DZ", 0.0),
        )
        pitch_arr = self._normalize_rc_centered_pwm(
            pitch_pwm,
            self._param_float(rc_params, f"RC{pitch_ch}_MIN", 1000.0),
            self._param_float(rc_params, f"RC{pitch_ch}_MAX", 2000.0),
            self._param_float(rc_params, f"RC{pitch_ch}_TRIM", 1500.0),
            reverse=self._param_float(rc_params, f"RC{pitch_ch}_REV", 1.0),
            deadzone=self._param_float(rc_params, f"RC{pitch_ch}_DZ", 0.0),
        )
        throttle_arr = self._normalize_rc_throttle_pwm(
            throttle_pwm,
            self._param_float(rc_params, f"RC{throttle_ch}_MIN", 1000.0),
            self._param_float(rc_params, f"RC{throttle_ch}_MAX", 2000.0),
            reverse=self._param_float(rc_params, f"RC{throttle_ch}_REV", 1.0),
        )
        yaw_arr = self._normalize_rc_centered_pwm(
            yaw_pwm,
            self._param_float(rc_params, f"RC{yaw_ch}_MIN", 1000.0),
            self._param_float(rc_params, f"RC{yaw_ch}_MAX", 2000.0),
            self._param_float(rc_params, f"RC{yaw_ch}_TRIM", 1500.0),
            reverse=self._param_float(rc_params, f"RC{yaw_ch}_REV", 1.0),
            deadzone=self._param_float(rc_params, f"RC{yaw_ch}_DZ", 0.0),
        )

        throttle_range = "0_1"

        manual_control = {
            "roll": roll_arr,
            "pitch": pitch_arr,
            "yaw": yaw_arr,
            "throttle": throttle_arr,
            "throttle_range": throttle_range,
            "available": bool(rc_topic),
        }

        return {
            "time": t_arr,
            "arming_origin": arming_origin,
            "tas": tas_arr,
            "gps_speed": gps_arr,
            "attitude": attitude,
            "flight_mode": flight_mode,
            "manual_control": manual_control,
        }

    @staticmethod
    def _normalize_aircraft_label(label):
        normalized = (label or "").strip().lower().replace("_", "-")
        if "fixed" in normalized:
            return "fixed-wing"
        if "multi" in normalized:
            return "multicopter"
        if "vtol" in normalized:
            return "vtol"
        return normalized

    @staticmethod
    def _workspace_has_data(workspace):
        # UI 수정 MainWindow._workspace_has_data 워크스페이스 UI 처리 변경
        plot_iter = workspace._iter_workspace_plots() if hasattr(workspace, "_iter_workspace_plots") else workspace.findChildren(AdvancedPlot)
        for plot in plot_iter:
            if plot.plotted_signals:
                return True
            if getattr(plot, "layout_special_spec", None):
                return True
        return False

    @staticmethod
    def _should_sync_workspace_time_range(action):
        # UI 수정 MainWindow._should_sync_workspace_time_range 워크스페이스 UI 처리 변경
        return str(action or "").strip() in {
            "auto_fit_view",
            "box_zoom",
            "reset_zoom",
            "right_drag_pan",
            "timeline_handle_change",
            "timeline_text_input",
            "viewbox_xrange_change",
            "wheel_zoom",
        }

    def _workspace_log_files(self, workspace):
        # UI 수정 MainWindow._workspace_log_files 워크스페이스 UI 처리 변경
        files = set()
        if not isinstance(workspace, Workspace):
            return files

        plot_iter = workspace._iter_workspace_plots() if hasattr(workspace, "_iter_workspace_plots") else workspace.findChildren(AdvancedPlot)
        for plot in plot_iter:
            try:
                special = getattr(plot, "layout_special_spec", None)
                if isinstance(special, dict):
                    special_file = str(special.get("file_name", "") or "").strip()
                    if special_file:
                        files.add(special_file)
                for uri in getattr(plot, "plotted_signals", {}).keys():
                    parsed = self._parse_render_uri(uri)
                    if parsed is None:
                        continue
                    file_name = str(parsed[0] or "").strip()
                    if file_name:
                        files.add(file_name)
            except RuntimeError:
                continue

        if not files:
            tab_idx = self.tab_widget.indexOf(workspace)
            if tab_idx >= 0:
                tab_text = str(self.tab_widget.tabText(tab_idx) or "")
                if tab_text.startswith("분석:"):
                    file_name = tab_text.split("|")[0].replace("분석:", "").strip()
                    if file_name:
                        files.add(file_name)
        return files

    def _workspace_primary_log_file(self, workspace):
        # UI 수정 MainWindow._workspace_primary_log_file 워크스페이스 UI 처리 변경
        log_files = sorted(self._workspace_log_files(workspace))
        if len(log_files) != 1:
            return None
        return log_files[0]

    def _iter_same_log_workspaces(self, source_workspace, file_name):
        # UI 수정 MainWindow._iter_same_log_workspaces 워크스페이스 UI 처리 변경
        if not file_name:
            return
        for tab_idx in range(self.tab_widget.count()):
            workspace = self.tab_widget.widget(tab_idx)
            if not isinstance(workspace, Workspace) or workspace is source_workspace:
                continue
            if self._workspace_primary_log_file(workspace) == file_name:
                yield workspace

    def _bootstrap_workspace_same_log_view(self, target_workspace, file_name, sync_cursor=True):
        # UI 수정 MainWindow._bootstrap_workspace_same_log_view 워크스페이스 UI 처리 변경
        if not isinstance(target_workspace, Workspace):
            return False
        file_name = str(file_name or "").strip()
        if not file_name:
            return False

        reference_workspace = None
        current_ws = self._active_workspace()
        if (
            isinstance(current_ws, Workspace)
            and current_ws is not target_workspace
            and self._workspace_primary_log_file(current_ws) == file_name
            and self._workspace_has_data(current_ws)
        ):
            reference_workspace = current_ws
        else:
            for workspace in self._iter_same_log_workspaces(target_workspace, file_name):
                if self._workspace_has_data(workspace):
                    reference_workspace = workspace
                    break

        ref_start = None
        ref_end = None
        ref_cursor_t = None

        if reference_workspace is not None:
            try:
                rs = float(reference_workspace.range_start)
                re_ = float(reference_workspace.range_end)
                if np.isfinite(rs) and np.isfinite(re_) and re_ > rs:
                    ref_start, ref_end = rs, re_
            except Exception:
                pass
            try:
                rc = float(reference_workspace.time_cursor.value())
                if np.isfinite(rc):
                    ref_cursor_t = rc
            except Exception:
                pass

        # Fallback: no peer workspace currently open for this log, but the user
        # may have analyzed this same log earlier (zoomed, shift+clicked) before
        # closing those tabs. _same_log_view_state preserves the last user-driven
        # range/cursor per file so newly opened workspaces stay consistent.
        if ref_start is None or ref_end is None:
            persisted = self._same_log_view_state.get(file_name)
            if isinstance(persisted, dict):
                try:
                    ps = float(persisted.get("range_start"))
                    pe = float(persisted.get("range_end"))
                    if np.isfinite(ps) and np.isfinite(pe) and pe > ps:
                        ref_start, ref_end = ps, pe
                except Exception:
                    pass
                if ref_cursor_t is None:
                    try:
                        pc = float(persisted.get("cursor_t"))
                        if np.isfinite(pc):
                            ref_cursor_t = pc
                    except Exception:
                        pass

        if ref_start is None or ref_end is None:
            return False

        applied = bool(
            target_workspace._set_time_range_ui_only(
                ref_start,
                ref_end,
                clamp_to_global=False,
            )
        )

        if sync_cursor and ref_cursor_t is not None:
            try:
                target_workspace._apply_external_cursor_time(ref_cursor_t, immediate_overlay=False)
            except Exception:
                pass

        return applied

    def _propagate_workspace_time_range(self, source_workspace, start_t, end_t, action=None):
        # UI 수정 MainWindow._propagate_workspace_time_range 워크스페이스 UI 처리 변경
        if self._same_log_time_sync_active:
            return 0
        if not isinstance(source_workspace, Workspace):
            return 0
        if not self._should_sync_workspace_time_range(action):
            return 0

        source_file = self._workspace_primary_log_file(source_workspace)
        if not source_file:
            return 0

        # Persist the user-driven range so newly opened workspaces for the
        # same log can pick it up via _bootstrap_workspace_same_log_view even
        # if no peer workspace is currently open.
        try:
            s = float(start_t)
            e = float(end_t)
            if np.isfinite(s) and np.isfinite(e) and e > s:
                slot = self._same_log_view_state.setdefault(source_file, {})
                slot["range_start"] = s
                slot["range_end"] = e
        except Exception:
            pass

        applied_count = 0
        self._same_log_time_sync_active = True
        try:
            for workspace in self._iter_same_log_workspaces(source_workspace, source_file):
                try:
                    if workspace._apply_external_time_range(start_t, end_t, clamp_to_global=True):
                        applied_count += 1
                except Exception:
                    continue
        finally:
            self._same_log_time_sync_active = False
        return applied_count

    def _propagate_workspace_playback_state(self, source_workspace, is_playing):
        # UI 수정 MainWindow._propagate_workspace_playback_state 워크스페이스 UI 처리 변경
        """Sync ▶/|| state across workspaces showing the same primary log.

        Only the source workspace runs the playback timer; peers mirror the
        UI state and rely on the existing same-log cursor propagation
        (`_propagate_workspace_cursor_time`) to track the playing time.
        """
        if self._same_log_playback_sync_active:
            return 0
        if not isinstance(source_workspace, Workspace):
            return 0

        source_file = self._workspace_primary_log_file(source_workspace)
        if not source_file:
            return 0

        applied_count = 0
        self._same_log_playback_sync_active = True
        try:
            for workspace in self._iter_same_log_workspaces(source_workspace, source_file):
                try:
                    if workspace._apply_external_playback_state(is_playing):
                        applied_count += 1
                except Exception:
                    continue
        finally:
            self._same_log_playback_sync_active = False
        return applied_count

    def _propagate_workspace_cursor_time(self, source_workspace, t, immediate_overlay=False, action=None):
        # UI 수정 MainWindow._propagate_workspace_cursor_time 워크스페이스 UI 처리 변경
        if self._same_log_cursor_sync_active:
            return 0
        if not isinstance(source_workspace, Workspace):
            return 0

        source_file = self._workspace_primary_log_file(source_workspace)
        if not source_file:
            return 0

        try:
            t = float(t)
        except Exception:
            return 0
        if not np.isfinite(t):
            return 0

        # Persist the user-driven cursor for same-log bootstrap fallback.
        slot = self._same_log_view_state.setdefault(source_file, {})
        slot["cursor_t"] = t

        applied_count = 0
        self._same_log_cursor_sync_active = True
        try:
            for workspace in self._iter_same_log_workspaces(source_workspace, source_file):
                try:
                    if workspace._apply_external_cursor_time(t, immediate_overlay=immediate_overlay):
                        applied_count += 1
                except Exception:
                    continue
        finally:
            self._same_log_cursor_sync_active = False
        return applied_count

    def _select_workspace_for_standard_panel(self, panel_title):
        # UI 수정 MainWindow._select_workspace_for_standard_panel 워크스페이스 UI 처리 변경
        current_ws = self.tab_widget.currentWidget()
        if not isinstance(current_ws, Workspace):
            self.add_workspace()
            return self.tab_widget.currentWidget()

        if not self._workspace_has_data(current_ws):
            return current_ws

        msg = QMessageBox(self)
        msg.setWindowTitle("표준 분석 패널")
        msg.setIcon(QMessageBox.Question)
        msg.setText(f"현재 Tab에 기존 그래프가 있습니다.\n'{panel_title}' 패널을 어디에 생성할까요?")
        btn_overwrite = msg.addButton("현재 탭 덮어쓰기", QMessageBox.AcceptRole)
        btn_new_tab = msg.addButton("새 탭에 생성", QMessageBox.ActionRole)
        btn_cancel = msg.addButton("취소", QMessageBox.RejectRole)
        msg.setDefaultButton(btn_new_tab)
        msg.exec()

        clicked = msg.clickedButton()
        if clicked == btn_cancel:
            return None
        if clicked == btn_new_tab:
            self.add_workspace()
            return self.tab_widget.currentWidget()
        if clicked == btn_overwrite:
            return current_ws
        return None

    def _get_dataset_for_standard_panel(self, target_aircraft_type):
        # UI 수정 MainWindow._get_dataset_for_standard_panel 레이아웃 UI 처리 변경
        target_key = self._normalize_aircraft_label(target_aircraft_type)
        if not self.loaded_datasets:
            return None, None, None

        if self.active_analysis_log and self.active_analysis_log in self.loaded_datasets:
            file_name = self.active_analysis_log
            aircraft_type = self.loaded_aircraft_types.get(file_name, "Unknown")
            return file_name, self.loaded_datasets[file_name], aircraft_type

        cur_idx = self.tab_widget.currentIndex()
        if cur_idx >= 0:
            tab_text = self.tab_widget.tabText(cur_idx)
            if tab_text.startswith("분석:"):
                current_file = tab_text.split("|")[0].replace("분석:", "").strip()
                if current_file in self.loaded_datasets:
                    aircraft_type = self.loaded_aircraft_types.get(current_file, "Unknown")
                    if self._normalize_aircraft_label(aircraft_type) == target_key:
                        return current_file, self.loaded_datasets[current_file], aircraft_type

        for file_name, dataset in self.loaded_datasets.items():
            aircraft_type = self.loaded_aircraft_types.get(file_name, "Unknown")
            if self._normalize_aircraft_label(aircraft_type) == target_key:
                return file_name, dataset, aircraft_type

        return None, None, None

    def _render_angle_pair_in_plot(self, plot, file_name, dataset, axis):
        # UI 수정 MainWindow._render_angle_pair_in_plot 그래프 UI 처리 변경
        sp_topic = self._find_topic_by_prefixes(dataset, "vehicle_attitude_setpoint")
        act_topic = self._find_topic_by_prefixes(dataset, "vehicle_attitude")
        sp_candidates = {
            "pitch": ["pitch_sp_euler", "pitch", "pitch_body"],
            "roll": ["roll_sp_euler", "roll", "roll_body"],
            "yaw": ["yaw_sp_euler", "yaw", "yaw_body"],
        }
        act_candidates = {
            "pitch": ["pitch_euler", "pitch"],
            "roll": ["roll_euler", "roll"],
            "yaw": ["yaw_euler", "yaw"],
        }
        sp_signal = self._find_signal_in_topic(dataset, sp_topic, sp_candidates.get(axis, []))
        act_signal = self._find_signal_in_topic(dataset, act_topic, act_candidates.get(axis, []))
        title = f"{self._axis_name(axis)} Angle (Actual) vs {self._axis_name(axis)} Angle Setpoint"
        return self._render_pair(
            plot,
            file_name,
            sp_topic,
            sp_signal,
            act_topic,
            act_signal,
            title,
            show_message=False,
        )

    def _render_rate_pair_in_plot(self, plot, file_name, dataset, axis):
        # UI 수정 MainWindow._render_rate_pair_in_plot 그래프 UI 처리 변경
        sp_topic = self._find_topic_by_prefixes(dataset, "vehicle_rates_setpoint")
        act_topic = self._find_topic_by_prefixes(dataset, "vehicle_angular_velocity")
        idx_map = {"roll": 0, "pitch": 1, "yaw": 2}
        idx = idx_map.get(axis, 0)
        sp_signal = self._find_signal_in_topic(dataset, sp_topic, [axis, f"xyz[{idx}]"])
        act_signal = self._find_signal_in_topic(dataset, act_topic, [f"xyz[{idx}]", axis])
        title = f"{self._axis_name(axis)} Angular Rate (Actual) vs {self._axis_name(axis)} Angular Rate Setpoint"
        return self._render_pair(
            plot,
            file_name,
            sp_topic,
            sp_signal,
            act_topic,
            act_signal,
            title,
            show_message=False,
        )

    @staticmethod
    def _iter_topics_by_prefixes(dataset, prefixes):
        if not dataset or not getattr(dataset, "topics", None):
            return
        if isinstance(prefixes, str):
            prefixes = [prefixes]
        seen = set()
        for prefix in prefixes:
            if prefix in dataset.topics and prefix not in seen:
                seen.add(prefix)
                yield prefix
            for topic_name in dataset.topics.keys():
                if topic_name in seen:
                    continue
                if str(topic_name).startswith(prefix):
                    seen.add(topic_name)
                    yield topic_name

    def _find_transition_mode_source(self, dataset):
        candidates = [
            "in_transition_mode",
            "in_transition_mode_flag",
            "in_transition_to_fw",
            "in_transition_to_fw_flag",
            "in_transition_back",
            "in_transition_back_flag",
        ]
        for topic_name in self._iter_topics_by_prefixes(dataset, ["vtol_vehicle_status", "vehicle_status"]):
            signal_name = self._find_signal_in_topic(dataset, topic_name, candidates)
            if signal_name:
                return topic_name, signal_name
        return None, None

    @staticmethod
    def _get_topic_signal_xy(dataset, topic_name, signal_name, x_axis_col="timestamp_sec"):
        if (
            not dataset
            or not topic_name
            or not signal_name
            or topic_name not in getattr(dataset, "topics", {})
        ):
            return None, None
        topic = dataset.topics.get(topic_name)
        df = getattr(topic, "dataframe", None)
        if df is None or x_axis_col not in df.columns or signal_name not in df.columns:
            return None, None
        try:
            x = np.asarray(df[x_axis_col].to_numpy(), dtype=np.float64)
            y = np.asarray(df[signal_name].to_numpy(), dtype=np.float64)
        except Exception:
            return None, None
        finite = np.isfinite(x) & np.isfinite(y)
        if not np.any(finite):
            return None, None
        x = x[finite]
        y = y[finite]
        order = np.argsort(x)
        x = x[order]
        y = y[order]
        if x.size == 0:
            return None, None
        unique = np.concatenate(([True], np.diff(x) > 1e-9))
        x = x[unique]
        y = y[unique]
        if x.size == 0:
            return None, None
        return x, y

    @staticmethod
    def _get_plot_signal_y_bounds(plot):
        # UI 수정 MainWindow._get_plot_signal_y_bounds 그래프 UI 처리 변경
        y_min = None
        y_max = None
        for cache in (getattr(plot, "signal_cache", {}) or {}).values():
            try:
                values = np.asarray(cache.get("y"), dtype=np.float64)
            except Exception:
                continue
            if values.size == 0:
                continue
            finite = values[np.isfinite(values)]
            if finite.size == 0:
                continue
            local_min = float(np.min(finite))
            local_max = float(np.max(finite))
            y_min = local_min if y_min is None else min(y_min, local_min)
            y_max = local_max if y_max is None else max(y_max, local_max)
        if y_min is None or y_max is None:
            return None, None
        return y_min, y_max

    def _add_transition_mode_overlay_to_plot(self, plot, dataset, color="#FF8800"):
        # UI 수정 MainWindow._add_transition_mode_overlay_to_plot 그래프 UI 처리 변경
        topic_name, signal_name = self._find_transition_mode_source(dataset)
        if not topic_name or not signal_name:
            return False

        x, transition = self._get_topic_signal_xy(dataset, topic_name, signal_name)
        if x is None or transition is None or len(x) == 0:
            return False

        y_min, y_max = self._get_plot_signal_y_bounds(plot)
        if y_min is None or y_max is None:
            try:
                view_range = plot.plot.plotItem.vb.viewRange()[1]
                y_min = float(view_range[0])
                y_max = float(view_range[1])
            except Exception:
                return False
        if not (np.isfinite(y_min) and np.isfinite(y_max)):
            return False

        span = float(y_max - y_min)
        if not np.isfinite(span) or span <= 1e-9:
            center = float(y_max)
            span = max(abs(center), 1.0)
            y_min = center - 0.5 * span
            y_max = center + 0.5 * span

        # Draw the transition overlay from a 0 baseline so it reads like a
        # regular on/off state over the attitude/rate data, while still being
        # scaled into the visible range of the current plot.
        baseline = 0.0
        if not (y_min <= baseline <= y_max):
            baseline = y_min + span * 0.08
        positive_headroom = float(y_max - baseline)
        if not np.isfinite(positive_headroom) or positive_headroom <= 0.15:
            return False
        amplitude = min(max(span * 0.18, 0.8), positive_headroom * 0.9)
        if not np.isfinite(amplitude) or amplitude <= 0.0:
            return False

        transition01 = np.clip(np.rint(transition), 0.0, 1.0)
        overlay_y = np.where(np.isfinite(transition), baseline + transition01 * amplitude, np.nan)
        if not np.any(np.isfinite(overlay_y)):
            return False

        overlay_item = pg.PlotCurveItem(
            x=x,
            y=overlay_y,
            pen=pg.mkPen(color=color, width=1.4),
            connect="finite",
        )
        try:
            overlay_item.setSkipFiniteCheck(True)
        except Exception:
            pass
        try:
            overlay_item.setZValue(20)
        except Exception:
            pass
        plot.plot.addItem(overlay_item, ignoreBounds=True)
        plot._add_click_toggle_legend_item(overlay_item, "in_transition_mode")
        return True

    def _render_angle_pair_with_transition_overlay_in_plot(self, plot, file_name, dataset, axis):
        # UI 수정 MainWindow._render_angle_pair_with_transition_overlay_in_plot 그래프 UI 처리 변경
        rendered = self._render_angle_pair_in_plot(plot, file_name, dataset, axis)
        if rendered:
            self._add_transition_mode_overlay_to_plot(plot, dataset, color="#FF8800")
        return rendered

    def _render_rate_pair_with_transition_overlay_in_plot(self, plot, file_name, dataset, axis):
        # UI 수정 MainWindow._render_rate_pair_with_transition_overlay_in_plot 그래프 UI 처리 변경
        rendered = self._render_rate_pair_in_plot(plot, file_name, dataset, axis)
        if rendered:
            self._add_transition_mode_overlay_to_plot(plot, dataset, color="#FF8800")
        return rendered

    def _render_altitude_tracking_in_plot(self, plot, file_name, dataset):
        # UI 수정 MainWindow._render_altitude_tracking_in_plot 그래프 UI 처리 변경
        sp_topic = self._find_topic_by_prefixes(dataset, "vehicle_local_position_setpoint")
        act_topic = self._find_topic_by_prefixes(dataset, "vehicle_local_position")
        # Prefer the math_engine-generated up-positive virtual signals so the
        # plot reads as "altitude up = positive". Fall back to NED z only when
        # the virtual signal is unavailable.
        sp_signal = self._find_signal_in_topic(dataset, sp_topic, ["alt_sp_up"])
        act_signal = self._find_signal_in_topic(dataset, act_topic, ["alt_up"])
        if sp_signal is None:
            sp_signal = self._find_signal_in_topic(dataset, sp_topic, ["z_deriv", "z"])
        if act_signal is None:
            act_signal = self._find_signal_in_topic(dataset, act_topic, ["z"])
        title = "Altitude vs Altitude Setpoint"
        return self._render_pair(
            plot,
            file_name,
            sp_topic,
            sp_signal,
            act_topic,
            act_signal,
            title,
            show_message=False,
        )

    def _render_speed_pair_in_plot(self, plot, file_name, dataset):
        # UI 수정 MainWindow._render_speed_pair_in_plot 그래프 UI 처리 변경
        ground_topic = self._find_topic_by_prefixes(dataset, ["vehicle_gps_position", "vehicle_local_position"])
        ground_signal = self._find_signal_in_topic(dataset, ground_topic, ["vel_m_s", "ground_speed_mag", "vx"])
        # Use validated TAS first; fall back through TECS estimate / raw airspeed.
        air_topic = self._find_topic_by_prefixes(dataset, ["airspeed_validated", "tecs_status", "airspeed"])
        air_signal = self._find_signal_in_topic(
            dataset,
            air_topic,
            ["true_airspeed_m_s", "true_airspeed_filtered", "indicated_airspeed_m_s"],
        )
        return self._render_pair(
            plot,
            file_name,
            air_topic,
            air_signal,
            ground_topic,
            ground_signal,
            "Airspeed vs GPS Ground Speed",
            show_message=False,
        )

    def _render_tecs_in_plot(self, plot, file_name, dataset):
        # UI 수정 MainWindow._render_tecs_in_plot 그래프 UI 처리 변경
        tecs_topic = self._find_topic_by_prefixes(dataset, "tecs_status")
        sp_signal = self._find_signal_in_topic(dataset, tecs_topic, ["throttle_sp"])
        act_signal = self._find_signal_in_topic(dataset, tecs_topic, ["throttle_trim"])
        return self._render_pair(
            plot,
            file_name,
            tecs_topic,
            sp_signal,
            tecs_topic,
            act_signal,
            "TECS Throttle Trim vs Throttle Setpoint",
            show_message=False,
        )

    def _render_fft_in_plot(self, plot, file_name, dataset):
        # UI 수정 MainWindow._render_fft_in_plot 그래프 UI 처리 변경
        accel_topic = self._find_topic_by_prefixes(dataset, "sensor_combined")
        if not accel_topic:
            return False

        cols = dataset.topics[accel_topic].dataframe.columns
        candidates = [
            ("accelerometer_m_s2[0]", "#FF6B6B"),
            ("accelerometer_m_s2[1]", "#33CC66"),
            ("accelerometer_m_s2[2]", "#4DA3FF"),
        ]

        plot.clear_plot_data()
        plot.plot.setTitle("Vibration Analysis: Accel FFT")
        rendered = False
        for col, color in candidates:
            if col in cols:
                rendered = plot.render_signal(file_name, accel_topic, col, color=color, is_fft=True) or rendered
        if rendered:
            plot.auto_fit_view()
        return rendered

    def _render_2d_flight_path_in_plot(self, plot, file_name, dataset):
        # UI 수정 MainWindow._render_2d_flight_path_in_plot 그래프 UI 처리 변경
        local_topic = self._find_topic_by_prefixes(dataset, "vehicle_local_position")
        global_topic = self._find_topic_by_prefixes(dataset, "vehicle_global_position")
        topic = local_topic or global_topic
        if not topic:
            return False

        display_lat = None
        display_lon = None
        display_alt = None
        comparison_curves = []
        primary_curve_name = "2D Flight Path"
        comparison_topic = None
        comparison_x_signal = None
        comparison_y_signal = None

        if "global" in topic:
            lon_signal = self._find_signal_in_topic(dataset, topic, ["lon", "longitude_deg"])
            lat_signal = self._find_signal_in_topic(dataset, topic, ["lat", "latitude_deg"])
            alt_signal = self._find_signal_in_topic(dataset, topic, ["alt", "altitude_msl_m", "altitude"])
            if not lon_signal or not lat_signal:
                return False
            df = dataset.topics[topic].dataframe
            if "timestamp_sec" not in df.columns:
                return False
            t = np.asarray(df["timestamp_sec"].to_numpy(), dtype=np.float64)
            lat = np.asarray(df[lat_signal].to_numpy(), dtype=np.float64)
            lon = np.asarray(df[lon_signal].to_numpy(), dtype=np.float64)
            mask = np.isfinite(t) & np.isfinite(lat) & np.isfinite(lon)
            z = None
            if alt_signal:
                alt = np.asarray(df[alt_signal].to_numpy(), dtype=np.float64)
                mask = mask & np.isfinite(alt)
                z = alt
            t = t[mask]
            lat = lat[mask]
            lon = lon[mask]
            display_lat = lat.copy()
            display_lon = lon.copy()
            if z is not None:
                z = z[mask]
                display_alt = z.copy()
                z = z - float(np.median(z))
            if len(t) < 2:
                return False
            lat0 = float(np.median(lat))
            lon0 = float(np.median(lon))
            earth_r = 6378137.0
            deg_to_rad = np.pi / 180.0
            north = (lat - lat0) * deg_to_rad * earth_r
            east = (lon - lon0) * deg_to_rad * earth_r * np.cos(lat0 * deg_to_rad)
            # (2026-05-28) 위성 배경 헬퍼가 같은 원점으로 정렬할 수 있도록 plot 에 저장.
            try:
                plot._geo_origin_latlon = (lat0, lon0)
            except Exception:
                pass
        else:
            x_signal = self._find_signal_in_topic(dataset, topic, ["x", "north", "position[0]"])
            y_signal = self._find_signal_in_topic(dataset, topic, ["y", "east", "position[1]"])
            z_signal = self._find_signal_in_topic(dataset, topic, ["z"])
            if z_signal is None:
                z_signal = self._find_signal_in_topic(dataset, topic, ["alt", "alt_up", "position[2]"])
            alt_signal = z_signal
            if not x_signal or not y_signal:
                return False
            df = dataset.topics[topic].dataframe
            if "timestamp_sec" not in df.columns:
                return False
            t = np.asarray(df["timestamp_sec"].to_numpy(), dtype=np.float64)
            x = np.asarray(df[x_signal].to_numpy(), dtype=np.float64)
            y = np.asarray(df[y_signal].to_numpy(), dtype=np.float64)
            mask = np.isfinite(t) & np.isfinite(x) & np.isfinite(y)
            z = None
            if z_signal:
                z_raw = np.asarray(df[z_signal].to_numpy(), dtype=np.float64)
                mask = mask & np.isfinite(z_raw)
                # local_position.z is NED (positive = down). Flip for both the
                # plot z buffer (already up-positive) and the value-overlay
                # display_alt so the value box reads positive when above takeoff.
                z = -z_raw
                display_alt = z.copy()
            t = t[mask]
            north = x[mask]
            east = y[mask]
            if z is not None:
                z = z[mask]
            if display_alt is not None:
                display_alt = display_alt[mask]
            # (2026-05-28) Local 모드: vehicle_local_position.ref_lat/ref_lon = NED 원점
            # → 위성 배경 정렬 기준점.
            try:
                ref_df = dataset.topics[topic].dataframe
                if "ref_lat" in ref_df.columns and "ref_lon" in ref_df.columns:
                    ref_lat_arr = ref_df["ref_lat"].to_numpy().astype("float64")
                    ref_lon_arr = ref_df["ref_lon"].to_numpy().astype("float64")
                    valid_ref = (
                        np.isfinite(ref_lat_arr) & np.isfinite(ref_lon_arr)
                        & (ref_lat_arr != 0) & (ref_lon_arr != 0)
                    )
                    if valid_ref.any():
                        idx_ref = int(np.argmax(valid_ref))
                        plot._geo_origin_latlon = (float(ref_lat_arr[idx_ref]), float(ref_lon_arr[idx_ref]))
            except Exception:
                pass

            # Prefer displaying real GPS lat/lon/alt values in the 2D path info box.
            g_topic = self._find_topic_by_prefixes(dataset, "vehicle_global_position")
            if g_topic and g_topic in dataset.topics:
                g_lat_signal = self._find_signal_in_topic(dataset, g_topic, ["lat", "latitude_deg"])
                g_lon_signal = self._find_signal_in_topic(dataset, g_topic, ["lon", "longitude_deg"])
                g_df = dataset.topics[g_topic].dataframe
                if (
                    g_df is not None
                    and "timestamp_sec" in g_df.columns
                    and g_lat_signal in g_df.columns
                    and g_lon_signal in g_df.columns
                ):
                    tg = np.asarray(g_df["timestamp_sec"].to_numpy(), dtype=np.float64)
                    latg = np.asarray(g_df[g_lat_signal].to_numpy(), dtype=np.float64)
                    long = np.asarray(g_df[g_lon_signal].to_numpy(), dtype=np.float64)
                    g_mask = np.isfinite(tg) & np.isfinite(latg) & np.isfinite(long)
                    tg = tg[g_mask]
                    latg = latg[g_mask]
                    long = long[g_mask]
                    if len(tg) >= 2:
                        order = np.argsort(tg)
                        tg = tg[order]
                        latg = latg[order]
                        long = long[order]
                        unique = np.concatenate(([True], np.diff(tg) > 1e-9))
                        tg = tg[unique]
                        latg = latg[unique]
                        long = long[unique]
                        if len(tg) >= 2:
                            display_lat = np.interp(t, tg, latg, left=np.nan, right=np.nan)
                            display_lon = np.interp(t, tg, long, left=np.nan, right=np.nan)

            sp_topic = self._find_topic_by_prefixes(dataset, "vehicle_local_position_setpoint")
            if sp_topic and sp_topic in dataset.topics:
                sp_x_signal = self._find_signal_in_topic(dataset, sp_topic, ["x", "north", "position[0]"])
                sp_y_signal = self._find_signal_in_topic(dataset, sp_topic, ["y", "east", "position[1]"])
                sp_df = dataset.topics[sp_topic].dataframe
                if (
                    sp_df is not None
                    and "timestamp_sec" in sp_df.columns
                    and sp_x_signal in sp_df.columns
                    and sp_y_signal in sp_df.columns
                ):
                    sp_t = np.asarray(sp_df["timestamp_sec"].to_numpy(), dtype=np.float64)
                    sp_x = np.asarray(sp_df[sp_x_signal].to_numpy(), dtype=np.float64)
                    sp_y = np.asarray(sp_df[sp_y_signal].to_numpy(), dtype=np.float64)
                    sp_mask = np.isfinite(sp_t) & np.isfinite(sp_x) & np.isfinite(sp_y)
                    sp_t = sp_t[sp_mask]
                    sp_x = sp_x[sp_mask]
                    sp_y = sp_y[sp_mask]
                    if len(sp_t) >= 2:
                        order = np.argsort(sp_t)
                        sp_t = sp_t[order]
                        sp_x = sp_x[order]
                        sp_y = sp_y[order]
                        unique = np.concatenate(([True], np.diff(sp_t) > 1e-9))
                        sp_t = sp_t[unique]
                        sp_x = sp_x[unique]
                        sp_y = sp_y[unique]
                        if len(sp_t) >= 2:
                            comparison_curves.append({
                                "key": "setpoint",
                                "name": "Setpoint Path",
                                # Map convention (2026-05-11): x = East, y = North.
                                "t": sp_t,
                                "x": sp_y,
                                "y": sp_x,
                                "color": "#FF4D4D",
                                "style": "dash",
                                "width": 2.0,
                            })
                            primary_curve_name = "Actual Path"
                            comparison_topic = sp_topic
                            comparison_x_signal = sp_x_signal
                            comparison_y_signal = sp_y_signal

        ok = plot.render_2d_flight_path(
            east,    # screen X axis (map convention, 2026-05-11)
            north,   # screen Y axis
            title="2D Flight Path",
            timestamps=t,
            altitude=z,
            display_lat=display_lat,
            display_lon=display_lon,
            display_alt=display_alt,
            comparison_curves=comparison_curves,
            primary_curve_name=primary_curve_name,
        )
        if ok:
            plot.layout_special_spec = {
                "kind": "flight_path_2d",
                "file_name": file_name,
                "topic": topic,
                "x_signal": lon_signal if "global" in topic else x_signal,
                "y_signal": lat_signal if "global" in topic else y_signal,
                "z_signal": alt_signal if "global" in topic else z_signal,
                "time_signal": "timestamp_sec",
            }
            if comparison_topic and comparison_x_signal and comparison_y_signal:
                plot.layout_special_spec["comparison_topic"] = comparison_topic
                plot.layout_special_spec["comparison_x_signal"] = comparison_x_signal
                plot.layout_special_spec["comparison_y_signal"] = comparison_y_signal
            plot._sync_2d_path_style_to_layout_spec()
        return ok

    def _render_3d_flight_path_in_plot(self, plot, file_name, dataset):
        # UI 수정 MainWindow._render_3d_flight_path_in_plot 그래프 UI 처리 변경
        local_topic = self._find_topic_by_prefixes(dataset, "vehicle_local_position")
        global_topic = self._find_topic_by_prefixes(dataset, "vehicle_global_position")

        topic = None
        x_signal = None
        y_signal = None
        using_local_xy = False

        if local_topic and local_topic in dataset.topics:
            lx = self._find_signal_in_topic(dataset, local_topic, ["x", "north", "position[0]"])
            ly = self._find_signal_in_topic(dataset, local_topic, ["y", "east", "position[1]"])
            if lx and ly:
                topic = local_topic
                x_signal = lx
                y_signal = ly
                using_local_xy = True

        if topic is None and global_topic and global_topic in dataset.topics:
            gx = self._find_signal_in_topic(dataset, global_topic, ["lon", "longitude_deg"])
            gy = self._find_signal_in_topic(dataset, global_topic, ["lat", "latitude_deg"])
            if gx and gy:
                topic = global_topic
                x_signal = gx
                y_signal = gy
                using_local_xy = False

        if topic is None or not x_signal or not y_signal:
            return False

        # Use vehicle_local_position.z as primary altitude source for both 2D/3D paths.
        z_topic = local_topic if local_topic and local_topic in dataset.topics else topic
        z_signal = self._find_signal_in_topic(dataset, z_topic, ["z"]) if z_topic else None
        if z_signal is None:
            z_topic = topic
            z_signal = self._find_signal_in_topic(
                dataset,
                z_topic,
                ["z", "alt", "altitude_msl_m", "altitude", "alt_up", "position[2]"],
            )
        if z_signal is None:
            return False

        try:
            df_xy = dataset.topics[topic].dataframe
            t = None
            if "timestamp_sec" in df_xy.columns:
                try:
                    t = np.asarray(df_xy["timestamp_sec"].to_numpy(), dtype=np.float64)
                except Exception:
                    t = None

            x_raw = np.asarray(df_xy[x_signal].to_numpy(), dtype=np.float64)
            y_raw = np.asarray(df_xy[y_signal].to_numpy(), dtype=np.float64)
            base_mask = np.isfinite(x_raw) & np.isfinite(y_raw)
            if t is not None and len(t) == len(base_mask):
                base_mask = base_mask & np.isfinite(t)

            x_raw = x_raw[base_mask]
            y_raw = y_raw[base_mask]
            if t is not None and len(t) == len(base_mask):
                t = t[base_mask]
            else:
                t = None

            if len(x_raw) == 0:
                return False

            if z_topic == topic:
                z_raw = np.asarray(df_xy[z_signal].to_numpy(), dtype=np.float64)
                z_raw = z_raw[base_mask]
                finite_z = np.isfinite(z_raw)
                x_raw = x_raw[finite_z]
                y_raw = y_raw[finite_z]
                z_raw = z_raw[finite_z]
                if t is not None and len(t) == len(finite_z):
                    t = t[finite_z]
            else:
                if t is None:
                    return False
                df_z = dataset.topics[z_topic].dataframe
                if df_z is None or "timestamp_sec" not in df_z.columns or z_signal not in df_z.columns:
                    return False
                tz = np.asarray(df_z["timestamp_sec"].to_numpy(), dtype=np.float64)
                zv = np.asarray(df_z[z_signal].to_numpy(), dtype=np.float64)
                z_mask = np.isfinite(tz) & np.isfinite(zv)
                tz = tz[z_mask]
                zv = zv[z_mask]
                if len(tz) < 2:
                    return False
                order = np.argsort(tz)
                tz = tz[order]
                zv = zv[order]
                unique = np.concatenate(([True], np.diff(tz) > 1e-9))
                tz = tz[unique]
                zv = zv[unique]
                if len(tz) < 2:
                    return False
                z_raw = np.interp(t, tz, zv, left=np.nan, right=np.nan)
                finite_z = np.isfinite(z_raw)
                x_raw = x_raw[finite_z]
                y_raw = y_raw[finite_z]
                z_raw = z_raw[finite_z]
                t = t[finite_z]

            if len(x_raw) < 2:
                return False

            if using_local_xy:
                # PX4 local_position is NED; all path renderers consume ENU.
                x, y, z = local_ned_to_enu(x_raw, y_raw, z_raw)
                frame_name = "local_ENU_m(local_z)"
            else:
                # Convert global lon/lat to the same ENU renderer contract.
                lat = y_raw
                lon = x_raw
                x, y, global_up = global_lla_to_enu(lat, lon, z_raw)
                # Prefer local_position.z-derived altitude when available.
                if z_topic == local_topic and z_signal == "z":
                    z = -(z_raw - float(z_raw[0]))
                    frame_name = "globalXY+localZ_ENU_m"
                else:
                    z = global_up
                    frame_name = "global_ENU_m"

            try:
                x_span = float(np.max(x) - np.min(x))
                y_span = float(np.max(y) - np.min(y))
                z_span = float(np.max(z) - np.min(z))
                print(
                    f"[3D][Source] topic={topic} z_topic={z_topic} frame={frame_name} "
                    f"span(x,y,z)=({x_span:.3f}, {y_span:.3f}, {z_span:.3f})"
                )
            except Exception:
                pass

            value_extras = None
            if t is not None and len(t) > 0:
                try:
                    value_extras = self._build_3d_path_value_extras(dataset, t, x, y, z)
                except Exception:
                    traceback.print_exc()
                    value_extras = None

            plot.configure_true_3d_vehicle_marker(
                detected_aircraft_type=self.loaded_aircraft_types.get(file_name, "Unknown"),
                refresh=False,
            )

            ok = plot.render_3d_path(
                x,
                y,
                z,
                "3D Flight Path (Interactive)",
                timestamps=t,
                value_extras=value_extras,
            )
            if ok:
                special_kind = "true_3d_path" if getattr(plot, "_true_3d_enabled", False) else "projected_3d_path"
                plot.layout_special_spec = {
                    "kind": special_kind,
                    "file_name": file_name,
                    "topic": topic,
                    "x_signal": x_signal,
                    "y_signal": y_signal,
                    "z_topic": z_topic,
                    "z_signal": z_signal,
                    "time_signal": "timestamp_sec",
                    "line_color": plot._3d_path_style["color"].name(),
                    "line_style": plot._3d_path_style.get("style", "solid"),
                    "line_width": float(plot._3d_path_style.get("width", 2.6)),
                }
                plot._sync_3d_style_to_layout_spec()
            return ok
        except Exception:
            traceback.print_exc()
            return False

    def _render_gps_speed_in_plot(self, plot, file_name, dataset):
        # UI 수정 MainWindow._render_gps_speed_in_plot 그래프 UI 처리 변경
        topic = self._find_topic_by_prefixes(dataset, ["vehicle_gps_position", "vehicle_local_position"])
        signal = self._find_signal_in_topic(dataset, topic, ["vel_m_s", "ground_speed_mag", "speed", "vx"])
        if not topic or not signal:
            return False

        plot.clear_plot_data()
        plot.plot.setTitle("GPS Speed")
        ok = plot.render_signal(file_name, topic, signal, color="#4DA3FF")
        if ok:
            plot.auto_fit_view()
        return ok

    def _render_transition_mode_in_plot(self, plot, file_name, dataset):
        # UI 수정 MainWindow._render_transition_mode_in_plot 그래프 UI 처리 변경
        topic, signal_name = self._find_transition_mode_source(dataset)
        if not topic or not signal_name:
            return False

        plot.clear_plot_data()
        plot.plot.setTitle("Transition Mode")
        rendered = plot.render_signal(file_name, topic, signal_name, color="#FF8800")
        if rendered:
            plot.auto_fit_view()
            self._reset_tools_workspace_to_full_range(plot)
        return rendered

