    def _render_telemetry_signal_in_plot(self, plot, file_name, dataset, ts_topic, candidates, title, color):
        # UI 수정 MainWindow._render_telemetry_signal_in_plot 그래프 UI 처리 변경
        """Render a single telemetry_status signal into one Auto Panels plot.

        Mirrors the lightweight contract used by other `_render_X_in_plot`
        helpers (sets title, calls render_signal, fits view) so it can plug
        straight into a builder list. Returns False when topic/signal is
        missing — the panel reports it as a missing tile, same as e.g.
        Accel FFT does on a log without sensor_combined.
        """
        plot.clear_plot_data()
        plot.plot.setTitle(title)
        if not ts_topic:
            return False
        signal_name = self._find_signal_in_topic(dataset, ts_topic, list(candidates))
        if not signal_name:
            return False
        ok = plot.render_signal(file_name, ts_topic, signal_name, color=color)
        if ok:
            plot.auto_fit_view()
        return ok

    def _render_input_rc_signal_in_plot(self, plot, file_name, dataset, rc_topic, candidates, title, color):
        # UI 수정 MainWindow._render_input_rc_signal_in_plot 그래프 UI 처리 변경
        plot.clear_plot_data()
        plot.plot.setTitle(title)
        if not rc_topic:
            return False
        signal_name = self._find_signal_in_topic(dataset, rc_topic, list(candidates))
        if not signal_name:
            return False
        ok = plot.render_signal(file_name, rc_topic, signal_name, color=color)
        if ok:
            plot.auto_fit_view()
        return ok

